from google.colab import drive
drive.mount('/content/drive')

import pandas as pd
import torch
from torch.utils.data import Dataset, DataLoader
from torchvision import transforms
from PIL import Image

# ==========================================
# 1. CSV PATHS
# ==========================================

TRAIN_CSV = "/content/drive/MyDrive/archive (1)/train_final.csv"
VAL_CSV   = "/content/drive/MyDrive/archive (1)/val_final.csv"
TEST_CSV  = "/content/drive/MyDrive/archive (1)/test_final.csv"

train_df = pd.read_csv(TRAIN_CSV)
val_df   = pd.read_csv(VAL_CSV)
test_df  = pd.read_csv(TEST_CSV)

# ==========================================
# 2. LABEL MAPPING
# ==========================================

label2idx = {
    "Normal": 0,
    "Ischemia": 1,
    "Bleeding": 2
}

idx2label = {
    0: "Normal",
    1: "Ischemia",
    2: "Bleeding"
}

# ==========================================
# 3. TRANSFORMS
# ==========================================

train_transform = transforms.Compose([
    transforms.Resize((224, 224)),
    transforms.RandomHorizontalFlip(),
    transforms.RandomRotation(15),
    transforms.ColorJitter(
        brightness=0.2,
        contrast=0.2
    ),
    transforms.ToTensor(),
    transforms.Normalize(
        mean=[0.485, 0.456, 0.406],
        std=[0.229, 0.224, 0.225]
    )
])

val_test_transform = transforms.Compose([
    transforms.Resize((224, 224)),
    transforms.ToTensor(),
    transforms.Normalize(
        mean=[0.485, 0.456, 0.406],
        std=[0.229, 0.224, 0.225]
    )
])

# ==========================================
# 4. DATASET CLASS
# ==========================================

class StrokeDataset(Dataset):

    def __init__(self, dataframe, transform=None):
        self.df = dataframe.reset_index(drop=True)
        self.transform = transform

    def __len__(self):
        return len(self.df)

    def __getitem__(self, idx):

        row = self.df.iloc[idx]

        image = Image.open(
            row["image_path"]
        ).convert("RGB")

        if self.transform:
            image = self.transform(image)

        label = label2idx[row["label"]]

        return image, label

# ==========================================
# 5. CREATE DATASETS
# ==========================================

train_dataset = StrokeDataset(
    train_df, train_transform
)

val_dataset = StrokeDataset(
    val_df, val_test_transform
)

test_dataset = StrokeDataset(
    test_df, val_test_transform
)

# ==========================================
# 6. DATALOADERS
# ==========================================

BATCH_SIZE = 16
NUM_WORKERS = 2

train_loader = DataLoader(
    train_dataset,
    batch_size=16,
    shuffle=True,
    num_workers=2,
    pin_memory=True,
    persistent_workers=True,
    prefetch_factor=2
)

val_loader = DataLoader(
    val_dataset,
    batch_size=16,
    shuffle=False,
    num_workers=2,
    pin_memory=True,
    persistent_workers=True,
    prefetch_factor=2
)

test_loader = DataLoader(
    test_dataset,
    batch_size=16,
    shuffle=False,
    num_workers=2,
    pin_memory=True,
    persistent_workers=True,
    prefetch_factor=2
)

# ==========================================
# 7. VERIFY DATA
# ==========================================

print("Train Images:", len(train_dataset))
print("Validation Images:", len(val_dataset))
print("Test Images:", len(test_dataset))

print("\nClass Distribution:")
print("\nTrain:")
print(train_df["label"].value_counts())

print("\nValidation:")
print(val_df["label"].value_counts())

print("\nTest:")
print(test_df["label"].value_counts())

print("\nData Loading Completed Successfully!")

# ============================================================
# MAXVIT-T: STRATIFIED 5-FOLD CROSS VALIDATION
# Based on Original MaxViT Training Configuration (Cell 79)
# ============================================================

import os
import random
import numpy as np
import pandas as pd
import torch
import torch.nn as nn
import torch.optim as optim

from PIL import Image
from torch.utils.data import Dataset, DataLoader
from torchvision import transforms
from torchvision.models import maxvit_t, MaxVit_T_Weights

from sklearn.model_selection import StratifiedKFold
from sklearn.metrics import (
    accuracy_score,
    precision_score,
    recall_score,
    f1_score,
    classification_report
)

# ============================================================
# 1. CONFIGURATION
# ============================================================

SEED = 42
NUM_FOLDS = 5
NUM_EPOCHS = 10
BATCH_SIZE = 16
NUM_WORKERS = 2

LEARNING_RATE = 3e-4
WEIGHT_DECAY = 1e-4

DEVICE = torch.device(
    "cuda" if torch.cuda.is_available() else "cpu"
)

SAVE_DIR = "/content/drive/MyDrive/Stroke_MaxViT_5Fold"
os.makedirs(SAVE_DIR, exist_ok=True)

print("Device:", DEVICE)

# ============================================================
# 2. REPRODUCIBILITY
# ============================================================

def set_seed(seed):
    random.seed(seed)
    np.random.seed(seed)
    torch.manual_seed(seed)

    if torch.cuda.is_available():
        torch.cuda.manual_seed_all(seed)

    torch.backends.cudnn.deterministic = True
    torch.backends.cudnn.benchmark = False


set_seed(SEED)

# ============================================================
# 3. DATA PREPARATION
# Keep TEST SET completely separate
# ============================================================

# Use original train + validation data only
cv_df = pd.concat(
    [train_df, val_df],
    ignore_index=True
).reset_index(drop=True)

label2idx = {
    "Normal": 0,
    "Ischemia": 1,
    "Bleeding": 2
}

idx2label = {
    0: "Normal",
    1: "Ischemia",
    2: "Bleeding"
}

cv_df["label_id"] = cv_df["label"].map(label2idx)

if cv_df["label_id"].isna().any():
    raise ValueError("Unknown labels found in dataset.")

cv_df["label_id"] = cv_df["label_id"].astype(int)

print("\nTotal CV images:", len(cv_df))
print("\nClass distribution:")
print(cv_df["label"].value_counts())

print("\nIndependent test images:", len(test_df))

# ============================================================
# 4. TRANSFORMS
# Same as original Cell 53
# ============================================================

train_transform = transforms.Compose([
    transforms.Resize((224, 224)),
    transforms.RandomHorizontalFlip(),
    transforms.RandomRotation(15),
    transforms.ColorJitter(
        brightness=0.2,
        contrast=0.2
    ),
    transforms.ToTensor(),
    transforms.Normalize(
        mean=[0.485, 0.456, 0.406],
        std=[0.229, 0.224, 0.225]
    )
])

val_transform = transforms.Compose([
    transforms.Resize((224, 224)),
    transforms.ToTensor(),
    transforms.Normalize(
        mean=[0.485, 0.456, 0.406],
        std=[0.229, 0.224, 0.225]
    )
])

# ============================================================
# 5. DATASET
# ============================================================

class StrokeFoldDataset(Dataset):

    def __init__(self, dataframe, transform=None):
        self.df = dataframe.reset_index(drop=True)
        self.transform = transform

    def __len__(self):
        return len(self.df)

    def __getitem__(self, idx):

        row = self.df.iloc[idx]

        image = Image.open(
            row["image_path"]
        ).convert("RGB")

        if self.transform:
            image = self.transform(image)

        label = int(row["label_id"])

        return image, label

# ============================================================
# 6. STRATIFIED 5-FOLD
# ============================================================

skf = StratifiedKFold(
    n_splits=NUM_FOLDS,
    shuffle=True,
    random_state=SEED
)

fold_results = []

# ============================================================
# 7. TRAIN EACH FOLD
# ============================================================

for fold, (train_idx, val_idx) in enumerate(
    skf.split(cv_df, cv_df["label_id"]),
    start=1
):

    print("\n" + "=" * 65)
    print(f"STARTING FOLD {fold}/{NUM_FOLDS}")
    print("=" * 65)

    set_seed(SEED + fold)

    fold_train_df = cv_df.iloc[train_idx].reset_index(drop=True)
    fold_val_df = cv_df.iloc[val_idx].reset_index(drop=True)

    print("Training images:", len(fold_train_df))
    print("Validation images:", len(fold_val_df))

    # --------------------------------------------------------
    # DATA LOADERS
    # --------------------------------------------------------

    fold_train_dataset = StrokeFoldDataset(
        fold_train_df,
        transform=train_transform
    )

    fold_val_dataset = StrokeFoldDataset(
        fold_val_df,
        transform=val_transform
    )

    fold_train_loader = DataLoader(
        fold_train_dataset,
        batch_size=BATCH_SIZE,
        shuffle=True,
        num_workers=NUM_WORKERS,
        pin_memory=True
    )

    fold_val_loader = DataLoader(
        fold_val_dataset,
        batch_size=BATCH_SIZE,
        shuffle=False,
        num_workers=NUM_WORKERS,
        pin_memory=True
    )

    # --------------------------------------------------------
    # LOAD FRESH PRETRAINED MAXVIT
    # --------------------------------------------------------

    weights = MaxVit_T_Weights.DEFAULT

    model = maxvit_t(weights=weights)

    num_features = model.classifier[5].in_features

    model.classifier[5] = nn.Linear(
        num_features,
        3,
        bias=False
    )

    model = model.to(DEVICE)

    criterion = nn.CrossEntropyLoss()

    optimizer = optim.AdamW(
        model.parameters(),
        lr=LEARNING_RATE,
        weight_decay=WEIGHT_DECAY
    )

    scheduler = optim.lr_scheduler.ReduceLROnPlateau(
        optimizer,
        mode="min",
        factor=0.5,
        patience=2
    )

    best_val_acc = 0.0

    best_path = os.path.join(
        SAVE_DIR,
        f"maxvit_fold_{fold}_best.pth"
    )

    # --------------------------------------------------------
    # TRAINING LOOP
    # --------------------------------------------------------

    for epoch in range(NUM_EPOCHS):

        model.train()

        train_loss_sum = 0.0
        train_correct = 0
        train_total = 0

        for images, labels in fold_train_loader:

            images = images.to(DEVICE)
            labels = labels.to(DEVICE)

            optimizer.zero_grad()

            outputs = model(images)
            loss = criterion(outputs, labels)

            loss.backward()
            optimizer.step()

            train_loss_sum += loss.item() * images.size(0)

            predictions = outputs.argmax(dim=1)

            train_total += labels.size(0)
            train_correct += (
                predictions == labels
            ).sum().item()

        train_loss = train_loss_sum / train_total
        train_acc = train_correct / train_total

        # ----------------------------------------------------
        # VALIDATION
        # ----------------------------------------------------

        model.eval()

        val_loss_sum = 0.0
        val_correct = 0
        val_total = 0

        with torch.no_grad():

            for images, labels in fold_val_loader:

                images = images.to(DEVICE)
                labels = labels.to(DEVICE)

                outputs = model(images)

                loss = criterion(outputs, labels)

                val_loss_sum += (
                    loss.item() * images.size(0)
                )

                predictions = outputs.argmax(dim=1)

                val_total += labels.size(0)
                val_correct += (
                    predictions == labels
                ).sum().item()

        val_loss = val_loss_sum / val_total
        val_acc = val_correct / val_total

        scheduler.step(val_loss)

        # ----------------------------------------------------
        # SAVE BEST CHECKPOINT
        # ----------------------------------------------------

        marker = ""

        if val_acc > best_val_acc:

            best_val_acc = val_acc

            torch.save(
                model.state_dict(),
                best_path
            )

            marker = " BEST"

        print(
            f"Fold {fold} | "
            f"Epoch {epoch+1:02d}/{NUM_EPOCHS} | "
            f"Train Loss: {train_loss:.4f} | "
            f"Train Acc: {train_acc*100:.2f}% | "
            f"Val Loss: {val_loss:.4f} | "
            f"Val Acc: {val_acc*100:.2f}%"
            f"{marker}"
        )

    # ========================================================
    # 8. EVALUATE BEST CHECKPOINT OF THIS FOLD
    # ========================================================

    print(f"\nEvaluating best checkpoint for Fold {fold}")

    model.load_state_dict(
        torch.load(best_path, map_location=DEVICE)
    )

    model.eval()

    y_true = []
    y_pred = []

    with torch.no_grad():

        for images, labels in fold_val_loader:

            images = images.to(DEVICE)

            outputs = model(images)

            predictions = outputs.argmax(dim=1)

            y_true.extend(labels.numpy().tolist())
            y_pred.extend(predictions.cpu().numpy().tolist())

    # --------------------------------------------------------
    # METRICS
    # --------------------------------------------------------

    acc = accuracy_score(y_true, y_pred)

    precision = precision_score(
        y_true,
        y_pred,
        average="macro",
        zero_division=0
    )

    recall = recall_score(
        y_true,
        y_pred,
        average="macro",
        zero_division=0
    )

    f1 = f1_score(
        y_true,
        y_pred,
        average="macro",
        zero_division=0
    )

    fold_results.append({
        "Fold": fold,
        "Accuracy": acc,
        "Precision": precision,
        "Recall": recall,
        "F1-score": f1
    })

    print("\nFold-wise classification report:")
    print(
        classification_report(
            y_true,
            y_pred,
            target_names=[
                "Normal",
                "Ischemia",
                "Bleeding"
            ],
            digits=4,
            zero_division=0
        )
    )

    print(
        f"Fold {fold} Results: "
        f"Acc={acc:.4f}, "
        f"Prec={precision:.4f}, "
        f"Recall={recall:.4f}, "
        f"F1={f1:.4f}"
    )

    del model, optimizer, scheduler
    torch.cuda.empty_cache()

# ============================================================
# 9. FINAL RESULTS: MEAN ± STANDARD DEVIATION
# ============================================================

results_df = pd.DataFrame(fold_results)

print("\n" + "=" * 75)
print("FIVE-FOLD CROSS-VALIDATION RESULTS")
print("=" * 75)

print(
    results_df.to_string(
        index=False,
        float_format=lambda x: f"{x:.4f}"
    )
)

summary = []

for metric in [
    "Accuracy",
    "Precision",
    "Recall",
    "F1-score"
]:

    mean_value = results_df[metric].mean()

    std_value = results_df[metric].std(ddof=1)

    summary.append({
        "Metric": metric,
        "Mean": mean_value,
        "SD": std_value,
        "Mean ± SD": f"{mean_value:.4f} ± {std_value:.4f}"
    })

summary_df = pd.DataFrame(summary)

print("\nMEAN ± STANDARD DEVIATION")
print(summary_df.to_string(index=False))

# ============================================================
# 10. SAVE RESULTS
# ============================================================

results_df.to_csv(
    os.path.join(SAVE_DIR, "five_fold_results.csv"),
    index=False
)

summary_df.to_csv(
    os.path.join(SAVE_DIR, "five_fold_mean_sd.csv"),
    index=False
)

print("\nResults saved in:")
print(SAVE_DIR)

print("\n5-FOLD CROSS-VALIDATION COMPLETED.")

