import os
import torch
import torch.nn as nn
import numpy as np

from torchvision.models import maxvit_t
from sklearn.metrics import (
    accuracy_score,
    precision_score,
    recall_score,
    f1_score,
    classification_report,
    confusion_matrix
)

# ==========================================
# 1. DEVICE AND CHECKPOINT
# ==========================================

DEVICE = torch.device(
    "cuda" if torch.cuda.is_available() else "cpu"
)

SAVE_DIR = "/content/drive/MyDrive/Stroke_MaxViT_5Fold"

best_path = os.path.join(
    SAVE_DIR,
    "maxvit_fold_5_best.pth"
)

assert os.path.exists(best_path), "Fold 5 checkpoint not found!"

print("Device:", DEVICE)
print("Checkpoint:", best_path)

# ==========================================
# 2. RECREATE MAXVIT MODEL
# ==========================================

model = maxvit_t(weights=None)

num_features = model.classifier[5].in_features

model.classifier[5] = nn.Linear(
    num_features,
    3,
    bias=False
)

# ==========================================
# 3. LOAD BEST FOLD 5 WEIGHTS
# ==========================================

state_dict = torch.load(
    best_path,
    map_location=DEVICE,
    weights_only=True
)

model.load_state_dict(state_dict)

model = model.to(DEVICE)
model.eval()

print("Fold 5 checkpoint loaded successfully!")

# ==========================================
# 4. EVALUATION
# ==========================================

all_preds = []
all_labels = []

with torch.no_grad():

    for images, labels in fold_val_loader:

        images = images.to(DEVICE)

        outputs = model(images)

        preds = torch.argmax(outputs, dim=1)

        all_preds.extend(
            preds.cpu().numpy()
        )

        all_labels.extend(
            labels.numpy()
        )

# ==========================================
# 5. METRICS
# ==========================================

accuracy = accuracy_score(
    all_labels, all_preds
)

precision = precision_score(
    all_labels,
    all_preds,
    average="macro",
    zero_division=0
)

recall = recall_score(
    all_labels,
    all_preds,
    average="macro",
    zero_division=0
)

f1 = f1_score(
    all_labels,
    all_preds,
    average="macro",
    zero_division=0
)

print("\n========== FOLD 5 RESULTS ==========")

print(f"Accuracy         : {accuracy:.4f}")
print(f"Macro Precision  : {precision:.4f}")
print(f"Macro Recall     : {recall:.4f}")
print(f"Macro F1-score   : {f1:.4f}")

# ==========================================
# 6. CLASSIFICATION REPORT
# ==========================================

print("\n========== CLASSIFICATION REPORT ==========")

print(
    classification_report(
        all_labels,
        all_preds,
        labels=[0, 1, 2],
        target_names=[
            "Normal",
            "Ischemia",
            "Bleeding"
        ],
        digits=4,
        zero_division=0
    )
)

# ==========================================
