# GROUND-TRUTH LESION QUANTITATIVE ANALYSIS
# ============================================================

import os
import numpy as np
import pandas as pd
from PIL import Image
from tqdm.auto import tqdm
from collections import Counter

# ------------------------------------------------------------
# 1. Dataset paths
# ------------------------------------------------------------

DATASET_ROOT = "/content/drive/MyDrive/archive (1)/İNME VERİ SETİ"

CLASS_DIRS = {
    "Bleeding": os.path.join(DATASET_ROOT, "Bleeding"),
    "Ischemia": os.path.join(DATASET_ROOT, "Ischemia")
}

# ------------------------------------------------------------
# 2. Extract lesion mask from OVERLAY
# ------------------------------------------------------------

def extract_gt_mask(overlay_rgb):

    overlay_rgb = np.asarray(overlay_rgb)

    r = overlay_rgb[:, :, 0].astype(np.int16)
    g = overlay_rgb[:, :, 1].astype(np.int16)
    b = overlay_rgb[:, :, 2].astype(np.int16)

    # Red / blue colored lesion annotation
    colored = (
        ((r > g + 30) & (r > b + 30)) |
        ((b > r + 30) & (b > g + 30))
    )

    return colored.astype(np.uint8)


# ------------------------------------------------------------
# 3. Build OVERLAY lookup
# ------------------------------------------------------------

overlay_lookup = {}

for cls, class_dir in CLASS_DIRS.items():

    overlay_dir = os.path.join(class_dir, "OVERLAY")

    if not os.path.exists(overlay_dir):
        print("Missing:", overlay_dir)
        continue

    for fname in os.listdir(overlay_dir):

        if fname.lower().endswith((".png", ".jpg", ".jpeg")):

            full_path = os.path.join(overlay_dir, fname)

            # filename -> overlay path
            overlay_lookup[(cls, fname)] = full_path


print("Total overlay files found:", len(overlay_lookup))


# ------------------------------------------------------------
# 4. Process lesion masks
# ------------------------------------------------------------

results = []

for cls in ["Bleeding", "Ischemia"]:

    class_dir = CLASS_DIRS[cls]
    png_dir = os.path.join(class_dir, "PNG")

    if not os.path.exists(png_dir):
        continue

    image_files = [
        f for f in os.listdir(png_dir)
        if f.lower().endswith((".png", ".jpg", ".jpeg"))
    ]

    print(f"\n{cls}: {len(image_files)} images")

    for fname in tqdm(image_files):

        key = (cls, fname)

        if key not in overlay_lookup:
            continue

        image_path = os.path.join(png_dir, fname)
        overlay_path = overlay_lookup[key]

        try:

            # Original CT
            ct_img = Image.open(image_path).convert("L")

            # Overlay
            overlay_img = Image.open(overlay_path).convert("RGB")

            # Resize to the same 224x224 space used by model
            ct_img = ct_img.resize((224, 224), Image.Resampling.BILINEAR)
            overlay_img = overlay_img.resize(
                (224, 224),
                Image.Resampling.NEAREST
            )

            ct_array = np.array(ct_img)
            overlay_array = np.array(overlay_img)

            # Ground-truth lesion mask
            lesion_mask = extract_gt_mask(overlay_array)

            lesion_pixels = int(lesion_mask.sum())

            # ------------------------------------------------
            # Brain/image area
            # ------------------------------------------------
            # Non-black CT region as a simple image-support mask
            brain_mask = (ct_array > 10).astype(np.uint8)

            brain_pixels = int(brain_mask.sum())

            # Coverage relative to full image
            image_coverage = (
                lesion_pixels / (224 * 224) * 100
            )

            # Coverage relative to visible CT region
            brain_coverage = (
                lesion_pixels / brain_pixels * 100
                if brain_pixels > 0 else 0
            )

            # ------------------------------------------------
            # Lesion centroid
            # ------------------------------------------------

            ys, xs = np.where(lesion_mask > 0)

            if len(xs) > 0:

                centroid_x = float(xs.mean())
                centroid_y = float(ys.mean())

                # Normalize centroid to 0-1
                centroid_x_norm = centroid_x / 224
                centroid_y_norm = centroid_y / 224

            else:

                centroid_x = np.nan
                centroid_y = np.nan
                centroid_x_norm = np.nan
                centroid_y_norm = np.nan

            # ------------------------------------------------
            # 6-region spatial mapping
            # ------------------------------------------------

            if len(xs) > 0:

                # Left / Right
                if centroid_x_norm < 0.5:
                    side = "Left"
                else:
                    side = "Right"

                # Anterior / Middle / Posterior
                if centroid_y_norm < 1/3:
                    position = "Anterior"

                elif centroid_y_norm < 2/3:
                    position = "Middle"

                else:
                    position = "Posterior"

                region = f"{side} {position}"

            else:

                region = "No Lesion"

            results.append({
                "filename": fname,
                "class": cls,
                "image_path": image_path,
                "overlay_path": overlay_path,

                "lesion_area_pixels": lesion_pixels,

                "image_coverage_percent": image_coverage,
                "brain_coverage_percent": brain_coverage,

                "centroid_x": centroid_x,
                "centroid_y": centroid_y,

                "centroid_x_norm": centroid_x_norm,
                "centroid_y_norm": centroid_y_norm,

                "region": region
            })

        except Exception as e:

            print("Error:", fname, e)


# ------------------------------------------------------------
# 5. Create dataframe
# ------------------------------------------------------------

lesion_df = pd.DataFrame(results)

print("\n========================================")
print("GROUND-TRUTH LESION ANALYSIS COMPLETE")
print("========================================")

print("Total annotated images:", len(lesion_df))

print("\nClass distribution:")
print(lesion_df["class"].value_counts())

