print("========== OVERALL LESION STATISTICS ==========")

print(f"Total annotated images: {len(lesion_df)}")

print("\nLesion Area (pixels):")
print(lesion_df["lesion_area_pixels"].describe())

print("\nImage Coverage (%):")
