# ============================================================
# OFFICIAL MASK vs OVERLAY VALIDATION
# SESSION 1 + SESSION 2
# ============================================================

import os
import numpy as np
import pandas as pd
from PIL import Image
from tqdm.auto import tqdm

ROOT = "/content/drive/MyDrive/archive (1)/İNME VERİ SETİ"

SESSION_DIRS = [
    os.path.join(ROOT, "YarısmaVeriSeti_1_Oturum"),
    os.path.join(ROOT, "YarısmaVeriSeti_2_Oturum")
]

# ------------------------------------------------------------
# Overlay -> binary lesion mask
# ------------------------------------------------------------

def extract_gt_mask(overlay_rgb):

    overlay_rgb = np.asarray(overlay_rgb)

    r = overlay_rgb[:, :, 0].astype(np.int16)
    g = overlay_rgb[:, :, 1].astype(np.int16)
    b = overlay_rgb[:, :, 2].astype(np.int16)

    colored = (
        ((r > g + 30) & (r > b + 30)) |
        ((b > r + 30) & (b > g + 30))
    )

    return colored.astype(np.uint8)


# ------------------------------------------------------------
# Dice
# ------------------------------------------------------------

def dice_score(mask1, mask2):

    mask1 = mask1.astype(bool)
    mask2 = mask2.astype(bool)

    intersection = np.logical_and(
        mask1, mask2
    ).sum()

    total = mask1.sum() + mask2.sum()

    if total == 0:
        return 1.0

    return 2 * intersection / total


# ------------------------------------------------------------
# IoU
# ------------------------------------------------------------

def iou_score(mask1, mask2):

    mask1 = mask1.astype(bool)
    mask2 = mask2.astype(bool)

    intersection = np.logical_and(
        mask1, mask2
    ).sum()

    union = np.logical_or(
        mask1, mask2
    ).sum()

    if union == 0:
        return 1.0

    return intersection / union


# ============================================================
# VALIDATION
# ============================================================

all_results = []

for session_dir in SESSION_DIRS:

    session_name = os.path.basename(session_dir)

    mask_dir = os.path.join(
        session_dir,
        "MASKS"
    )

    overlay_dir = os.path.join(
        session_dir,
        "OVERLAY"
    )

    print("\n" + "=" * 70)
    print("SESSION:", session_name)
    print("=" * 70)

    mask_files = {
        os.path.splitext(f)[0]: os.path.join(
            mask_dir, f
        )
        for f in os.listdir(mask_dir)
        if f.lower().endswith(".png")
    }

    overlay_files = {
        os.path.splitext(f)[0]: os.path.join(
            overlay_dir, f
        )
        for f in os.listdir(overlay_dir)
        if f.lower().endswith(".png")
    }

    matched_ids = sorted(
        set(mask_files) &
        set(overlay_files)
    )

    print("Official MASK:", len(mask_files))
    print("OVERLAY:", len(overlay_files))
    print("Matched pairs:", len(matched_ids))

    for image_id in tqdm(
        matched_ids,
        desc=session_name
    ):

        try:

            # --------------------------------------------
            # Official binary mask
            # --------------------------------------------

            official = Image.open(
                mask_files[image_id]
            ).convert("L")

            official = np.array(
                official
            )

            official = (
                official > 0
            ).astype(np.uint8)


            # --------------------------------------------
            # Overlay
            # --------------------------------------------

            overlay = Image.open(
                overlay_files[image_id]
            ).convert("RGB")

            overlay = np.array(
                overlay
            )

            extracted = extract_gt_mask(
                overlay
            )


            # --------------------------------------------
            # Resize if necessary
            # --------------------------------------------

            if official.shape != extracted.shape:

                extracted_img = Image.fromarray(
                    extracted * 255
                )

                extracted_img = extracted_img.resize(
                    (
                        official.shape[1],
                        official.shape[0]
                    ),
                    Image.Resampling.NEAREST
                )

                extracted = (
                    np.array(
                        extracted_img
                    ) > 0
                ).astype(np.uint8)


            # --------------------------------------------
            # Metrics
            # --------------------------------------------

            dice = dice_score(
                official,
                extracted
            )

            iou = iou_score(
                official,
                extracted
            )


            all_results.append({

                "session":
                    session_name,

                "image_id":
                    image_id,

                "official_mask_pixels":
                    int(official.sum()),

                "extracted_mask_pixels":
                    int(extracted.sum()),

                "dice":
                    dice,

                "iou":
                    iou
            })


        except Exception as e:

            print(
                f"Error {image_id}: {e}"
            )


mask_validation_df = pd.DataFrame(
    all_results
)


# ============================================================
# FINAL SUMMARY
# ============================================================

print("\n")
print("=" * 70)
print("OFFICIAL MASK vs OVERLAY VALIDATION")
print("=" * 70)

print(
    "Total validated pairs:",
    len(mask_validation_df)
)

print("\n---------- DICE ----------")

