# ============================================================
# STEP 1: STATISTICAL VALIDATION OF LESION CHARACTERISTICS
# N = 2,223
# Bleeding vs Ischemia
# ============================================================

import numpy as np
import pandas as pd
from scipy import stats


# ============================================================
# 1. PREPARE DATA
# ============================================================

df = lesion_df.copy()

# Make sure numeric columns are numeric
numeric_cols = [
    "lesion_area_pixels",
    "image_coverage_percent",
    "brain_coverage_percent",
    "centroid_x_norm",
    "centroid_y_norm"
]

for col in numeric_cols:
    df[col] = pd.to_numeric(
        df[col],
        errors="coerce"
    )


bleeding = df[
    df["class"] == "Bleeding"
].copy()

ischemia = df[
    df["class"] == "Ischemia"
].copy()


print("=" * 70)
print("STATISTICAL VALIDATION")
print("=" * 70)

print("Bleeding N :", len(bleeding))
print("Ischemia N :", len(ischemia))
print("Total N    :", len(df))


# ============================================================
# 2. BOOTSTRAP 95% CI FOR MEAN DIFFERENCE
# ============================================================

def bootstrap_mean_difference(
    group1,
    group2,
    n_boot=5000,
    seed=42
):

    rng = np.random.default_rng(seed)

    group1 = np.asarray(group1)
    group2 = np.asarray(group2)

    differences = []

    for _ in range(n_boot):

        sample1 = rng.choice(
            group1,
            size=len(group1),
            replace=True
        )

        sample2 = rng.choice(
            group2,
            size=len(group2),
            replace=True
        )

        differences.append(
            np.mean(sample2) -
            np.mean(sample1)
        )

    differences = np.asarray(
        differences
    )

    ci_low, ci_high = np.percentile(
        differences,
        [2.5, 97.5]
    )

    return (
        np.mean(differences),
        ci_low,
        ci_high
    )


# ============================================================
# 3. COHEN'S d
# ============================================================

def cohens_d(group1, group2):

    group1 = np.asarray(group1)
    group2 = np.asarray(group2)

    n1 = len(group1)
    n2 = len(group2)

    mean1 = np.mean(group1)
    mean2 = np.mean(group2)

    var1 = np.var(
        group1,
        ddof=1
    )

    var2 = np.var(
        group2,
        ddof=1
    )

    pooled_sd = np.sqrt(
        (
            (n1 - 1) * var1 +
            (n2 - 1) * var2
        )
        /
        (
            n1 + n2 - 2
        )
    )

    if pooled_sd == 0:
        return np.nan

    return (
        (mean2 - mean1)
        / pooled_sd
    )


# ============================================================
# 4. STATISTICAL TEST FOR EACH FEATURE
# ============================================================

features = {

    "Lesion Area (pixels)":
        "lesion_area_pixels",

    "Image Coverage (%)":
        "image_coverage_percent",

    "Visible-CT Coverage (%)":
        "brain_coverage_percent",

    "Centroid X":
        "centroid_x_norm",

    "Centroid Y":
        "centroid_y_norm"
}


results = []


for feature_name, column in features.items():

    g1 = bleeding[column].dropna().values
    g2 = ischemia[column].dropna().values


    # --------------------------------------------------------
    # Descriptive statistics
    # --------------------------------------------------------

    mean1 = np.mean(g1)
    mean2 = np.mean(g2)

    sd1 = np.std(
        g1,
        ddof=1
    )

    sd2 = np.std(
        g2,
        ddof=1
    )

    median1 = np.median(g1)
    median2 = np.median(g2)


    # --------------------------------------------------------
    # Mann–Whitney U
    # --------------------------------------------------------

    u_stat, mw_p = stats.mannwhitneyu(
        g1,
        g2,
        alternative="two-sided"
    )


    # --------------------------------------------------------
    # Welch's t-test
    # --------------------------------------------------------

    t_stat, t_p = stats.ttest_ind(
        g1,
        g2,
        equal_var=False
    )


    # --------------------------------------------------------
    # Cohen's d
    # --------------------------------------------------------

    d = cohens_d(
        g1,
        g2
    )


    # --------------------------------------------------------
    # Bootstrap CI
    # Difference = Ischemia - Bleeding
    # --------------------------------------------------------

    diff, ci_low, ci_high = (
        bootstrap_mean_difference(
            g1,
            g2
        )
    )


    # --------------------------------------------------------
    # Fold difference
    # --------------------------------------------------------

    if mean1 != 0:
        fold_difference = (
            mean2 / mean1
        )
    else:
        fold_difference = np.nan


    results.append({

        "Feature":
            feature_name,

        "Bleeding_Mean":
            mean1,

        "Bleeding_SD":
            sd1,

        "Bleeding_Median":
            median1,

        "Ischemia_Mean":
            mean2,

        "Ischemia_SD":
            sd2,

        "Ischemia_Median":
            median2,

        "Mean_Difference":
            diff,

        "95CI_Lower":
            ci_low,

        "95CI_Upper":
            ci_high,

        "Fold_Difference":
            fold_difference,

        "Mann_Whitney_U":
            u_stat,

        "MW_p":
            mw_p,

        "Welch_t":
            t_stat,

        "Welch_p":
            t_p,

        "Cohens_d":
            d
    })


stats_df = pd.DataFrame(
    results
)


# ============================================================
# 5. MULTIPLE-COMPARISON CORRECTION
# ============================================================

from statsmodels.stats.multitest import (
    multipletests
)

stats_df["MW_p_FDR"] = (
    multipletests(
        stats_df["MW_p"],
        method="fdr_bh"
    )[1]
)


# ============================================================
# 6. SIGNIFICANCE LABEL
# ============================================================

stats_df["Significant_FDR"] = (
    stats_df["MW_p_FDR"] < 0.05
)


# ============================================================
# 7. PAPER-READY ROUNDING
# ============================================================

display_columns = [

    "Feature",

    "Bleeding_Mean",
    "Bleeding_SD",
    "Bleeding_Median",

    "Ischemia_Mean",
    "Ischemia_SD",
    "Ischemia_Median",

    "Mean_Difference",

    "95CI_Lower",
    "95CI_Upper",

    "Fold_Difference",

    "MW_p",
    "MW_p_FDR",

    "Cohens_d",

    "Significant_FDR"
]


paper_stats = stats_df[
    display_columns
].copy()


numeric_display = [
    c for c in display_columns
    if c != "Feature"
    and c != "Significant_FDR"
]


paper_stats[numeric_display] = (
    paper_stats[numeric_display]
    .round(4)
)


print("\n")
print("=" * 70)
print("PAPER-READY STATISTICAL TABLE")
print("=" * 70)

display(paper_stats)


# ============================================================
# 8. NORMALITY CHECK
# ============================================================

print("\n")
print("=" * 70)
print("NORMALITY CHECK")
print("=" * 70)

for feature_name, column in features.items():

    # Shapiro is not ideal for huge N, so use
    # a random subset of 5000 max.

    b_sample = bleeding[column].dropna()

    i_sample = ischemia[column].dropna()

    if len(b_sample) > 5000:
        b_sample = b_sample.sample(
            5000,
            random_state=42
        )

    if len(i_sample) > 5000:
        i_sample = i_sample.sample(
            5000,
            random_state=42
        )

    b_stat, b_p = stats.shapiro(
        b_sample
    )

    i_stat, i_p = stats.shapiro(
        i_sample
    )

    print(
        f"\n{feature_name}"
    )

    print(
        f"Bleeding Shapiro p = {b_p:.6g}"
    )

    print(
        f"Ischemia Shapiro p = {i_p:.6g}"
    )


# ============================================================
# 9. EFFECT SIZE INTERPRETATION
# ============================================================

def interpret_d(d):

    d_abs = abs(d)

    if d_abs < 0.2:
        return "Negligible"

    elif d_abs < 0.5:
        return "Small"

    elif d_abs < 0.8:
        return "Medium"

    else:
        return "Large"


stats_df["Effect_Size_Interpretation"] = (
    stats_df["Cohens_d"].apply(
        interpret_d
    )
)


print("\n")
print("=" * 70)
print("EFFECT SIZE")
print("=" * 70)

display(
    stats_df[
        [
            "Feature",
            "Cohens_d",
            "Effect_Size_Interpretation"
        ]
    ].round(4)
)

# ============================================================
# STEP 2: FULL LESION QUALITY CONTROL / QC
# N = 2,223
# ============================================================

import os
import numpy as np
import pandas as pd
from PIL import Image
from tqdm.auto import tqdm
from scipy import ndimage


# ============================================================
# 1. CONFIGURATION
# ============================================================

df = lesion_df.copy()

print("=" * 70)
print("FULL LESION QUALITY CONTROL")
print("=" * 70)

print("Total images:", len(df))


# ============================================================
# 2. RE-ANALYZE EVERY LESION MASK
# ============================================================

qc_results = []

for _, row in tqdm(
    df.iterrows(),
    total=len(df),
    desc="QC"
):

    try:

        overlay_path = row["overlay_path"]

        overlay_img = Image.open(
            overlay_path
        ).convert("RGB")

        overlay_img = overlay_img.resize(
            (224, 224),
            Image.Resampling.NEAREST
        )

        overlay_array = np.array(
            overlay_img
        )

        # --------------------------------------------
        # Extract lesion mask
        # --------------------------------------------

        lesion_mask = extract_gt_mask(
            overlay_array
        )

        lesion_mask = (
            lesion_mask > 0
        ).astype(np.uint8)


        # --------------------------------------------
        # Basic lesion area
        # --------------------------------------------

        lesion_pixels = int(
            lesion_mask.sum()
        )

        lesion_percentage = (
            lesion_pixels /
            (224 * 224)
        ) * 100


        # --------------------------------------------
        # Connected components
        # --------------------------------------------

        labeled_mask, num_components = (
            ndimage.label(
                lesion_mask
            )
        )

        component_sizes = np.bincount(
            labeled_mask.ravel()
        )[1:]


        if len(component_sizes) > 0:

            largest_component = int(
                component_sizes.max()
            )

            smallest_component = int(
                component_sizes.min()
            )

            mean_component_size = float(
                component_sizes.mean()
            )

            median_component_size = float(
                np.median(
                    component_sizes
                )
            )

        else:

            largest_component = 0
            smallest_component = 0
            mean_component_size = 0
            median_component_size = 0


        # --------------------------------------------
        # Largest-component ratio
        # --------------------------------------------

        if lesion_pixels > 0:

            largest_component_ratio = (
                largest_component /
                lesion_pixels
            )

        else:

            largest_component_ratio = 0


        # --------------------------------------------
        # Empty lesion flag
        # --------------------------------------------

        empty_mask = (
            lesion_pixels == 0
        )


        # --------------------------------------------
        # Very small lesion
        # --------------------------------------------

        very_small = (
            lesion_pixels < 20
        )


        # --------------------------------------------
        # Very large lesion
        # --------------------------------------------

        very_large = (
            lesion_percentage > 10
        )


        # --------------------------------------------
        # Fragmented lesion
        # --------------------------------------------

        fragmented = (
            num_components >= 5
        )


        # --------------------------------------------
        # Centroid
        # --------------------------------------------

        ys, xs = np.where(
            lesion_mask > 0
        )

        if len(xs) > 0:

            centroid_x = (
                float(xs.mean()) / 224
            )

            centroid_y = (
                float(ys.mean()) / 224
            )

        else:

            centroid_x = np.nan
            centroid_y = np.nan


        qc_results.append({

            "filename":
                row["filename"],

            "class":
                row["class"],

            "lesion_area_pixels":
                lesion_pixels,

            "lesion_coverage_percent":
                lesion_percentage,

            "num_components":
                int(num_components),

            "largest_component_pixels":
                largest_component,

            "smallest_component_pixels":
                smallest_component,

            "mean_component_pixels":
                mean_component_size,

            "median_component_pixels":
                median_component_size,

            "largest_component_ratio":
                largest_component_ratio,

            "centroid_x_norm":
                centroid_x,

            "centroid_y_norm":
                centroid_y,

            "empty_mask":
                empty_mask,

            "very_small":
                very_small,

            "very_large":
                very_large,

            "fragmented":
                fragmented
        })


    except Exception as e:

        print(
            "ERROR:",
            row["filename"],
            e
        )


qc_df = pd.DataFrame(
    qc_results
)


# ============================================================
# 3. BASIC QC SUMMARY
# ============================================================

print("\n")
print("=" * 70)
print("BASIC QC SUMMARY")
print("=" * 70)

print(
    "Successfully processed:",
    len(qc_df)
)

print(
    "Failed:",
    len(df) - len(qc_df)
)

