# ============================================================
# STEP 2 — GRAD-CAM + GROUND-TRUTH LESION MASK
# 331 HELD-OUT ANNOTATED TEST IMAGES
# ============================================================

import numpy as np
import torch
from PIL import Image
from pytorch_grad_cam.utils.model_targets import ClassifierOutputTarget

# IMPORTANT: model output mapping
model_idx_to_label = {
    0: "Normal",
    1: "Ischemia",
    2: "Bleeding"
}

IMG_SIZE = 224
CAM_THRESHOLD = 0.35

def extract_gt_mask(overlay_rgb):
    r = overlay_rgb[:, :, 0].astype(np.int16)
    g = overlay_rgb[:, :, 1].astype(np.int16)
    b = overlay_rgb[:, :, 2].astype(np.int16)

    colored = (
        ((r > g + 30) & (r > b + 30)) |
        ((b > r + 30) & (b > g + 30))
    )

    return colored.astype(np.uint8)


validation_records = []

for i, row in annotated_test_df.iterrows():

    # -------------------------------
    # Load CT image
    # -------------------------------
    pil_img = Image.open(
        row["image_path"]
    ).convert("RGB").resize(
        (IMG_SIZE, IMG_SIZE)
    )

    input_tensor = val_transform(
        pil_img
    ).unsqueeze(0).to(device)

    # -------------------------------
    # Classification
    # -------------------------------
    with torch.no_grad():
        output = model(input_tensor)
        probs = torch.softmax(output, dim=1)
        confidence, pred = torch.max(probs, dim=1)

    pred_idx = pred.item()
    confidence = confidence.item()
    pred_class = model_idx_to_label[pred_idx]

    # -------------------------------
    # Ground-truth lesion
    # -------------------------------
    overlay = Image.open(
        row["overlay_path"]
    ).convert("RGB").resize(
        (IMG_SIZE, IMG_SIZE),
        Image.Resampling.NEAREST
    )

    gt_mask = extract_gt_mask(
        np.array(overlay)
    )

    # -------------------------------
    # Grad-CAM
    # -------------------------------
    grayscale_cam = cam(
        input_tensor=input_tensor,
        targets=[ClassifierOutputTarget(pred_idx)]
    )[0]

    grayscale_cam = grayscale_cam.copy()

    if grayscale_cam.max() > 0:
        grayscale_cam /= grayscale_cam.max()

    cam_mask = (
        grayscale_cam >= CAM_THRESHOLD
    ).astype(np.uint8)

    # -------------------------------
    # Save record
    # -------------------------------
    validation_records.append({
        "filename": row["filename"],
        "true_class": row["class"],
        "pred_class": pred_class,
        "pred_idx": pred_idx,
        "confidence": confidence,
        "gt_mask": gt_mask,
        "cam_mask": cam_mask,
        "cam_map": grayscale_cam
    })

    if (i + 1) % 25 == 0:
        print(f"Processed {i+1}/{len(annotated_test_df)}")

print("\n========================================")
print("GRAD-CAM VALIDATION DATA READY")
print("========================================")
print("Processed:", len(validation_records))

print(
    "Non-empty GT masks:",
    sum(r["gt_mask"].sum() > 0 for r in validation_records),
    "/", len(validation_records)
)

print(
    "Non-empty CAM masks:",
    sum(r["cam_mask"].sum() > 0 for r in validation_records),
    "/", len(validation_records)
)

# ============================================================
# STEP 3 — LESION–GRAD-CAM SPATIAL VALIDATION
# Dice, IoU, Pointing Game, Centroid Distance
# ============================================================

import numpy as np
import pandas as pd

results = []

for r in validation_records:

    gt = r["gt_mask"].astype(bool)
    cam_mask = r["cam_mask"].astype(bool)

    # --------------------------------------------------------
    # Dice
    # --------------------------------------------------------
    intersection = np.logical_and(gt, cam_mask).sum()

    dice = (
        2 * intersection /
        (gt.sum() + cam_mask.sum())
        if (gt.sum() + cam_mask.sum()) > 0
        else 0.0
    )

    # --------------------------------------------------------
    # IoU
    # --------------------------------------------------------
    union = np.logical_or(gt, cam_mask).sum()

    iou = (
        intersection / union
        if union > 0
        else 0.0
    )

    # --------------------------------------------------------
    # Pointing Game
    # Does maximum Grad-CAM activation fall inside lesion?
    # --------------------------------------------------------
    cam_map = r["cam_map"]

    max_y, max_x = np.unravel_index(
        np.argmax(cam_map),
        cam_map.shape
    )

    pointing = int(gt[max_y, max_x])

    # --------------------------------------------------------
    # GT lesion centroid
    # --------------------------------------------------------
    gt_y, gt_x = np.where(gt)

    if len(gt_x) > 0:
        gt_centroid_x = gt_x.mean()
        gt_centroid_y = gt_y.mean()
    else:
        gt_centroid_x = np.nan
        gt_centroid_y = np.nan

    # --------------------------------------------------------
    # Grad-CAM centroid
    # --------------------------------------------------------
    cam_y, cam_x = np.where(cam_mask)

    if len(cam_x) > 0:
        cam_centroid_x = cam_x.mean()
        cam_centroid_y = cam_y.mean()
    else:
        cam_centroid_x = np.nan
        cam_centroid_y = np.nan

    # --------------------------------------------------------
    # Centroid distance in pixels
    # --------------------------------------------------------
    if not np.isnan(cam_centroid_x):

        centroid_distance = np.sqrt(
            (gt_centroid_x - cam_centroid_x) ** 2 +
            (gt_centroid_y - cam_centroid_y) ** 2
        )

    else:
        centroid_distance = np.nan

    results.append({
        "filename": r["filename"],
        "true_class": r["true_class"],
        "pred_class": r["pred_class"],
        "confidence": r["confidence"],
        "correct": r["true_class"] == r["pred_class"],
        "gt_area_pixels": int(gt.sum()),
        "cam_area_pixels": int(cam_mask.sum()),
        "dice": dice,
        "iou": iou,
        "pointing_game": pointing,
        "gt_centroid_x": gt_centroid_x,
        "gt_centroid_y": gt_centroid_y,
        "cam_centroid_x": cam_centroid_x,
        "cam_centroid_y": cam_centroid_y,
        "centroid_distance": centroid_distance
    })

validation_df = pd.DataFrame(results)

# ============================================================
# OVERALL SUMMARY
# ============================================================

print("========================================")
print("OVERALL LESION–GRAD-CAM VALIDATION")
print("========================================")

print(f"N = {len(validation_df)}")

print(
    f"Dice              : "
    f"{validation_df['dice'].mean():.4f} ± "
    f"{validation_df['dice'].std():.4f}"
)

print(
    f"IoU               : "
    f"{validation_df['iou'].mean():.4f} ± "
    f"{validation_df['iou'].std():.4f}"
)

print(
    f"Pointing Game     : "
    f"{validation_df['pointing_game'].mean():.4f}"
)

print(
    f"Centroid Distance : "
    f"{validation_df['centroid_distance'].mean():.4f} ± "
    f"{validation_df['centroid_distance'].std():.4f} pixels"
)

# ============================================================
# CLASS-WISE SUMMARY
# ============================================================

class_summary = (
    validation_df
    .groupby("true_class")
    .agg(
        N=("filename", "count"),
        Dice=("dice", "mean"),
        IoU=("iou", "mean"),
        Pointing_Game=("pointing_game", "mean"),
        Centroid_Distance=("centroid_distance", "mean")
    )
    .reset_index()
)

print("\n========================================")
print("CLASS-WISE VALIDATION")
print("========================================")

display(class_summary)

# ============================================================
# SAVE RESULTS
# ============================================================

out_path = "/content/final_gradcam_validation/gradcam_lesion_validation_new.csv"

validation_df.to_csv(
    out_path,
    index=False
)

class_summary.to_csv(
    "/content/final_gradcam_validation/gradcam_classwise_summary_new.csv",
    index=False
)

print("\nSaved:")
print(out_path)

