import os
import torch
import torch.nn as nn
import pandas as pd
import numpy as np

from PIL import Image
from torchvision import transforms
from torchvision.models import maxvit_t

# ------------------------------------------------------------
# 1. Paths
# ------------------------------------------------------------

# CHANGE THIS to your external dataset folder
EXTERNAL_ROOT = "/content/drive/MyDrive/EXTERNAL_DATASET"

# Existing trained MaxViT checkpoint
CHECKPOINT_PATH = (
    "/content/drive/MyDrive/Stroke_MaxViT_Model/"
    "best_maxvit_t.pth"
)

print("External dataset path:")
print(EXTERNAL_ROOT)

print("\nCheckpoint path:")
print(CHECKPOINT_PATH)

print("\nExternal dataset exists:", os.path.exists(EXTERNAL_ROOT))
print("Checkpoint exists:", os.path.exists(CHECKPOINT_PATH))


# ------------------------------------------------------------
# 2. Device
# ------------------------------------------------------------

device = torch.device(
    "cuda" if torch.cuda.is_available() else "cpu"
)

print("\nDevice:", device)


# ------------------------------------------------------------
# 3. Same preprocessing used during training
# ------------------------------------------------------------

preprocess = transforms.Compose([
    transforms.Resize((224, 224)),
    transforms.ToTensor(),
    transforms.Normalize(
        mean=[0.485, 0.456, 0.406],
        std=[0.229, 0.224, 0.225]
    )
])


# ------------------------------------------------------------
# 4. Load MaxViT
# ------------------------------------------------------------

model = maxvit_t(
    weights=None,
    num_classes=3
)

checkpoint = torch.load(
    CHECKPOINT_PATH,
    map_location=device
)

# Handle direct state_dict checkpoint
if isinstance(checkpoint, dict) and "state_dict" in checkpoint:
    state_dict = checkpoint["state_dict"]
else:
    state_dict = checkpoint

# Remove possible "module." prefix
state_dict = {
    k.replace("module.", "", 1) if k.startswith("module.") else k: v
    for k, v in state_dict.items()
}

model.load_state_dict(state_dict, strict=True)

model = model.to(device)
model.eval()


# ------------------------------------------------------------
# 5. Class mapping
# ------------------------------------------------------------

# Dataset semantic labels
gt_class_to_idx = {
    "Normal": 0,
    "Bleeding": 1,
    "Ischemia": 2
}

# IMPORTANT:
# The trained MaxViT raw output mapping from your previous model
model_idx_to_label = {
    0: "Normal",
    1: "Ischemia",
    2: "Bleeding"
}

print("\nModel loaded successfully.")
print("Number of parameters:",
      sum(p.numel() for p in model.parameters()))

print("\nModel output mapping:")
print(model_idx_to_label)



import os

os.makedirs("/content/final_gradcam_validation", exist_ok=True)

validation_df.to_csv(
    "/content/final_gradcam_validation/gradcam_lesion_validation.csv",
    index=False
)

class_summary.to_csv(
    "/content/final_gradcam_validation/gradcam_classwise_summary.csv",
    index=False
)

