import os
import glob
import pandas as pd

DATA_ROOT = "/content/drive/MyDrive/archive (1)/İNME VERİ SETİ"

mask_files = glob.glob(
    os.path.join(DATA_ROOT, "**", "MASKS", "*.png"),
    recursive=True
)

records = []

for mask_path in mask_files:

    filename = os.path.basename(mask_path)

    # Find corresponding PNG with same filename
    png_matches = glob.glob(
        os.path.join(DATA_ROOT, "**", "PNG", filename),
        recursive=True
    )

    # Also check direct class folders such as Normal/filename.png
    if not png_matches:
        png_matches = glob.glob(
            os.path.join(DATA_ROOT, "**", filename),
            recursive=True
        )

        png_matches = [
            p for p in png_matches
            if "/MASKS/" not in p
        ]

    # Determine class from corresponding image path
    found_class = None
    image_path = None

    for p in png_matches:
        parts = p.replace("\\", "/").split("/")

        for cls in ["Normal", "Bleeding", "Ischemia"]:
            if cls in parts:
                found_class = cls
                image_path = p
                break

        if found_class is not None:
            break

    records.append({
        "filename": filename,
        "mask_path": mask_path,
        "image_path": image_path,
        "class": found_class
    })

mask_class_df = pd.DataFrame(records)

