import os
import glob
import pandas as pd

DATA_ROOT = "/content/drive/MyDrive/archive (1)/İNME VERİ SETİ"

# 1. All MASK files
mask_files = glob.glob(
    os.path.join(DATA_ROOT, "**", "MASKS", "*.png"),
    recursive=True
)

# 2. All PNG files
png_files = glob.glob(
    os.path.join(DATA_ROOT, "**", "PNG", "*.png"),
    recursive=True
)

# basename → paths
png_map = {}

for p in png_files:
    name = os.path.basename(p)
    png_map.setdefault(name, []).append(p)

# 3. Match MASK → PNG
records = []

for mask_path in mask_files:
    filename = os.path.basename(mask_path)

    matches = png_map.get(filename, [])

    records.append({
        "filename": filename,
        "mask_path": mask_path,
        "png_matches": len(matches),
        "image_path": matches[0] if matches else None
    })

mask_df = pd.DataFrame(records)

print("Total MASK:", len(mask_df))
print("MASK with matching PNG:", mask_df["image_path"].notna().sum())
print("MASK without matching PNG:", mask_df["image_path"].isna().sum())

print("\nExample matched files:")
display(mask_df[mask_df["image_path"].notna()].head(20))

# ============================================================
# CHECK Bilgi.xlsx STRUCTURE
# ============================================================

xlsx_path = os.path.join(DATA_ROOT, "Bilgi.xlsx")

xls = pd.ExcelFile(xlsx_path)

print("Sheets:")
print(xls.sheet_names)

for sheet in xls.sheet_names:
    df_tmp = pd.read_excel(xlsx_path, sheet_name=sheet)

    print("\n" + "="*60)
    print("SHEET:", sheet)
    print("Shape:", df_tmp.shape)
    print("Columns:", list(df_tmp.columns))
