# ============================================================
# OVERLAY vs OFFICIAL MASK — 300 MATCHED IMAGES
# ============================================================

import cv2
import numpy as np
import pandas as pd

def dice_score(a, b):
    a = a.astype(bool)
    b = b.astype(bool)

    intersection = np.logical_and(a, b).sum()

    if a.sum() + b.sum() == 0:
        return 1.0

    return (2.0 * intersection) / (a.sum() + b.sum())


def iou_score(a, b):
    a = a.astype(bool)
    b = b.astype(bool)

    intersection = np.logical_and(a, b).sum()
    union = np.logical_or(a, b).sum()

    if union == 0:
        return 1.0

    return intersection / union


def extract_gt_mask(overlay_rgb):
    r = overlay_rgb[:, :, 0].astype(np.int16)
    g = overlay_rgb[:, :, 1].astype(np.int16)
    b = overlay_rgb[:, :, 2].astype(np.int16)

    colored = (
        ((r > g + 30) & (r > b + 30)) |
        ((b > r + 30) & (b > g + 30))
    )

    return colored.astype(np.uint8)


results = []

for _, row in overlap_df.iterrows():

    mask_img = cv2.imread(
        row["mask_path"],
        cv2.IMREAD_GRAYSCALE
    )

    overlay_img = cv2.imread(
        row["overlay_path"],
        cv2.IMREAD_COLOR
    )

    if mask_img is None or overlay_img is None:
        continue

    # BGR → RGB
    overlay_rgb = cv2.cvtColor(
        overlay_img,
        cv2.COLOR_BGR2RGB
    )

    # Extract lesion from OVERLAY
    overlay_mask = extract_gt_mask(overlay_rgb)

    # Resize to official MASK size
    overlay_mask = cv2.resize(
        overlay_mask,
        (mask_img.shape[1], mask_img.shape[0]),
        interpolation=cv2.INTER_NEAREST
    )

    # Official MASK
    official_mask = (
        mask_img > 0
    ).astype(np.uint8)

    # Metrics
    dice = dice_score(
        overlay_mask,
        official_mask
    )

    iou = iou_score(
        overlay_mask,
        official_mask
    )

    results.append({
        "filename": row["filename"],
        "overlay_pixels": int(overlay_mask.sum()),
        "mask_pixels": int(official_mask.sum()),
        "Dice": dice,
        "IoU": iou
    })


overlay_mask_validation = pd.DataFrame(results)

print("=" * 60)
print("OVERLAY vs OFFICIAL MASK")
print("=" * 60)

print("Valid matched pairs:",
      len(overlay_mask_validation))

print("\nMean Dice:",
      overlay_mask_validation["Dice"].mean())

print("SD Dice:",
      overlay_mask_validation["Dice"].std())

print("\nMean IoU:",
      overlay_mask_validation["IoU"].mean())

print("SD IoU:",
      overlay_mask_validation["IoU"].std())

print("\nMedian Dice:",
      overlay_mask_validation["Dice"].median())

print("Median IoU:",
      overlay_mask_validation["IoU"].median())

