# ============================================================
# GRAD-CAM vs ACTUAL LESION — 331 STROKE IMAGES
# Dice | IoU | Pointing Game | Centroid Distance
# ============================================================

import torch
import numpy as np
import cv2
import pandas as pd
from tqdm.auto import tqdm

model.eval()

THRESHOLD = 0.55

target_layer = model.blocks[3].layers[1].layers.MBconv.layers.conv_c

results = []

for _, row in tqdm(
    stroke_df.iterrows(),
    total=len(stroke_df),
    desc="Grad-CAM validation"
):

    # --------------------------------------------------------
    # Load CT
    # --------------------------------------------------------
    img = cv2.imread(row["image_path"])

    if img is None:
        continue

    img_rgb = cv2.cvtColor(img, cv2.COLOR_BGR2RGB)

    input_tensor = preprocess(
        img_rgb
    ).unsqueeze(0).to(device)

    activations = []
    gradients = []

    def forward_hook(module, inp, output):
        activations.append(output)

    def backward_hook(module, grad_input, grad_output):
        gradients.append(grad_output[0])

    fh = target_layer.register_forward_hook(forward_hook)
    bh = target_layer.register_full_backward_hook(backward_hook)

    # --------------------------------------------------------
    # Forward
    # --------------------------------------------------------
    output = model(input_tensor)

    pred_idx = output.argmax(dim=1).item()

    # Confidence
    probabilities = torch.softmax(output, dim=1)
    confidence = probabilities[0, pred_idx].item()

    # --------------------------------------------------------
    # Backward
    # --------------------------------------------------------
    model.zero_grad()

    output[0, pred_idx].backward()

    fh.remove()
    bh.remove()

    # --------------------------------------------------------
    # Grad-CAM
    # --------------------------------------------------------
    activation = activations[0]
    gradient = gradients[0]

    weights = gradient.mean(
        dim=(2, 3),
        keepdim=True
    )

    cam = (weights * activation).sum(dim=1)
    cam = torch.relu(cam)

    cam = cam[0].detach().cpu().numpy()

    # Normalize
    cam -= cam.min()

    if cam.max() > 0:
        cam /= cam.max()

    # Resize
    cam = cv2.resize(
        cam,
        (224, 224),
        interpolation=cv2.INTER_LINEAR
    )

    # Binary Grad-CAM mask
    gradcam_mask = (
        cam >= THRESHOLD
    ).astype(np.uint8)

    # --------------------------------------------------------
    # Actual lesion from OVERLAY
    # --------------------------------------------------------
    overlay_img = cv2.imread(
        row["overlay_path"],
        cv2.IMREAD_COLOR
    )

    if overlay_img is None:
        continue

    overlay_rgb = cv2.cvtColor(
        overlay_img,
        cv2.COLOR_BGR2RGB
    )

    lesion_mask = extract_gt_mask(overlay_rgb)

    lesion_mask = cv2.resize(
        lesion_mask,
        (224, 224),
        interpolation=cv2.INTER_NEAREST
    )

    # --------------------------------------------------------
    # Dice
    # --------------------------------------------------------
    lesion_bool = lesion_mask.astype(bool)
    cam_bool = gradcam_mask.astype(bool)

    intersection = np.logical_and(
        lesion_bool,
        cam_bool
    ).sum()

    lesion_area = lesion_bool.sum()
    cam_area = cam_bool.sum()

    union = np.logical_or(
        lesion_bool,
        cam_bool
    ).sum()

    if lesion_area + cam_area > 0:
        dice = (
            2 * intersection /
            (lesion_area + cam_area)
        )
    else:
        dice = np.nan

    if union > 0:
        iou = intersection / union
    else:
        iou = np.nan

    # --------------------------------------------------------
    # Pointing Game
    # Maximum Grad-CAM point inside lesion?
    # --------------------------------------------------------
    max_y, max_x = np.unravel_index(
        np.argmax(cam),
        cam.shape
    )

    pointing = int(
        lesion_bool[max_y, max_x]
    )

    # --------------------------------------------------------
    # Centroid distance
    # --------------------------------------------------------
    lesion_M = cv2.moments(
        lesion_mask.astype(np.uint8)
    )

    cam_M = cv2.moments(
        gradcam_mask.astype(np.uint8)
    )

    if lesion_M["m00"] > 0 and cam_M["m00"] > 0:

        lesion_cx = (
            lesion_M["m10"] /
            lesion_M["m00"]
        )

        lesion_cy = (
            lesion_M["m01"] /
            lesion_M["m00"]
        )

        cam_cx = (
            cam_M["m10"] /
            cam_M["m00"]
        )

        cam_cy = (
            cam_M["m01"] /
            cam_M["m00"]
        )

        centroid_distance = np.sqrt(
            (lesion_cx - cam_cx)**2 +
            (lesion_cy - cam_cy)**2
        )

    else:
        centroid_distance = np.nan

    # --------------------------------------------------------
    # Save result
    # --------------------------------------------------------
    results.append({
        "filename": row["filename"],
        "label": row["label"],
        "prediction_idx": pred_idx,
        "confidence": confidence,
        "lesion_area": int(lesion_area),
        "gradcam_area": int(cam_area),
        "Dice": dice,
        "IoU": iou,
        "Pointing_Game": pointing,
        "Centroid_Distance": centroid_distance,
        "correct": (
            (row["label"] == "Bleeding" and pred_idx == 2) or
            (row["label"] == "Ischemia" and pred_idx == 1)
        )
    })


gradcam_validation_df = pd.DataFrame(results)

print("\n" + "="*70)
print("GRAD-CAM vs ACTUAL LESION")
print("="*70)

print("Valid images:", len(gradcam_validation_df))

print("\nOverall:")
print(
    gradcam_validation_df[
        ["Dice", "IoU", "Pointing_Game", "Centroid_Distance"]
    ].describe()
)

print("\nMean ± SD:")
for metric in [
    "Dice",
    "IoU",
    "Pointing_Game",
    "Centroid_Distance"
]:
    print(
        f"{metric}: "
        f"{gradcam_validation_df[metric].mean():.4f} ± "
        f"{gradcam_validation_df[metric].std():.4f}"
    )

print("\nClass-wise:")
print(
    gradcam_validation_df.groupby("label")[
        ["Dice", "IoU", "Pointing_Game", "Centroid_Distance"]
    ].agg(["mean", "std"])
)

# ============================================================
# ACTUAL LESION MORPHOLOGY DATASET — 2,223 STROKE IMAGES
# ============================================================

import os
import glob
import cv2
import numpy as np
import pandas as pd
from tqdm.auto import tqdm

# ------------------------------------------------------------
# Find all OVERLAY images from Bleeding + Ischemia
# ------------------------------------------------------------

overlay_files = []

for cls in ["Bleeding", "Ischemia"]:
    folder = os.path.join(DATA_ROOT, cls, "OVERLAY")
    overlay_files.extend(
        glob.glob(os.path.join(folder, "*.png"))
    )

print("Total OVERLAY images:", len(overlay_files))


# ------------------------------------------------------------
# Extract lesion mask from OVERLAY
# ------------------------------------------------------------

def extract_lesion_mask(overlay_path):

    img = cv2.imread(
        overlay_path,
        cv2.IMREAD_COLOR
    )

    if img is None:
        return None

    rgb = cv2.cvtColor(
        img,
        cv2.COLOR_BGR2RGB
    )

    r = rgb[:, :, 0].astype(np.int16)
    g = rgb[:, :, 1].astype(np.int16)
    b = rgb[:, :, 2].astype(np.int16)

    colored = (
        ((r > g + 30) & (r > b + 30)) |
        ((b > r + 30) & (b > g + 30))
    )

    return colored.astype(np.uint8)


# ------------------------------------------------------------
# Process all images
# ------------------------------------------------------------

lesion_records = []

for path in tqdm(
    overlay_files,
    desc="Extracting lesions"
):

    filename = os.path.basename(path)

    # Determine class from path
    if f"{os.sep}Bleeding{os.sep}" in path:
        label = "Bleeding"
    elif f"{os.sep}Ischemia{os.sep}" in path:
        label = "Ischemia"
    else:
        continue

    mask = extract_lesion_mask(path)

    if mask is None:
        continue

    area = int(mask.sum())

    # Skip only completely empty masks
    if area == 0:
        continue

    h, w = mask.shape

    # --------------------------------------------------------
    # Image coverage
    # --------------------------------------------------------

    image_coverage = (
        area / (h * w)
    ) * 100


    # --------------------------------------------------------
    # Lesion centroid
    # --------------------------------------------------------

    M = cv2.moments(mask)

    if M["m00"] > 0:

        cx = M["m10"] / M["m00"]
        cy = M["m01"] / M["m00"]

        # normalized centroid
        cx_norm = cx / w
        cy_norm = cy / h

    else:
        cx = cy = cx_norm = cy_norm = np.nan


    # --------------------------------------------------------
    # Connected components / morphology
    # --------------------------------------------------------

    num_labels, labels, stats, centroids = cv2.connectedComponentsWithStats(
        mask,
        connectivity=8
    )

    # Exclude background
    component_areas = stats[1:, cv2.CC_STAT_AREA]

    component_count = len(component_areas)

    if component_count > 0:

        largest_component = int(
            component_areas.max()
        )

        largest_component_ratio = (
            largest_component / area
        )

    else:

        largest_component = 0
        largest_component_ratio = np.nan


    lesion_records.append({
        "filename": filename,
        "label": label,
        "lesion_area": area,
        "image_width": w,
        "image_height": h,
        "image_coverage_percent": image_coverage,
        "centroid_x": cx,
        "centroid_y": cy,
        "centroid_x_norm": cx_norm,
        "centroid_y_norm": cy_norm,
        "component_count": component_count,
        "largest_component": largest_component,
        "largest_component_ratio": largest_component_ratio,
        "overlay_path": path
    })


lesion_df = pd.DataFrame(lesion_records)

print("\n" + "="*70)
print("ACTUAL LESION DATASET")
print("="*70)

print("Valid images:", len(lesion_df))

print("\nClass distribution:")
print(
    lesion_df["label"].value_counts()
)

print("\nEmpty masks excluded:",
      len(overlay_files) - len(lesion_df))

display(
    lesion_df.head()
)

# ============================================================
# LESION AREA & COVERAGE
# BLEEDING vs ISCHEMIA
# ============================================================

from scipy.stats import (
    mannwhitneyu,
    shapiro
)
import numpy as np
import pandas as pd

# ------------------------------------------------------------
# Split classes
# ------------------------------------------------------------

bleeding = lesion_df[
    lesion_df["label"] == "Bleeding"
]

ischemia = lesion_df[
    lesion_df["label"] == "Ischemia"
]


# ------------------------------------------------------------
# Function for statistics
# ------------------------------------------------------------

def compare_groups(df1, df2, variable):

    x = df1[variable].dropna().values
    y = df2[variable].dropna().values

    # Mann-Whitney U
    u_stat, p_value = mannwhitneyu(
        x,
        y,
        alternative="two-sided"
    )

    # Cohen's d
    pooled_sd = np.sqrt(
        (
            (len(x)-1) * np.var(x, ddof=1) +
            (len(y)-1) * np.var(y, ddof=1)
        )
        /
        (len(x) + len(y) - 2)
    )

    cohens_d = (
        (np.mean(y) - np.mean(x))
        / pooled_sd
    )

    return {
        "Bleeding_N": len(x),
        "Bleeding_Mean": np.mean(x),
        "Bleeding_SD": np.std(x, ddof=1),
        "Bleeding_Median": np.median(x),

        "Ischemia_N": len(y),
        "Ischemia_Mean": np.mean(y),
        "Ischemia_SD": np.std(y, ddof=1),
        "Ischemia_Median": np.median(y),

        "Mann_Whitney_U": u_stat,
        "p_value": p_value,
        "Cohens_d": cohens_d
    }


# ------------------------------------------------------------
# Area
# ------------------------------------------------------------

area_stats = compare_groups(
    bleeding,
    ischemia,
    "lesion_area"
)

# ------------------------------------------------------------
# Coverage
# ------------------------------------------------------------

coverage_stats = compare_groups(
    bleeding,
    ischemia,
    "image_coverage_percent"
)


# ------------------------------------------------------------
# Display
# ------------------------------------------------------------

stats_table = pd.DataFrame(
    [area_stats, coverage_stats],
    index=[
        "Lesion Area (pixels)",
        "Image Coverage (%)"
    ]
)

print("="*80)
print("LESION MORPHOLOGY — BLEEDING vs ISCHEMIA")
print("="*80)

display(
    stats_table.round(4)
)

print("\nIndividual results:")

print("\nLESION AREA")
for k, v in area_stats.items():
    print(f"{k}: {v:.6f}" if isinstance(v, float) else f"{k}: {v}")

print("\nIMAGE COVERAGE")
for k, v in coverage_stats.items():
    print(f"{k}: {v:.6f}" if isinstance(v, float) else f"{k}: {v}")

