import os
import numpy as np
import pandas as pd
from PIL import Image
from skimage.measure import label, regionprops

root = "/content/drive/MyDrive/archive (1)/İNME VERİ SETİ"

def extract_gt_mask(overlay_rgb):
    r = overlay_rgb[:, :, 0].astype(np.int16)
    g = overlay_rgb[:, :, 1].astype(np.int16)
    b = overlay_rgb[:, :, 2].astype(np.int16)

    colored = (
        ((r > g + 30) & (r > b + 30)) |
        ((b > r + 30) & (b > g + 30))
    )

    return colored.astype(np.uint8)


lesion_records = []

for label_name in ["Bleeding", "Ischemia"]:

    overlay_dir = os.path.join(root, label_name, "OVERLAY")

    files = [
        f for f in os.listdir(overlay_dir)
        if f.lower().endswith((".png", ".jpg", ".jpeg"))
    ]

    for filename in files:

        path = os.path.join(overlay_dir, filename)

        overlay = np.array(Image.open(path).convert("RGB"))

        mask = extract_gt_mask(overlay)

        h, w = mask.shape

        # Connected components
        labeled = label(mask)
        props = regionprops(labeled)

        if len(props) == 0:
            continue

        # Total lesion area
        lesion_area = int(mask.sum())

        # Largest connected component
        largest = max(props, key=lambda r: r.area)

        largest_component = int(largest.area)

        largest_component_ratio = (
            largest_component / lesion_area
            if lesion_area > 0 else np.nan
        )

        # Centroid
        cy, cx = largest.centroid

        lesion_records.append({
            "filename": filename,
            "label": label_name,
            "lesion_area": lesion_area,
            "image_width": w,
            "image_height": h,
            "image_coverage_percent":
                (lesion_area / (w * h)) * 100,
            "centroid_x": cx,
            "centroid_y": cy,
            "centroid_x_norm": cx / w,
            "centroid_y_norm": cy / h,
            "component_count": len(props),
            "largest_component": largest_component,
            "largest_component_ratio":
                largest_component_ratio,
            "overlay_path": path
        })


lesion_df = pd.DataFrame(lesion_records)

print("=" * 80)
print("ACTUAL LESION DATAFRAME")
print("=" * 80)

print("Total valid images:", len(lesion_df))
