# ============================================================
# LESION SHAPE MORPHOLOGY — BLEEDING vs ISCHEMIA
# ============================================================

import numpy as np
import pandas as pd
from skimage.measure import label, regionprops

shape_results = []

for _, row in lesion_df.iterrows():

    # Load overlay
    overlay = plt.imread(row["overlay_path"])

    # Convert RGBA -> RGB if necessary
    if overlay.shape[-1] == 4:
        overlay = overlay[:, :, :3]

    # Convert to uint8
    if overlay.max() <= 1:
        overlay = (overlay * 255).astype(np.uint8)
    else:
        overlay = overlay.astype(np.uint8)

    # Extract lesion mask
    mask = extract_gt_mask(overlay)

    # Connected components
    labeled = label(mask)

    regions_prop = regionprops(labeled)

    if len(regions_prop) == 0:
        continue

    # Largest lesion component
    region = max(regions_prop, key=lambda r: r.area)

    area = region.area
    perimeter = region.perimeter

    # Circularity
    if perimeter > 0:
        circularity = (4 * np.pi * area) / (perimeter ** 2)
    else:
        circularity = np.nan

    # Eccentricity
    eccentricity = region.eccentricity

    # Solidity
    solidity = region.solidity

    # Bounding-box aspect ratio
    minr, minc, maxr, maxc = region.bbox

    height = maxr - minr
    width = maxc - minc

    if min(height, width) > 0:
        aspect_ratio = max(height, width) / min(height, width)
    else:
        aspect_ratio = np.nan

    shape_results.append({
        "filename": row["filename"],
        "label": row["label"],
        "circularity": circularity,
        "eccentricity": eccentricity,
        "solidity": solidity,
        "aspect_ratio": aspect_ratio
    })

shape_df = pd.DataFrame(shape_results)

print("=" * 80)
print("LESION SHAPE MORPHOLOGY — BLEEDING vs ISCHEMIA")
print("=" * 80)

shape_stats = shape_df.groupby("label")[
    ["circularity", "eccentricity", "solidity", "aspect_ratio"]
].agg(
    ["count", "mean", "std", "median"]
)

display(shape_stats.round(4))

# ============================================================
# STATISTICAL TEST — LESION SHAPE MORPHOLOGY
# Bleeding vs Ischemia
# ============================================================

import numpy as np
import pandas as pd
from scipy.stats import mannwhitneyu

features = [
    "circularity",
    "eccentricity",
    "solidity",
    "aspect_ratio"
]

results = []

for feature in features:

    bleeding = shape_df.loc[
        shape_df["label"] == "Bleeding",
        feature
    ].dropna().values

    ischemia = shape_df.loc[
        shape_df["label"] == "Ischemia",
        feature
    ].dropna().values

    # Mann–Whitney U test
    U, p = mannwhitneyu(
        bleeding,
        ischemia,
        alternative="two-sided"
    )

    # Cohen's d
    mean_b = np.mean(bleeding)
    mean_i = np.mean(ischemia)

    sd_b = np.std(bleeding, ddof=1)
    sd_i = np.std(ischemia, ddof=1)

    n_b = len(bleeding)
    n_i = len(ischemia)

    pooled_sd = np.sqrt(
        (
            (n_b - 1) * sd_b**2 +
            (n_i - 1) * sd_i**2
        ) /
        (n_b + n_i - 2)
    )

    cohens_d = (mean_b - mean_i) / pooled_sd

    results.append({
        "Feature": feature,
        "Bleeding Mean": mean_b,
        "Bleeding SD": sd_b,
        "Ischemia Mean": mean_i,
        "Ischemia SD": sd_i,
        "Mann-Whitney U": U,
        "p-value": p,
        "Cohen's d": cohens_d
    })

shape_test_results = pd.DataFrame(results)

print("=" * 100)
print("STATISTICAL VALIDATION OF LESION SHAPE MORPHOLOGY")
print("=" * 100)

display(
    shape_test_results.round(4)
)

# ============================================================
# FDR CORRECTION FOR FOUR LESION SHAPE FEATURES
# ============================================================

from statsmodels.stats.multitest import multipletests

# Raw p-values from the four morphology tests
raw_p = shape_test_results["p-value"].values

# Benjamini-Hochberg FDR correction
reject, p_fdr, _, _ = multipletests(
    raw_p,
    alpha=0.05,
    method="fdr_bh"
)

shape_test_results["p-FDR"] = p_fdr
shape_test_results["Significant (FDR)"] = reject

print("=" * 100)
print("FDR-CORRECTED STATISTICAL VALIDATION OF LESION SHAPE MORPHOLOGY")
print("=" * 100)

display(
    shape_test_results[
        [
            "Feature",
            "Bleeding Mean",
            "Bleeding SD",
            "Ischemia Mean",
            "Ischemia SD",
            "Mann-Whitney U",
            "p-value",
            "p-FDR",
            "Cohen's d",
            "Significant (FDR)"
        ]
    ].round(4)
)

# ============================================
# Step 2: Merge lesion + morphology features
# ============================================

# Lesion/spatial features from lesion_df
lesion_features = lesion_df[
    [
        "filename",
        "label",
        "lesion_area",
        "image_coverage_percent",
        "centroid_x_norm",
        "centroid_y_norm"
    ]
].copy()

# Morphology features from shape_df
morphology_features = shape_df[
    [
        "filename",
        "label",
        "circularity",
        "eccentricity",
        "solidity",
        "aspect_ratio"
    ]
].copy()

# Merge using filename and label
pca_df = pd.merge(
    lesion_features,
    morphology_features,
    on=["filename", "label"],
    how="inner"
)

feature_cols = [
    "lesion_area",
    "image_coverage_percent",
    "circularity",
    "eccentricity",
    "solidity",
    "aspect_ratio",
    "centroid_x_norm",
    "centroid_y_norm"
]

# Keep valid numerical observations
X = pca_df[feature_cols].copy()

valid_mask = np.isfinite(X).all(axis=1)

X = X.loc[valid_mask].copy()
labels = pca_df.loc[valid_mask, "label"].copy()

# Standardization
scaler = StandardScaler()
X_scaled = scaler.fit_transform(X)

print("Merged samples:", len(pca_df))
print("Valid samples:", len(X_scaled))
print("Features:", len(feature_cols))

print("\nClass distribution:")
print(labels.value_counts())

print("\nFeature matrix shape:", X_scaled.shape)

# ============================================
# Step 3: PCA analysis
# ============================================

from sklearn.decomposition import PCA

# Perform PCA
pca = PCA(n_components=8)
X_pca = pca.fit_transform(X_scaled)

# Explained variance
explained_variance = pca.explained_variance_ratio_ * 100
cumulative_variance = np.cumsum(explained_variance)

pca_summary = pd.DataFrame({
    "Principal Component": [f"PC{i}" for i in range(1, 9)],
    "Explained Variance (%)": explained_variance,
    "Cumulative Variance (%)": cumulative_variance
})

print(pca_summary.to_string(index=False))

print("\nPC1 + PC2 explained variance:",
      f"{explained_variance[0] + explained_variance[1]:.2f}%")

# ============================================
# Step 4: PCA phenotype visualization
# ============================================

import matplotlib.pyplot as plt
import numpy as np

# PCA coordinates
pc1 = X_pca[:, 0]
pc2 = X_pca[:, 1]

# Class masks
bleeding_mask = labels.values == "Bleeding"
ischemia_mask = labels.values == "Ischemia"

fig, ax = plt.subplots(figsize=(8, 6))

# Plot both stroke phenotypes
ax.scatter(
    pc1[bleeding_mask],
    pc2[bleeding_mask],
    alpha=0.55,
    s=22,
    label="Bleeding"
)

ax.scatter(
    pc1[ischemia_mask],
    pc2[ischemia_mask],
    alpha=0.55,
    s=22,
    label="Ischemia"
)

# Axis labels with explained variance
ax.set_xlabel(
    f"PC1 ({explained_variance[0]:.2f}% variance)",
    fontsize=11
)

ax.set_ylabel(
    f"PC2 ({explained_variance[1]:.2f}% variance)",
    fontsize=11
)

ax.set_title(
    "Spatial-Morphological Phenotype Space",
    fontsize=14,
    fontweight="bold"
)

ax.legend(frameon=True)
ax.grid(True, linestyle="--", alpha=0.3)

plt.tight_layout()

plt.savefig(
    "Fig7_spatial_morphological_PCA.png",
    dpi=300,
    bbox_inches="tight"
)

plt.show()

# ============================================
# Step 5: Quantitative phenotype separability
# ============================================

from sklearn.metrics import silhouette_score
from sklearn.utils import check_random_state

# Encode classes
y = labels.map({
    "Bleeding": 0,
    "Ischemia": 1
}).values

# ------------------------------------------------
# 1. Silhouette score using the full 8-D phenotype
# ------------------------------------------------
observed_silhouette = silhouette_score(
    X_scaled,
    y,
    metric="euclidean"
)

print(f"Observed Silhouette Score: {observed_silhouette:.4f}")


# ------------------------------------------------
# 2. Permutation test
# ------------------------------------------------
rng = check_random_state(42)

n_permutations = 1000
permuted_scores = np.zeros(n_permutations)

for i in range(n_permutations):
    y_perm = rng.permutation(y)

    permuted_scores[i] = silhouette_score(
        X_scaled,
        y_perm,
        metric="euclidean"
    )

# One-sided permutation p-value
permutation_p = (
    np.sum(permuted_scores >= observed_silhouette) + 1
) / (n_permutations + 1)

print(f"Permutation test p-value: {permutation_p:.4f}")

# ------------------------------------------------
# 3. Null distribution summary
# ------------------------------------------------
print("\nPermutation null distribution:")
print(f"Mean:   {permuted_scores.mean():.4f}")
print(f"SD:     {permuted_scores.std():.4f}")
print(f"95th percentile: {np.percentile(permuted_scores, 95):.4f}")

# ------------------------------------------------
# Interpretation
# ------------------------------------------------
if permutation_p < 0.001:
    significance = "Highly significant (p < 0.001)"
elif permutation_p < 0.01:
    significance = "Significant (p < 0.01)"
elif permutation_p < 0.05:
    significance = "Significant (p < 0.05)"
else:
    significance = "Not statistically significant"

print(f"\nResult: {significance}")

# ============================================================
# FULL ABLATION STUDY
# A1: Size Only
# A2: Size + Shape
# A3: Size + Spatial
# A4: Full Spatial-Morphological Phenotype
# ============================================================

import numpy as np
import pandas as pd

from sklearn.model_selection import StratifiedKFold, cross_validate
from sklearn.pipeline import Pipeline
from sklearn.preprocessing import StandardScaler
from sklearn.linear_model import LogisticRegression
from sklearn.metrics import make_scorer, f1_score


# ------------------------------------------------------------
# 1. Define feature groups
# ------------------------------------------------------------

feature_sets = {

    "A1: Size Only": [
        "lesion_area",
        "image_coverage_percent"
    ],

    "A2: Size + Shape": [
        "lesion_area",
        "image_coverage_percent",
        "circularity",
        "eccentricity",
        "solidity",
        "aspect_ratio"
    ],

    "A3: Size + Spatial": [
        "lesion_area",
        "image_coverage_percent",
        "centroid_x_norm",
        "centroid_y_norm"
    ],

    "A4: Full Phenotype": [
        "lesion_area",
        "image_coverage_percent",
        "circularity",
        "eccentricity",
        "solidity",
        "aspect_ratio",
        "centroid_x_norm",
        "centroid_y_norm"
    ]
}


# ------------------------------------------------------------
# 2. Prepare labels
# ------------------------------------------------------------

y = pca_df["label"].map({
    "Bleeding": 0,
    "Ischemia": 1
}).values


# ------------------------------------------------------------
# 3. Same CV split for ALL experiments
# ------------------------------------------------------------

cv = StratifiedKFold(
    n_splits=5,
    shuffle=True,
    random_state=42
)


# ------------------------------------------------------------
# 4. Same model + same evaluation metrics
# ------------------------------------------------------------

scoring = {
    "accuracy": "accuracy",
    "balanced_accuracy": "balanced_accuracy",
    "f1": make_scorer(f1_score),
    "roc_auc": "roc_auc"
}


# ------------------------------------------------------------
# 5. Run all ablation experiments
# ------------------------------------------------------------

ablation_results = []

for experiment, features in feature_sets.items():

    X = pca_df[features].values

    model = Pipeline([
        ("scaler", StandardScaler()),
        ("classifier", LogisticRegression(
            max_iter=2000,
            random_state=42
        ))
    ])

    scores = cross_validate(
        model,
        X,
        y,
        cv=cv,
        scoring=scoring,
        return_train_score=False
    )

    # Mean ± SD
    accuracy_mean = scores["test_accuracy"].mean()
    accuracy_sd = scores["test_accuracy"].std()

    balanced_mean = scores["test_balanced_accuracy"].mean()
    balanced_sd = scores["test_balanced_accuracy"].std()

    f1_mean = scores["test_f1"].mean()
    f1_sd = scores["test_f1"].std()

    auc_mean = scores["test_roc_auc"].mean()
    auc_sd = scores["test_roc_auc"].std()

    ablation_results.append({
        "Experiment": experiment,
        "Feature Count": len(features),
        "Accuracy": accuracy_mean,
        "Accuracy SD": accuracy_sd,
        "Balanced Accuracy": balanced_mean,
        "Balanced Accuracy SD": balanced_sd,
        "F1": f1_mean,
        "F1 SD": f1_sd,
        "ROC-AUC": auc_mean,
        "ROC-AUC SD": auc_sd
    })


# ------------------------------------------------------------
# 6. Create final ablation table
# ------------------------------------------------------------

ablation_df = pd.DataFrame(ablation_results)


# ------------------------------------------------------------
# 7. Calculate improvement over A1
# ------------------------------------------------------------

baseline_auc = ablation_df.loc[
    ablation_df["Experiment"] == "A1: Size Only",
    "ROC-AUC"
].iloc[0]

baseline_f1 = ablation_df.loc[
    ablation_df["Experiment"] == "A1: Size Only",
    "F1"
].iloc[0]

ablation_df["Δ ROC-AUC vs A1"] = (
    ablation_df["ROC-AUC"] - baseline_auc
)

ablation_df["Δ F1 vs A1"] = (
    ablation_df["F1"] - baseline_f1
)


# ------------------------------------------------------------
# 8. Pretty publication-style table
# ------------------------------------------------------------

display_df = ablation_df.copy()

display_df["Accuracy"] = display_df.apply(
    lambda r: f"{r['Accuracy']:.4f} ± {r['Accuracy SD']:.4f}", axis=1
)

display_df["Balanced Accuracy"] = display_df.apply(
    lambda r: f"{r['Balanced Accuracy']:.4f} ± {r['Balanced Accuracy SD']:.4f}", axis=1
)

display_df["F1"] = display_df.apply(
    lambda r: f"{r['F1']:.4f} ± {r['F1 SD']:.4f}", axis=1
)

display_df["ROC-AUC"] = display_df.apply(
    lambda r: f"{r['ROC-AUC']:.4f} ± {r['ROC-AUC SD']:.4f}", axis=1
)

display_df["Δ ROC-AUC vs A1"] = display_df[
    "Δ ROC-AUC vs A1"
].map(lambda x: f"{x:+.4f}")

display_df["Δ F1 vs A1"] = display_df[
    "Δ F1 vs A1"
].map(lambda x: f"{x:+.4f}")


display_df = display_df[
    [
        "Experiment",
        "Feature Count",
        "Accuracy",
        "Balanced Accuracy",
        "F1",
        "ROC-AUC",
        "Δ ROC-AUC vs A1",
        "Δ F1 vs A1"
    ]
]


print("\n" + "=" * 90)
print("FULL SPATIAL-MORPHOLOGICAL ABLATION STUDY")
print("=" * 90)

display(display_df)


# ------------------------------------------------------------
# 9. Print feature composition
# ------------------------------------------------------------

print("\nFeature composition:")

for experiment, features in feature_sets.items():
    print(f"\n{experiment} ({len(features)} features)")
    for f in features:
        print(f"  • {f}")

# ============================================================
# LESION FRAGMENTATION ANALYSIS
# ============================================================

import numpy as np
import pandas as pd
from scipy.stats import mannwhitneyu
from statsmodels.stats.multitest import multipletests

# ------------------------------------------------------------
# 1. Get fragmentation-related features from lesion_df
# ------------------------------------------------------------

frag_df = lesion_df[
    [
        "filename",
        "label",
        "component_count",
        "largest_component",
        "largest_component_ratio"
    ]
].copy()

# Fragmentation Index
frag_df["fragmentation_index"] = (
    1 - frag_df["largest_component_ratio"]
)

# Remove invalid values
frag_df = frag_df[
    np.isfinite(frag_df["component_count"]) &
    np.isfinite(frag_df["largest_component_ratio"]) &
    np.isfinite(frag_df["fragmentation_index"])
].copy()


# ------------------------------------------------------------
# 2. Separate classes
# ------------------------------------------------------------

bleeding = frag_df[frag_df["label"] == "Bleeding"]
ischemia = frag_df[frag_df["label"] == "Ischemia"]


print("=" * 70)
print("LESION FRAGMENTATION ANALYSIS")
print("=" * 70)

print(f"\nBleeding samples: {len(bleeding)}")
print(f"Ischemia samples: {len(ischemia)}")


# ------------------------------------------------------------
# 3. Descriptive statistics
# ------------------------------------------------------------

features = [
    "component_count",
    "largest_component_ratio",
    "fragmentation_index"
]

for feature in features:

    print(f"\n{feature}")

    print(
        f"Bleeding : "
        f"{bleeding[feature].mean():.4f} ± "
        f"{bleeding[feature].std():.4f} "
        f"(median={bleeding[feature].median():.4f})"
    )

    print(
        f"Ischemia : "
        f"{ischemia[feature].mean():.4f} ± "
        f"{ischemia[feature].std():.4f} "
        f"(median={ischemia[feature].median():.4f})"
    )


# ------------------------------------------------------------
# 4. Statistical comparison
# ------------------------------------------------------------

results = []

for feature in features:

    u_stat, p_value = mannwhitneyu(
        bleeding[feature],
        ischemia[feature],
        alternative="two-sided"
    )

    # Cohen's d
    mean_b = bleeding[feature].mean()
    mean_i = ischemia[feature].mean()

    sd_b = bleeding[feature].std()
    sd_i = ischemia[feature].std()

    n_b = len(bleeding)
    n_i = len(ischemia)

    pooled_sd = np.sqrt(
        ((n_b - 1) * sd_b**2 +
         (n_i - 1) * sd_i**2)
        /
        (n_b + n_i - 2)
    )

    cohens_d = (mean_b - mean_i) / pooled_sd

    results.append({
        "Feature": feature,
        "Mann-Whitney U": u_stat,
        "p-value": p_value,
        "Cohen's d": cohens_d
    })


# ------------------------------------------------------------
# 5. Benjamini-Hochberg FDR correction
# ------------------------------------------------------------

results_df = pd.DataFrame(results)

reject, p_fdr, _, _ = multipletests(
    results_df["p-value"],
    method="fdr_bh"
)

results_df["p_FDR"] = p_fdr
results_df["Significant"] = reject


# ------------------------------------------------------------
# 6. Final statistical table
# ------------------------------------------------------------

print("\n" + "=" * 70)
print("STATISTICAL RESULTS")
print("=" * 70)

display(results_df.round(6))

# ============================================================
# ACTUAL LESION — COVERAGE RANGE
# ============================================================

for label in ["Bleeding", "Ischemia"]:
    values = lesion_df.loc[
        lesion_df["label"] == label,
        "image_coverage_percent"
    ]

    print(f"{label}:")
    print(f"  Min = {values.min():.2f}%")
    print(f"  Max = {values.max():.2f}%")
    print()

