import numpy as np
import pandas as pd

def assign_brain_region(cx_norm, cy_norm):
    """
    Divide image into 6 regions:
    Left/Right × Anterior/Middle/Posterior

    x < 0.5  -> Left
    x >= 0.5 -> Right

    y < 1/3       -> Anterior
    1/3 <= y < 2/3 -> Middle
    y >= 2/3      -> Posterior
    """

    if pd.isna(cx_norm) or pd.isna(cy_norm):
        return None

    side = "Left" if cx_norm < 0.5 else "Right"

    if cy_norm < 1/3:
        position = "Anterior"
    elif cy_norm < 2/3:
        position = "Middle"
    else:
        position = "Posterior"

    return f"{side} {position}"


# Assign region
lesion_df["region"] = lesion_df.apply(
    lambda r: assign_brain_region(
        r["centroid_x_norm"],
        r["centroid_y_norm"]
    ),
    axis=1
)

# ------------------------------------------------------------
# Counts
# ------------------------------------------------------------

region_counts = pd.crosstab(
    lesion_df["label"],
    lesion_df["region"]
)

# Ensure all 6 regions exist
regions = [
    "Left Anterior",
    "Left Middle",
    "Left Posterior",
    "Right Anterior",
    "Right Middle",
    "Right Posterior"
]

region_counts = region_counts.reindex(
    columns=regions,
    fill_value=0
)

# ------------------------------------------------------------
# Convert to percentage within each class
# ------------------------------------------------------------

region_percent = (
    region_counts
    .div(region_counts.sum(axis=1), axis=0)
    * 100
)

print("="*80)
print("ACTUAL LESION — SIX-REGION DISTRIBUTION")
print("="*80)

print("\nCounts:")
display(region_counts)

print("\nPercentage distribution:")
display(region_percent.round(2))

