# ============================================================
# 8. FIND OVERLAY PATH
# ============================================================

def get_overlay_path(image_path):

    image_path = os.path.normpath(
        str(image_path)
    )

    candidates = [

        image_path.replace(
            os.sep + "PNG" + os.sep,
            os.sep + "OVERLAY" + os.sep
        ),

        image_path.replace(
            "/PNG/",
            "/OVERLAY/"
        ),

        image_path.replace(
            "\\PNG\\",
            "\\OVERLAY\\"
        )
    ]

    for path in candidates:

        if os.path.exists(path):

            return path


    return None


# ============================================================
# 9. EXTRACT GROUND-TRUTH MASK
# ============================================================

def extract_gt_mask(overlay_rgb):

    r = overlay_rgb[:, :, 0].astype(
        np.int16
    )

    g = overlay_rgb[:, :, 1].astype(
        np.int16
    )

    b = overlay_rgb[:, :, 2].astype(
        np.int16
    )


    colored = (

        (
            (r > g + 30)
            &
            (r > b + 30)
        )

        |

        (
            (b > r + 30)
            &
            (b > g + 30)
        )
    )


    return colored.astype(
        np.uint8
    )


# ============================================================
# 10. LESION FEATURES
# ============================================================

def calculate_lesion_features(mask):

    mask = (
        mask > 0
    ).astype(
        np.uint8
    )

    H, W = mask.shape

    total_pixels = H * W

    lesion_area = int(
        mask.sum()
    )


    # --------------------------------------------------------
    # Empty mask
    # --------------------------------------------------------

    if lesion_area == 0:

        return {

            "lesion_area_px":
                0,

            "lesion_coverage_percent":
                0.0,

            "centroid_x":
                np.nan,

            "centroid_y":
                np.nan,

            "component_count":
                0,

            "largest_component_ratio":
                np.nan,

            "perimeter_px":
                0.0,

            "circularity":
                np.nan,

            "aspect_ratio":
                np.nan,

            "solidity":
                np.nan,

            "equivalent_diameter_px":
                np.nan
        }


    # --------------------------------------------------------
    # Connected components
    # --------------------------------------------------------

    n_labels, labels, stats, centroids = (
        cv2.connectedComponentsWithStats(
            mask,
            connectivity=8
        )
    )


    component_areas = (
        stats[
            1:,
            cv2.CC_STAT_AREA
        ]
    )


    component_count = len(
        component_areas
    )


    largest_component_ratio = (
        component_areas.max()
        /
        lesion_area
    )


    # --------------------------------------------------------
    # Lesion centroid
    # --------------------------------------------------------

    ys, xs = np.where(
        mask > 0
    )


    centroid_x = (
        xs.mean()
        /
        W
    )


    centroid_y = (
        ys.mean()
        /
        H
    )


    # --------------------------------------------------------
    # Morphology
    # --------------------------------------------------------

    props = regionprops(
        mask
    )


    if len(props) > 0:

        prop = max(
            props,
            key=lambda x: x.area
        )


        minr, minc, maxr, maxc = (
            prop.bbox
        )


        height = (
            maxr - minr
        )


        width = (
            maxc - minc
        )


        if height > 0:

            aspect_ratio = (
                width /
                height
            )

        else:

            aspect_ratio = np.nan


        solidity = (
            prop.solidity
        )


        equivalent_diameter = (
            prop.equivalent_diameter_area
        )


        perimeter_px = (
            prop.perimeter
        )


        if perimeter_px > 0:

            circularity = (
                4 *
                np.pi *
                prop.area
                /
                (
                    perimeter_px ** 2
                )
            )

        else:

            circularity = np.nan


    else:

        aspect_ratio = np.nan
        solidity = np.nan
        equivalent_diameter = np.nan
        perimeter_px = 0.0
        circularity = np.nan


    return {

        "lesion_area_px":
            lesion_area,

        "lesion_coverage_percent":
            (
                lesion_area /
                total_pixels *
                100
            ),

        "centroid_x":
            centroid_x,

        "centroid_y":
            centroid_y,

        "component_count":
            component_count,

        "largest_component_ratio":
            largest_component_ratio,

        "perimeter_px":
            perimeter_px,

        "circularity":
            circularity,

        "aspect_ratio":
            aspect_ratio,

        "solidity":
            solidity,

        "equivalent_diameter_px":
            equivalent_diameter
    }


# ============================================================
# 11. GRAD-CAM FEATURES
# ============================================================

GRADCAM_THRESHOLD = 0.35


def calculate_gradcam_features(
    grayscale_cam,
    threshold=0.35
):

    cam_map = (
        grayscale_cam.copy()
    )


    # Same threshold as your
    # original working visualization
    cam_map[
        cam_map < threshold
    ] = 0


    active = (
        cam_map > 0
    )


    if active.sum() == 0:

        return {

            "gradcam_area_percent":
                0.0,

            "gradcam_centroid_x":
                np.nan,

            "gradcam_centroid_y":
                np.nan
        }


    ys, xs = np.where(
        active
    )


    weights = cam_map[
        active
    ]


    # Weighted Grad-CAM centroid
    centroid_x = (

        np.average(
            xs,
            weights=weights
        )

        /

        cam_map.shape[1]
    )


    centroid_y = (

        np.average(
            ys,
            weights=weights
        )

        /

        cam_map.shape[0]
    )


    area_percent = (

        active.sum()

        /

        active.size

        *

        100
    )


    return {

        "gradcam_area_percent":
            area_percent,

        "gradcam_centroid_x":
            centroid_x,

        "gradcam_centroid_y":
            centroid_y
    }


# ============================================================
# 12. 2 × 3 SPATIAL REGION
# ============================================================

def get_spatial_region(
    x,
    y
):

    if (
        pd.isna(x)
        or
        pd.isna(y)
    ):

        return None


    # 3 columns
    if x < 1 / 3:

        col = 1

    elif x < 2 / 3:

        col = 2

    else:

        col = 3


    # 2 rows
    if y < 0.5:

        row = 1

    else:

        row = 2


    return (
        f"R{row}C{col}"
    )


