print("Validation:", len(val_df))
print("Test:", len(test_df))


# ------------------------------------------------------------
# MD5 HASH FUNCTION
# ------------------------------------------------------------

def md5_hash(path):
    h = hashlib.md5()

    with open(path, "rb") as f:
        for chunk in iter(lambda: f.read(8192), b""):
            h.update(chunk)

    return h.hexdigest()


# ------------------------------------------------------------
# CALCULATE HASHES
# ------------------------------------------------------------

def add_hash(df_input):

    df_out = df_input.copy()

    df_out["md5"] = df_out["image_path"].apply(md5_hash)

    return df_out


print("\nCalculating hashes...")

train_h = add_hash(train_df)
val_h   = add_hash(val_df)
test_h  = add_hash(test_df)


# ------------------------------------------------------------
# CHECK CROSS-SPLIT EXACT DUPLICATES
# ------------------------------------------------------------

train_hashes = set(train_h["md5"])
val_hashes   = set(val_h["md5"])
test_hashes  = set(test_h["md5"])

train_val = train_hashes & val_hashes
train_test = train_hashes & test_hashes
val_test = val_hashes & test_hashes

print("\n======================================")
print("EXACT DUPLICATE LEAKAGE AUDIT")
print("======================================")

print("Train ↔ Validation :", len(train_val))
print("Train ↔ Test       :", len(train_test))
print("Validation ↔ Test  :", len(val_test))

print("\n======================================")

if len(train_test) == 0:
    print("✅ NO EXACT DUPLICATE BETWEEN TRAIN AND TEST")
else:
    print("⚠️ EXACT DUPLICATES FOUND BETWEEN TRAIN AND TEST")

if len(train_val) == 0:
    print("✅ NO EXACT DUPLICATE BETWEEN TRAIN AND VALIDATION")
else:
    print("⚠️ EXACT DUPLICATES FOUND BETWEEN TRAIN AND VALIDATION")

if len(val_test) == 0:
    print("✅ NO EXACT DUPLICATE BETWEEN VALIDATION AND TEST")
else:
    print("⚠️ EXACT DUPLICATES FOUND BETWEEN VALIDATION AND TEST")

# ============================================================
# STEP 3: GLOBAL EXACT-DUPLICATE GROUPING
# ============================================================

import hashlib
import pandas as pd
from tqdm import tqdm

def md5_hash(path):
    h = hashlib.md5()
    with open(path, "rb") as f:
        for chunk in iter(lambda: f.read(8192), b""):
            h.update(chunk)
    return h.hexdigest()

print("Calculating MD5 hashes for all images...")

df_hash = df.copy()

df_hash["md5"] = [
    md5_hash(path)
    for path in tqdm(df_hash["image_path"])
]

print("\nTotal images:", len(df_hash))
print("Unique MD5 hashes:", df_hash["md5"].nunique())

# ------------------------------------------------------------
# FIND DUPLICATE GROUPS
# ------------------------------------------------------------

duplicate_groups = (
    df_hash[df_hash["md5"].duplicated(keep=False)]
    .sort_values("md5")
)

print("\n======================================")
print("GLOBAL EXACT DUPLICATE AUDIT")
print("======================================")

print("Images involved in duplicate groups:",
      len(duplicate_groups))

print("Unique duplicate groups:",
      duplicate_groups["md5"].nunique())

print("Extra duplicate copies:",
      len(duplicate_groups) - duplicate_groups["md5"].nunique())

# Show duplicate groups
for md5, group in duplicate_groups.groupby("md5"):

    print("\nMD5:", md5)

    for _, row in group.iterrows():
        print("Label:", row["label"])
        print("Path :", row["image_path"])

# ============================================================
# STEP 3: REMOVE EXACT DUPLICATE IMAGES
# Keep ONE image from each duplicate group
# ============================================================

# df_hash already contains:
# image_path, label, md5

print("Before duplicate removal:")
print("Total images:", len(df_hash))
print("Unique MD5:", df_hash["md5"].nunique())

# ------------------------------------------------------------
# KEEP FIRST IMAGE OF EACH MD5 GROUP
# ------------------------------------------------------------

df_clean = df_hash.drop_duplicates(
    subset="md5",
    keep="first"
).copy()

# ------------------------------------------------------------
# RESET INDEX
# ------------------------------------------------------------

df_clean = df_clean.reset_index(drop=True)

# ------------------------------------------------------------
# RESULTS
# ------------------------------------------------------------

print("\n======================================")
print("DUPLICATE REMOVAL RESULT")
print("======================================")

print("Original images :", len(df_hash))
print("Unique images   :", len(df_clean))
print("Removed images  :", len(df_hash) - len(df_clean))

