# STEP 5: VERIFY FINAL SPLIT FOR EXACT DUPLICATE LEAKAGE
# ============================================================

import hashlib
from tqdm import tqdm

def md5_hash(path):
    h = hashlib.md5()
    with open(path, "rb") as f:
        for chunk in iter(lambda: f.read(8192), b""):
            h.update(chunk)
    return h.hexdigest()


def get_hashes(dataframe):

    return {
        md5_hash(path)
        for path in tqdm(
            dataframe["image_path"],
            desc="Hashing images"
        )
    }


print("Calculating final split hashes...\n")

train_hashes = get_hashes(train_df)
val_hashes   = get_hashes(val_df)
test_hashes  = get_hashes(test_df)


train_val = train_hashes & val_hashes
train_test = train_hashes & test_hashes
val_test = val_hashes & test_hashes


print("\n======================================")
print("FINAL EXACT DUPLICATE LEAKAGE AUDIT")
print("======================================")

print("Train ↔ Validation :", len(train_val))
print("Train ↔ Test       :", len(train_test))
print("Validation ↔ Test  :", len(val_test))

if len(train_val) == 0 and len(train_test) == 0 and len(val_test) == 0:
    print("\n✅ FINAL SPLIT HAS NO EXACT DUPLICATE OVERLAP")
else:
    print("\n⚠️ EXACT DUPLICATE OVERLAP STILL EXISTS")

