# ============================================================
# PREREQUISITE: DATASET + TRANSFORMS FOR CNN BASELINES
# ============================================================

from PIL import Image
from torch.utils.data import Dataset
from torchvision import transforms

# ------------------------------------------------------------
# LABEL MAPPING
# ------------------------------------------------------------

label_to_idx = {
    "Normal": 0,
    "Ischemia": 1,
    "Bleeding": 2
}

idx_to_label = {
    0: "Normal",
    1: "Ischemia",
    2: "Bleeding"
}


# ------------------------------------------------------------
# DATASET CLASS
# ------------------------------------------------------------

class StrokeDataset(Dataset):

    def __init__(self, dataframe, transform=None):
        self.dataframe = dataframe.reset_index(drop=True)
        self.transform = transform

    def __len__(self):
        return len(self.dataframe)

    def __getitem__(self, idx):

        image_path = self.dataframe.loc[idx, "image_path"]
        label = self.dataframe.loc[idx, "label"]

        # Load image
        image = Image.open(image_path).convert("RGB")

        # Apply transforms
        if self.transform:
            image = self.transform(image)

        # Convert label
        label = label_to_idx[label]

        return image, label


# ------------------------------------------------------------
# TRANSFORMS
# Same preprocessing protocol as your original experiment
# ------------------------------------------------------------

train_transform = transforms.Compose([
    transforms.Resize((224, 224)),
    transforms.RandomHorizontalFlip(),
    transforms.RandomRotation(15),
    transforms.ColorJitter(
        brightness=0.2,
        contrast=0.2,
        saturation=0.2,
        hue=0.05
    ),
    transforms.ToTensor(),
    transforms.Normalize(
        mean=[0.485, 0.456, 0.406],
        std=[0.229, 0.224, 0.225]
    )
])

val_transform = transforms.Compose([
    transforms.Resize((224, 224)),
    transforms.ToTensor(),
    transforms.Normalize(
        mean=[0.485, 0.456, 0.406],
        std=[0.229, 0.224, 0.225]
    )
])


# ------------------------------------------------------------
# CHECK
# ------------------------------------------------------------

print("StrokeDataset defined successfully.")

print("\nTrain:", len(train_df))
print("Validation:", len(val_df))
print("Test:", len(test_df))

print("\nLabel mapping:")
print(label_to_idx)

# ============================================================
# RESNET50 CNN BASELINE — TRAINING
# ============================================================

import torch
import torch.nn as nn
import torch.optim as optim
from torch.utils.data import DataLoader
from torchvision import models
from sklearn.metrics import accuracy_score
import numpy as np
import random

# ------------------------------------------------------------
# 1. REPRODUCIBILITY
# ------------------------------------------------------------

SEED = 42

random.seed(SEED)
np.random.seed(SEED)
torch.manual_seed(SEED)
torch.cuda.manual_seed_all(SEED)

torch.backends.cudnn.deterministic = True
torch.backends.cudnn.benchmark = False


# ------------------------------------------------------------
# 2. DEVICE
# ------------------------------------------------------------

device = torch.device(
    "cuda" if torch.cuda.is_available() else "cpu"
)

print("Device:", device)


# ------------------------------------------------------------
# 3. DATASETS
# ------------------------------------------------------------

train_dataset = StrokeDataset(
    train_df,
    transform=train_transform
)

val_dataset = StrokeDataset(
    val_df,
    transform=val_transform
)

test_dataset = StrokeDataset(
    test_df,
    transform=val_transform
)


# ------------------------------------------------------------
# 4. DATALOADERS
# ------------------------------------------------------------

BATCH_SIZE = 32

train_loader = DataLoader(
    train_dataset,
    batch_size=BATCH_SIZE,
    shuffle=True,
    num_workers=2,
    pin_memory=True
)

val_loader = DataLoader(
    val_dataset,
    batch_size=BATCH_SIZE,
    shuffle=False,
    num_workers=2,
    pin_memory=True
)

test_loader = DataLoader(
    test_dataset,
    batch_size=BATCH_SIZE,
    shuffle=False,
    num_workers=2,
    pin_memory=True
)

print("Train batches:", len(train_loader))
print("Validation batches:", len(val_loader))
print("Test batches:", len(test_loader))


# ------------------------------------------------------------
# 5. RESNET50
# ------------------------------------------------------------

model = models.resnet50(
    weights=models.ResNet50_Weights.DEFAULT
)

num_features = model.fc.in_features

model.fc = nn.Linear(
    num_features,
    3
)

model = model.to(device)

print("ResNet50 loaded successfully.")


# ------------------------------------------------------------
# 6. LOSS + OPTIMIZER
# ------------------------------------------------------------

criterion = nn.CrossEntropyLoss()

optimizer = optim.AdamW(
    model.parameters(),
    lr=3e-4,
    weight_decay=1e-4
)

scheduler = optim.lr_scheduler.ReduceLROnPlateau(
    optimizer,
    mode="min",
    factor=0.5,
    patience=2
)


# ------------------------------------------------------------
# 7. TRAINING
# ------------------------------------------------------------

NUM_EPOCHS = 15

best_val_loss = float("inf")

save_path = (
    "/content/drive/MyDrive/"
    "resnet50_best_seed42.pth"
)

train_losses = []
val_losses = []

train_accs = []
val_accs = []


for epoch in range(NUM_EPOCHS):

    # =========================
    # TRAIN
    # =========================

    model.train()

    running_loss = 0.0

    train_preds = []
    train_targets = []

    for images, labels in train_loader:

        images = images.to(
            device,
            non_blocking=True
        )

        labels = labels.to(
            device,
            non_blocking=True
        )

        optimizer.zero_grad()

        outputs = model(images)

        loss = criterion(
            outputs,
            labels
        )

        loss.backward()

        optimizer.step()

        running_loss += (
            loss.item() * images.size(0)
        )

        preds = torch.argmax(
            outputs,
            dim=1
        )

        train_preds.extend(
            preds.detach().cpu().numpy()
        )

        train_targets.extend(
            labels.detach().cpu().numpy()
        )


    train_loss = (
        running_loss /
        len(train_dataset)
    )

    train_acc = accuracy_score(
        train_targets,
        train_preds
    )


    # =========================
    # VALIDATION
    # =========================

    model.eval()

    val_running_loss = 0.0

    val_preds = []
    val_targets = []

    with torch.no_grad():

        for images, labels in val_loader:

            images = images.to(
                device,
                non_blocking=True
            )

            labels = labels.to(
                device,
                non_blocking=True
            )

            outputs = model(images)

            loss = criterion(
                outputs,
                labels
            )

            val_running_loss += (
                loss.item() * images.size(0)
            )

            preds = torch.argmax(
                outputs,
                dim=1
            )

            val_preds.extend(
                preds.cpu().numpy()
            )

            val_targets.extend(
                labels.cpu().numpy()
            )


    val_loss = (
        val_running_loss /
        len(val_dataset)
    )

    val_acc = accuracy_score(
        val_targets,
        val_preds
    )


    # =========================
    # SCHEDULER
    # =========================

    scheduler.step(val_loss)


    # =========================
    # SAVE BEST MODEL
    # =========================

    if val_loss < best_val_loss:

        best_val_loss = val_loss

        torch.save(
            model.state_dict(),
            save_path
        )

        marker = " ⭐ BEST"

    else:

        marker = ""


    # =========================
    # HISTORY
    # =========================

    train_losses.append(train_loss)
    val_losses.append(val_loss)

    train_accs.append(train_acc)
    val_accs.append(val_acc)


    # =========================
    # PRINT
    # =========================

    print(
        f"Epoch [{epoch+1:02d}/{NUM_EPOCHS}] "
        f"Train Loss: {train_loss:.4f} | "
        f"Train Acc: {train_acc*100:.2f}% | "
        f"Val Loss: {val_loss:.4f} | "
        f"Val Acc: {val_acc*100:.2f}%"
        f"{marker}"
    )


print("\nTraining completed.")
print("Best model saved at:")
print(save_path)

# =========================
# ResNet50 - Test Evaluation
# =========================

import torch
import numpy as np
from sklearn.metrics import (
    accuracy_score,
    precision_score,
    recall_score,
    f1_score,
    classification_report,
    confusion_matrix
)
import matplotlib.pyplot as plt
import seaborn as sns

# Load best model
best_model_path = "/content/drive/MyDrive/resnet50_best_seed42.pth"

model.load_state_dict(torch.load(best_model_path, map_location=device))
model = model.to(device)
model.eval()

all_preds = []
all_labels = []

with torch.no_grad():
    for images, labels in test_loader:
        images = images.to(device)
        labels = labels.to(device)

        outputs = model(images)
        preds = torch.argmax(outputs, dim=1)

        all_preds.extend(preds.cpu().numpy())
        all_labels.extend(labels.cpu().numpy())

# Convert to numpy
all_preds = np.array(all_preds)
all_labels = np.array(all_labels)

# =========================
# Overall Metrics
# =========================

test_accuracy = accuracy_score(all_labels, all_preds)

test_precision = precision_score(
    all_labels, all_preds,
    average="weighted",
    zero_division=0
)

test_recall = recall_score(
    all_labels, all_preds,
    average="weighted",
    zero_division=0
)

test_f1 = f1_score(
    all_labels, all_preds,
    average="weighted",
    zero_division=0
)

print("\n==============================")
print("ResNet50 TEST RESULTS")
print("==============================")
print(f"Test Accuracy : {test_accuracy * 100:.2f}%")
print(f"Test Precision: {test_precision * 100:.2f}%")
print(f"Test Recall   : {test_recall * 100:.2f}%")
print(f"Test F1-score : {test_f1 * 100:.2f}%")

# =========================
# Classification Report
# =========================

target_names = [
    idx_to_label[i] for i in sorted(idx_to_label.keys())
]

print("\nClassification Report:")
print(
    classification_report(
        all_labels,
        all_preds,
        target_names=target_names,
        digits=4,
        zero_division=0
    )
)

# =========================
# Confusion Matrix
# =========================

cm = confusion_matrix(all_labels, all_preds)

plt.figure(figsize=(7, 6))
sns.heatmap(
    cm,
    annot=True,
    fmt="d",
    xticklabels=target_names,
    yticklabels=target_names
)

plt.xlabel("Predicted Label")
plt.ylabel("True Label")
plt.title("ResNet50 Confusion Matrix")
plt.tight_layout()
plt.show()

# ==========================================
# DenseNet121 Training - Seed 42
# ==========================================

import torch
import torch.nn as nn
import torch.optim as optim
from torchvision.models import densenet121, DenseNet121_Weights
from sklearn.metrics import (
    accuracy_score,
    precision_score,
    recall_score,
    f1_score,
    classification_report,
    confusion_matrix
)
import numpy as np
import matplotlib.pyplot as plt
import seaborn as sns

# -----------------------------
# Reproducibility
# -----------------------------
SEED = 42

torch.manual_seed(SEED)
torch.cuda.manual_seed_all(SEED)
np.random.seed(SEED)

if torch.backends.cudnn.is_available():
    torch.backends.cudnn.deterministic = True
    torch.backends.cudnn.benchmark = False

print("Device:", device)

# -----------------------------
# DataLoaders
# -----------------------------
print("Train batches:", len(train_loader))
print("Validation batches:", len(val_loader))
print("Test batches:", len(test_loader))

# -----------------------------
# Load pretrained DenseNet121
# -----------------------------
weights = DenseNet121_Weights.DEFAULT

model = densenet121(weights=weights)

# Replace classifier for 3 classes
num_features = model.classifier.in_features
model.classifier = nn.Linear(num_features, 3)

model = model.to(device)

print("DenseNet121 loaded successfully.")

# -----------------------------
# Loss function
# -----------------------------
criterion = nn.CrossEntropyLoss()

# -----------------------------
# Optimizer
# -----------------------------
optimizer = optim.AdamW(
    model.parameters(),
    lr=3e-4,
    weight_decay=1e-4
)

# -----------------------------
# Learning-rate scheduler
# -----------------------------
scheduler = optim.lr_scheduler.ReduceLROnPlateau(
    optimizer,
    mode="min",
    factor=0.5,
    patience=2
)

# -----------------------------
# Training settings
# -----------------------------
num_epochs = 15

best_val_acc = 0.0

best_model_path = (
    "/content/drive/MyDrive/"
    "densenet121_best_seed42.pth"
)

train_losses = []
val_losses = []

train_accs = []
val_accs = []

# ==========================================
# Training Loop
# ==========================================

for epoch in range(num_epochs):

    # -----------------------------
    # TRAIN
    # -----------------------------
    model.train()

    running_loss = 0.0
    correct = 0
    total = 0

    for images, labels in train_loader:

        images = images.to(device)
        labels = labels.to(device)

        optimizer.zero_grad()

        outputs = model(images)

        loss = criterion(outputs, labels)

        loss.backward()

        optimizer.step()

        running_loss += loss.item() * images.size(0)

        _, predicted = torch.max(outputs, 1)

        total += labels.size(0)
        correct += (predicted == labels).sum().item()

    train_loss = running_loss / total
    train_acc = correct / total

    # -----------------------------
    # VALIDATION
    # -----------------------------
    model.eval()

    val_running_loss = 0.0
    val_correct = 0
    val_total = 0

    with torch.no_grad():

        for images, labels in val_loader:

            images = images.to(device)
            labels = labels.to(device)

            outputs = model(images)

            loss = criterion(outputs, labels)

            val_running_loss += loss.item() * images.size(0)

            _, predicted = torch.max(outputs, 1)

            val_total += labels.size(0)
            val_correct += (predicted == labels).sum().item()

    val_loss = val_running_loss / val_total
    val_acc = val_correct / val_total

    # -----------------------------
    # Scheduler
    # -----------------------------
    scheduler.step(val_loss)

    # -----------------------------
    # Save history
    # -----------------------------
    train_losses.append(train_loss)
    val_losses.append(val_loss)

    train_accs.append(train_acc)
    val_accs.append(val_acc)

    # -----------------------------
    # Save best model
    # -----------------------------
    best_marker = ""

    if val_acc > best_val_acc:

        best_val_acc = val_acc

        torch.save(
            model.state_dict(),
            best_model_path
        )

        best_marker = " ⭐ BEST"

    print(
        f"Epoch [{epoch+1:02d}/{num_epochs}] "
        f"Train Loss: {train_loss:.4f} | "
        f"Train Acc: {train_acc*100:.2f}% | "
        f"Val Loss: {val_loss:.4f} | "
        f"Val Acc: {val_acc*100:.2f}%"
        f"{best_marker}"
    )

print("\nTraining completed.")
print("Best validation accuracy:",
      f"{best_val_acc*100:.2f}%")

print("Best model saved at:")
print(best_model_path)

# ==========================================
# DenseNet121 - Test Evaluation
# ==========================================

import torch
import numpy as np
from sklearn.metrics import (
    accuracy_score,
    precision_score,
    recall_score,
    f1_score,
    classification_report,
    confusion_matrix
)
import matplotlib.pyplot as plt
import seaborn as sns

# -----------------------------
# Load best DenseNet121 model
# -----------------------------
best_model_path = "/content/drive/MyDrive/densenet121_best_seed42.pth"

model.load_state_dict(
    torch.load(best_model_path, map_location=device)
)

model = model.to(device)
model.eval()

# -----------------------------
# Test prediction
# -----------------------------
all_preds = []
all_labels = []

with torch.no_grad():

    for images, labels in test_loader:

        images = images.to(device)
        labels = labels.to(device)

        outputs = model(images)

        preds = torch.argmax(outputs, dim=1)

        all_preds.extend(preds.cpu().numpy())
        all_labels.extend(labels.cpu().numpy())

all_preds = np.array(all_preds)
all_labels = np.array(all_labels)

# -----------------------------
# Overall metrics
# -----------------------------
test_accuracy = accuracy_score(
    all_labels, all_preds
)

test_precision = precision_score(
    all_labels,
    all_preds,
    average="weighted",
    zero_division=0
)

test_recall = recall_score(
    all_labels,
    all_preds,
    average="weighted",
    zero_division=0
)

test_f1 = f1_score(
    all_labels,
    all_preds,
    average="weighted",
    zero_division=0
)

print("\n==============================")
print("DenseNet121 TEST RESULTS")
print("==============================")

print(f"Test Accuracy : {test_accuracy * 100:.2f}%")
print(f"Test Precision: {test_precision * 100:.2f}%")
print(f"Test Recall   : {test_recall * 100:.2f}%")
print(f"Test F1-score : {test_f1 * 100:.2f}%")

# -----------------------------
# Classification Report
# -----------------------------
target_names = [
    idx_to_label[i]
    for i in sorted(idx_to_label.keys())
]

print("\nClassification Report:")

print(
    classification_report(
        all_labels,
        all_preds,
        target_names=target_names,
        digits=4,
        zero_division=0
    )
)

# -----------------------------
# Confusion Matrix
# -----------------------------
cm = confusion_matrix(
    all_labels,
    all_preds
)

plt.figure(figsize=(7, 6))

sns.heatmap(
    cm,
    annot=True,
    fmt="d",
    xticklabels=target_names,
    yticklabels=target_names
)

plt.xlabel("Predicted Label")
plt.ylabel("True Label")
plt.title("DenseNet121 Confusion Matrix")

plt.tight_layout()
plt.show()

# ==========================================
# EfficientNet-B3 Training - Seed 42
# ==========================================

import torch
import torch.nn as nn
import torch.optim as optim
from torchvision.models import efficientnet_b3, EfficientNet_B3_Weights

import numpy as np

# -----------------------------
# Reproducibility
# -----------------------------
SEED = 42

torch.manual_seed(SEED)
torch.cuda.manual_seed_all(SEED)
np.random.seed(SEED)

if torch.backends.cudnn.is_available():
    torch.backends.cudnn.deterministic = True
    torch.backends.cudnn.benchmark = False

print("Device:", device)

# -----------------------------
# DataLoaders
# -----------------------------
print("Train batches:", len(train_loader))
print("Validation batches:", len(val_loader))
print("Test batches:", len(test_loader))

# -----------------------------
# Load pretrained EfficientNet-B3
# -----------------------------
weights = EfficientNet_B3_Weights.DEFAULT

model = efficientnet_b3(weights=weights)

# Replace final classifier for 3 classes
num_features = model.classifier[1].in_features

model.classifier[1] = nn.Linear(
    num_features,
    3
)

model = model.to(device)

print("EfficientNet-B3 loaded successfully.")

# -----------------------------
# Loss function
# -----------------------------
criterion = nn.CrossEntropyLoss()

# -----------------------------
# Optimizer
# -----------------------------
optimizer = optim.AdamW(
    model.parameters(),
    lr=3e-4,
    weight_decay=1e-4
)

# -----------------------------
# Learning-rate scheduler
# -----------------------------
scheduler = optim.lr_scheduler.ReduceLROnPlateau(
    optimizer,
    mode="min",
    factor=0.5,
    patience=2
)

# -----------------------------
# Training settings
# -----------------------------
num_epochs = 15

best_val_acc = 0.0

best_model_path = (
    "/content/drive/MyDrive/"
    "efficientnet_b3_best_seed42.pth"
)

train_losses = []
val_losses = []

train_accs = []
val_accs = []

# ==========================================
# Training Loop
# ==========================================

for epoch in range(num_epochs):

    # -----------------------------
    # TRAIN
    # -----------------------------
    model.train()

    running_loss = 0.0
    correct = 0
    total = 0

    for images, labels in train_loader:

        images = images.to(device)
        labels = labels.to(device)

        optimizer.zero_grad()

        outputs = model(images)

        loss = criterion(outputs, labels)

        loss.backward()

        optimizer.step()

        running_loss += loss.item() * images.size(0)

        _, predicted = torch.max(outputs, 1)

        total += labels.size(0)
        correct += (predicted == labels).sum().item()

    train_loss = running_loss / total
    train_acc = correct / total

    # -----------------------------
    # VALIDATION
    # -----------------------------
    model.eval()

    val_running_loss = 0.0
    val_correct = 0
    val_total = 0

    with torch.no_grad():

        for images, labels in val_loader:

            images = images.to(device)
            labels = labels.to(device)

            outputs = model(images)

            loss = criterion(outputs, labels)

            val_running_loss += loss.item() * images.size(0)

            _, predicted = torch.max(outputs, 1)

            val_total += labels.size(0)
            val_correct += (predicted == labels).sum().item()

    val_loss = val_running_loss / val_total
    val_acc = val_correct / val_total

    # -----------------------------
    # Scheduler
    # -----------------------------
    scheduler.step(val_loss)

    # -----------------------------
    # Save history
    # -----------------------------
    train_losses.append(train_loss)
    val_losses.append(val_loss)

    train_accs.append(train_acc)
    val_accs.append(val_acc)

    # -----------------------------
    # Save best model
    # -----------------------------
    best_marker = ""

    if val_acc > best_val_acc:

        best_val_acc = val_acc

        torch.save(
            model.state_dict(),
            best_model_path
        )

        best_marker = " ⭐ BEST"

    print(
        f"Epoch [{epoch+1:02d}/{num_epochs}] "
        f"Train Loss: {train_loss:.4f} | "
        f"Train Acc: {train_acc*100:.2f}% | "
        f"Val Loss: {val_loss:.4f} | "
        f"Val Acc: {val_acc*100:.2f}%"
        f"{best_marker}"
    )

print("\nTraining completed.")
print(
    "Best validation accuracy:",
    f"{best_val_acc*100:.2f}%"
)

print("Best model saved at:")
print(best_model_path)

