import torch
import torch.nn as nn
import torch.optim as optim
import numpy as np

from torchvision.models import maxvit_t, MaxVit_T_Weights

# -----------------------------
# Reproducibility
# -----------------------------
SEED = 42

torch.manual_seed(SEED)
torch.cuda.manual_seed_all(SEED)
np.random.seed(SEED)

if torch.backends.cudnn.is_available():
    torch.backends.cudnn.deterministic = True
    torch.backends.cudnn.benchmark = False

print("Device:", device)

print("Train batches:", len(train_loader))
print("Validation batches:", len(val_loader))
print("Test batches:", len(test_loader))

# -----------------------------
# Load pretrained MaxViT-T
# -----------------------------
weights = MaxVit_T_Weights.DEFAULT

model = maxvit_t(weights=weights)

# -----------------------------
# CORRECT classifier replacement
# MaxViT classifier:
# 0 AdaptiveAvgPool
# 1 Flatten
# 2 LayerNorm
# 3 Linear(512 -> 512)
# 4 Tanh
# 5 Linear(512 -> 1000)
# -----------------------------

num_features = model.classifier[5].in_features

model.classifier[5] = nn.Linear(
    num_features,
    3,
    bias=False
)

model = model.to(device)

print("MaxViT loaded successfully.")
print("Final classifier:", model.classifier[5])

# -----------------------------
# Loss
# -----------------------------
criterion = nn.CrossEntropyLoss()

# -----------------------------
# Optimizer
# -----------------------------
optimizer = optim.AdamW(
    model.parameters(),
    lr=3e-4,
    weight_decay=1e-4
)

# -----------------------------
# Scheduler
# -----------------------------
scheduler = optim.lr_scheduler.ReduceLROnPlateau(
    optimizer,
    mode="min",
    factor=0.5,
    patience=2
)

# -----------------------------
# Training settings
# -----------------------------
num_epochs = 15

best_val_acc = 0.0

best_model_path = (
    "/content/drive/MyDrive/"
    "maxvit_t_best_clean_seed42.pth"
)

train_losses = []
val_losses = []

train_accs = []
val_accs = []

# ==========================================
# Training Loop
# ==========================================

for epoch in range(num_epochs):

    # -----------------------------
    # TRAIN
    # -----------------------------
    model.train()

    running_loss = 0.0
    correct = 0
    total = 0

    for images, labels in train_loader:

        images = images.to(device)
        labels = labels.to(device)

        optimizer.zero_grad()

        outputs = model(images)

        loss = criterion(outputs, labels)

        loss.backward()

        optimizer.step()

        running_loss += loss.item() * images.size(0)

        _, predicted = torch.max(outputs, 1)

        total += labels.size(0)
        correct += (predicted == labels).sum().item()

    train_loss = running_loss / total
    train_acc = correct / total

    # -----------------------------
    # VALIDATION
    # -----------------------------
    model.eval()

    val_running_loss = 0.0
    val_correct = 0
    val_total = 0

    with torch.no_grad():

        for images, labels in val_loader:

            images = images.to(device)
            labels = labels.to(device)

            outputs = model(images)

            loss = criterion(outputs, labels)

            val_running_loss += loss.item() * images.size(0)

            _, predicted = torch.max(outputs, 1)

            val_total += labels.size(0)

            val_correct += (
                predicted == labels
            ).sum().item()

    val_loss = val_running_loss / val_total
    val_acc = val_correct / val_total

    # -----------------------------
    # Scheduler
    # -----------------------------
    scheduler.step(val_loss)

    # -----------------------------
    # Save history
    # -----------------------------
    train_losses.append(train_loss)
    val_losses.append(val_loss)

    train_accs.append(train_acc)
    val_accs.append(val_acc)

    # -----------------------------
    # Save best model
    # -----------------------------
    best_marker = ""

    if val_acc > best_val_acc:

        best_val_acc = val_acc

        torch.save(
            model.state_dict(),
            best_model_path
        )

        best_marker = " ⭐ BEST"

    # -----------------------------
    # Print
    # -----------------------------
    print(
        f"Epoch [{epoch+1:02d}/{num_epochs}] "
        f"Train Loss: {train_loss:.4f} | "
        f"Train Acc: {train_acc*100:.2f}% | "
        f"Val Loss: {val_loss:.4f} | "
        f"Val Acc: {val_acc*100:.2f}%"
        f"{best_marker}"
    )

print("\n==========================================")
print("MaxViT Training Completed")
print("==========================================")

print(
    "Best validation accuracy:",
    f"{best_val_acc*100:.2f}%"
)

print("\nBest model saved at:")
print(best_model_path)

# ============================================================
# CNN BASELINE 1: RESNET50
# ============================================================

import torch
import torch.nn as nn
import torch.optim as optim
from torch.utils.data import DataLoader
from torchvision import models
from sklearn.metrics import (
    accuracy_score,
    precision_score,
    recall_score,
    f1_score,
    classification_report,
    confusion_matrix
)
import numpy as np
import random
import os
import matplotlib.pyplot as plt
import seaborn as sns

# ============================================================
# 1. REPRODUCIBILITY
# ============================================================

SEED = 42

random.seed(SEED)
np.random.seed(SEED)
torch.manual_seed(SEED)
torch.cuda.manual_seed_all(SEED)

torch.backends.cudnn.deterministic = True
torch.backends.cudnn.benchmark = False


# ============================================================
# 2. DEVICE
# ============================================================

device = torch.device("cuda" if torch.cuda.is_available() else "cpu")

print("Device:", device)


# ============================================================
# 3. DATASET
# ============================================================
# IMPORTANT:
# Uses your FINAL duplicate-free slide-level split:
#
# train_df = 4728
# val_df   = 1013
# test_df  = 1014
#
# Reuse your existing StrokeDataset and transforms.
# ============================================================

train_dataset = StrokeDataset(
    train_df,
    transform=train_transform
)

val_dataset = StrokeDataset(
    val_df,
    transform=val_transform
)

test_dataset = StrokeDataset(
    test_df,
    transform=val_transform
)


# ============================================================
# 4. DATALOADERS
# ============================================================

BATCH_SIZE = 32

train_loader = DataLoader(
    train_dataset,
    batch_size=BATCH_SIZE,
    shuffle=True,
    num_workers=2,
    pin_memory=True
)

val_loader = DataLoader(
    val_dataset,
    batch_size=BATCH_SIZE,
    shuffle=False,
    num_workers=2,
    pin_memory=True
)

test_loader = DataLoader(
    test_dataset,
    batch_size=BATCH_SIZE,
    shuffle=False,
    num_workers=2,
    pin_memory=True
)

print("Train batches:", len(train_loader))
print("Val batches  :", len(val_loader))
print("Test batches :", len(test_loader))


# ============================================================
# 5. RESNET50 MODEL
# ============================================================

weights = models.ResNet50_Weights.DEFAULT

model = models.resnet50(weights=weights)

# Replace final classification layer
num_features = model.fc.in_features

model.fc = nn.Linear(
    num_features,
    3
)

model = model.to(device)

print("\nResNet50:")
print(model.fc)


# ============================================================
# 6. LOSS + OPTIMIZER
# ============================================================

criterion = nn.CrossEntropyLoss()

optimizer = optim.AdamW(
    model.parameters(),
    lr=3e-4,
    weight_decay=1e-4
)

scheduler = optim.lr_scheduler.ReduceLROnPlateau(
    optimizer,
    mode="min",
    factor=0.5,
    patience=2
)


# ============================================================
# 7. TRAINING SETTINGS
# ============================================================

NUM_EPOCHS = 15

best_val_loss = float("inf")

save_path = "/content/drive/MyDrive/resnet50_best.pth"


# ============================================================
# 8. TRAINING LOOP
# ============================================================

train_losses = []
val_losses = []

train_accs = []
val_accs = []


for epoch in range(NUM_EPOCHS):

    # --------------------------------------------------------
    # TRAIN
    # --------------------------------------------------------

    model.train()

    running_loss = 0.0
    train_preds = []
    train_targets = []

    for images, labels in train_loader:

        images = images.to(device)
        labels = labels.to(device)

        optimizer.zero_grad()

        outputs = model(images)

        loss = criterion(outputs, labels)

        loss.backward()

        optimizer.step()

        running_loss += loss.item() * images.size(0)

        preds = torch.argmax(outputs, dim=1)

        train_preds.extend(
            preds.detach().cpu().numpy()
        )

        train_targets.extend(
            labels.detach().cpu().numpy()
        )


    epoch_train_loss = (
        running_loss / len(train_dataset)
    )

    epoch_train_acc = accuracy_score(
        train_targets,
        train_preds
    )


    # --------------------------------------------------------
    # VALIDATION
    # --------------------------------------------------------

    model.eval()

    val_running_loss = 0.0

    val_preds = []
    val_targets = []

    with torch.no_grad():

        for images, labels in val_loader:

            images = images.to(device)
            labels = labels.to(device)

            outputs = model(images)

            loss = criterion(
                outputs,
                labels
            )

            val_running_loss += (
                loss.item() * images.size(0)
            )

            preds = torch.argmax(
                outputs,
                dim=1
            )

            val_preds.extend(
                preds.cpu().numpy()
            )

            val_targets.extend(
                labels.cpu().numpy()
            )


    epoch_val_loss = (
        val_running_loss / len(val_dataset)
    )

    epoch_val_acc = accuracy_score(
        val_targets,
        val_preds
    )


    # --------------------------------------------------------
    # SCHEDULER
    # --------------------------------------------------------

    scheduler.step(epoch_val_loss)


    # --------------------------------------------------------
    # SAVE BEST MODEL
    # --------------------------------------------------------

    if epoch_val_loss < best_val_loss:

        best_val_loss = epoch_val_loss

        torch.save(
            model.state_dict(),
            save_path
        )

        best_marker = " ⭐ BEST"

    else:

        best_marker = ""


    # --------------------------------------------------------
    # STORE HISTORY
    # --------------------------------------------------------

    train_losses.append(epoch_train_loss)
    val_losses.append(epoch_val_loss)

    train_accs.append(epoch_train_acc)
    val_accs.append(epoch_val_acc)


    # --------------------------------------------------------
    # PRINT
    # --------------------------------------------------------

    print(
        f"Epoch [{epoch+1:02d}/{NUM_EPOCHS}] "
        f"Train Loss: {epoch_train_loss:.4f} | "
        f"Train Acc: {epoch_train_acc*100:.2f}% | "
        f"Val Loss: {epoch_val_loss:.4f} | "
        f"Val Acc: {epoch_val_acc*100:.2f}%"
        f"{best_marker}"
    )


# ============================================================
# 9. LOAD BEST MODEL
# ============================================================

model.load_state_dict(
    torch.load(
        save_path,
        map_location=device
    )
)

model.eval()

print("\nBest ResNet50 model loaded.")


# ============================================================
# 10. TEST EVALUATION
# ============================================================

test_preds = []
test_targets = []

with torch.no_grad():

    for images, labels in test_loader:

        images = images.to(device)
        labels = labels.to(device)

        outputs = model(images)

        preds = torch.argmax(
            outputs,
            dim=1
        )

        test_preds.extend(
            preds.cpu().numpy()
        )

        test_targets.extend(
            labels.cpu().numpy()
        )


# ============================================================
# 11. METRICS
# ============================================================

test_accuracy = accuracy_score(
    test_targets,
    test_preds
)

test_precision = precision_score(
    test_targets,
    test_preds,
    average="weighted",
    zero_division=0
)

test_recall = recall_score(
    test_targets,
    test_preds,
    average="weighted",
    zero_division=0
)

test_f1 = f1_score(
    test_targets,
    test_preds,
    average="weighted",
    zero_division=0
)


print("\n======================================")
print("RESNET50 TEST RESULTS")
print("======================================")

print(f"Accuracy : {test_accuracy*100:.2f}%")
print(f"Precision: {test_precision*100:.2f}%")
print(f"Recall   : {test_recall*100:.2f}%")
print(f"F1 Score : {test_f1*100:.2f}%")


# ============================================================
# 12. CLASSIFICATION REPORT
# ============================================================

class_names = [
    "Normal",
    "Ischemia",
    "Bleeding"
]

print("\nClassification Report:\n")

print(
    classification_report(
        test_targets,
        test_preds,
        target_names=class_names,
        digits=4,
        zero_division=0
    )
)


# ============================================================
# 13. CONFUSION MATRIX
# ============================================================

cm = confusion_matrix(
    test_targets,
    test_preds
)

plt.figure(figsize=(7, 6))

sns.heatmap(
    cm,
    annot=True,
    fmt="d",
    xticklabels=class_names,
    yticklabels=class_names
)

plt.xlabel("Predicted Label")
plt.ylabel("True Label")
plt.title("ResNet50 Confusion Matrix")

plt.tight_layout()
plt.show()


# ============================================================
# 14. TRAINING CURVES
# ============================================================

plt.figure(figsize=(8, 5))

plt.plot(
    train_losses,
    label="Training Loss"
)

plt.plot(
    val_losses,
    label="Validation Loss"
)

plt.xlabel("Epoch")
plt.ylabel("Loss")
plt.title("ResNet50 Training and Validation Loss")

plt.legend()
plt.tight_layout()
plt.show()


plt.figure(figsize=(8, 5))

plt.plot(
    train_accs,
    label="Training Accuracy"
)

plt.plot(
    val_accs,
    label="Validation Accuracy"
)

plt.xlabel("Epoch")
plt.ylabel("Accuracy")
plt.title("ResNet50 Training and Validation Accuracy")

plt.legend()
plt.tight_layout()
plt.show()

import os
import pydicom
from collections import Counter

DATASET_PATH = "/content/drive/MyDrive/archive (1)/İNME VERİ SETİ"

dicom_files = []

for root, dirs, files in os.walk(DATASET_PATH):
    for f in files:
        if f.lower().endswith(".dcm"):
            dicom_files.append(os.path.join(root, f))

print("Total DICOM files:", len(dicom_files))

