dataset2 = "/content/drive/MyDrive/archive (1)/İNME VERİ SETİ"

image_ext = ('.png', '.jpg', '.jpeg', '.bmp', '.tif', '.tiff')

def count_original_images(dataset_path):
    total = 0

    for root, dirs, files in os.walk(dataset_path):

        folder = os.path.basename(root).lower()

        # MASKS, OVERLAY, DICOM folder বাদ
        if folder in ["masks", "overlay", "dicom"]:
            continue

        total += sum(
            1 for f in files
            if f.lower().endswith(image_ext)
        )

    return total

print("Dataset 1 Original Images:", count_original_images(dataset1))
print("Dataset 2 Original Images:", count_original_images(dataset2))

