import os
import pandas as pd
from glob import glob
from sklearn.model_selection import train_test_split

# ==========================================================
# DATASET PATH
# ==========================================================

DATASET_PATH = "/content/drive/MyDrive/archive (1)/İNME VERİ SETİ"

IMG_EXT = (".png", ".jpg", ".jpeg", ".bmp", ".tif", ".tiff")

image_paths = []
labels = []

# ==========================================================
# NORMAL IMAGES
# ==========================================================

normal_path = os.path.join(DATASET_PATH, "Normal")

for ext in IMG_EXT:
    files = glob(os.path.join(normal_path, "*" + ext))
    image_paths.extend(files)
    labels.extend(["Normal"] * len(files))

# ==========================================================
# BLEEDING (PNG only)
# ==========================================================

bleeding_path = os.path.join(DATASET_PATH, "Bleeding", "PNG")

for ext in IMG_EXT:
    files = glob(os.path.join(bleeding_path, "*" + ext))
    image_paths.extend(files)
    labels.extend(["Bleeding"] * len(files))

# ==========================================================
# ISCHEMIA (PNG only)
# ==========================================================

ischemia_path = os.path.join(DATASET_PATH, "Ischemia", "PNG")

for ext in IMG_EXT:
    files = glob(os.path.join(ischemia_path, "*" + ext))
    image_paths.extend(files)
    labels.extend(["Ischemia"] * len(files))

# ==========================================================
# CREATE DATAFRAME
# ==========================================================

df = pd.DataFrame({
    "image_path": image_paths,
    "label": labels
})

print("="*60)
print("TOTAL IMAGES :", len(df))
print("="*60)
print(df["label"].value_counts())
print("="*60)

# ==========================================================
# TRAIN / VALIDATION / TEST SPLIT
# ==========================================================

train_df, temp_df = train_test_split(
    df,
    test_size=0.30,
    stratify=df["label"],
    random_state=42
)

val_df, test_df = train_test_split(
    temp_df,
    test_size=0.50,
    stratify=temp_df["label"],
    random_state=42
)

train_df = train_df.reset_index(drop=True)
val_df = val_df.reset_index(drop=True)
test_df = test_df.reset_index(drop=True)

# ==========================================================
# SUMMARY
# ==========================================================

print("\n========== DATASET SUMMARY ==========\n")

print(f"Train Images      : {len(train_df)}")
print(train_df["label"].value_counts())

print()

print(f"Validation Images : {len(val_df)}")
print(val_df["label"].value_counts())

print()

print(f"Test Images       : {len(test_df)}")
print(test_df["label"].value_counts())

print("\n✅ Dataset Split Completed Successfully!")

