# ==========================================================
# SWIN-T MODEL + LOSS + OPTIMIZER + SCHEDULER (T4 GPU)
# ==========================================================

import os
import torch
import torch.nn as nn
import torchvision.models as models

# ==========================================================
# DEVICE
# ==========================================================

device = torch.device("cuda" if torch.cuda.is_available() else "cpu")

print("Device:", device)

if torch.cuda.is_available():
    print("GPU:", torch.cuda.get_device_name(0))

# ==========================================================
# NUMBER OF CLASSES
# ==========================================================

num_classes = 3

# ==========================================================
# LOAD PRETRAINED SWIN-T
# ==========================================================

weights = models.Swin_T_Weights.DEFAULT

model = models.swin_t(weights=weights)

# ==========================================================
# REPLACE CLASSIFIER
# ==========================================================

in_features = model.head.in_features

model.head = nn.Sequential(
    nn.Dropout(0.5),
    nn.Linear(in_features, num_classes)
)

model = model.to(device)

print("✅ Swin-T Loaded Successfully")

# ==========================================================
# LOSS FUNCTION
# ==========================================================

criterion = nn.CrossEntropyLoss(
    label_smoothing=0.1
)

# ==========================================================
# OPTIMIZER
# ==========================================================

optimizer = torch.optim.AdamW(
    model.parameters(),
    lr=3e-4,
    betas=(0.9, 0.999),
    eps=1e-8,
    weight_decay=1e-4
)

# ==========================================================
# LEARNING RATE SCHEDULER
# ==========================================================

scheduler = torch.optim.lr_scheduler.ReduceLROnPlateau(
    optimizer,
    mode="max",
    factor=0.5,
    patience=2
)

# ==========================================================
# SAVE DIRECTORY
# ==========================================================

SAVE_DIR = "/content/drive/MyDrive/Stroke_SwinT_Model"

os.makedirs(SAVE_DIR, exist_ok=True)

BEST_MODEL_PATH = os.path.join(
    SAVE_DIR,
    "best_swin_t.pth"
)

LAST_MODEL_PATH = os.path.join(
    SAVE_DIR,
    "last_swin_t.pth"
)

print("="*60)
print("✅ Swin-T Model Ready")
print("="*60)

print("Best Model Save Path:")
print(BEST_MODEL_PATH)

print()

print("Last Model Save Path:")
print(LAST_MODEL_PATH)

print(train_loader)
print(val_loader)
print(test_loader)

print(len(train_loader))
print(len(val_loader))
print(len(test_loader))

