import torch
import numpy as np
import pandas as pd
from PIL import Image
from torch.utils.data import Dataset, DataLoader
from sklearn.metrics import (
    accuracy_score,
    balanced_accuracy_score,
    precision_recall_fscore_support,
    confusion_matrix
)

# =========================================================
# 1. Device
# =========================================================
device = torch.device("cuda" if torch.cuda.is_available() else "cpu")
model = model.to(device)
model.eval()

print("Device:", device)

if torch.cuda.is_available():
    print("GPU:", torch.cuda.get_device_name(0))


# =========================================================
# 2. Dataset
# =========================================================
class ExternalStrokeDataset(Dataset):

    def __init__(self, df, transform):
        self.df = df.reset_index(drop=True)
        self.transform = transform

    def __len__(self):
        return len(self.df)

    def __getitem__(self, idx):

        row = self.df.iloc[idx]

        image = Image.open(row["image_path"]).convert("RGB")
        image = self.transform(image)

        label = int(row["label_idx"])

        return image, label


external_dataset = ExternalStrokeDataset(
    external_sample_df,
    preprocess
)


external_loader = DataLoader(
    external_dataset,
    batch_size=64,
    shuffle=False,
    num_workers=2 if torch.cuda.is_available() else 0,
    pin_memory=torch.cuda.is_available()
)


# =========================================================
# 3. Inference
# =========================================================
all_preds = []
all_labels = []
all_probs = []

print("\nStarting external validation...")
print("Images:", len(external_dataset))

with torch.inference_mode():

    for batch_idx, (images, labels) in enumerate(external_loader):

        images = images.to(
            device,
            non_blocking=torch.cuda.is_available()
        )

        outputs = model(images)

        probs = torch.softmax(outputs, dim=1)
        preds = torch.argmax(probs, dim=1)

        all_preds.append(preds.cpu().numpy())
        all_labels.append(labels.numpy())
        all_probs.append(probs.cpu().numpy())

        print(
            f"\rProcessed: "
            f"{min((batch_idx + 1) * 64, len(external_dataset))}"
            f"/{len(external_dataset)}",
            end=""
        )


all_preds = np.concatenate(all_preds)
all_labels = np.concatenate(all_labels)
all_probs = np.concatenate(all_probs)

print("\n\nInference completed.")


# =========================================================
# 4. Overall Metrics
# =========================================================
accuracy = accuracy_score(
    all_labels,
    all_preds
)

balanced_acc = balanced_accuracy_score(
    all_labels,
    all_preds
)

precision, recall, f1, support = precision_recall_fscore_support(
    all_labels,
    all_preds,
    labels=[0, 1, 2],
    zero_division=0
)

macro_precision = precision.mean()
macro_recall = recall.mean()
macro_f1 = f1.mean()


# =========================================================
# 5. Results
# =========================================================
print("\n" + "=" * 60)
print("EXTERNAL VALIDATION RESULTS — MAXViT")
print("=" * 60)

print(f"Accuracy:          {accuracy:.4f}")
print(f"Balanced Accuracy: {balanced_acc:.4f}")
print(f"Macro Precision:   {macro_precision:.4f}")
print(f"Macro Recall:      {macro_recall:.4f}")
print(f"Macro F1:          {macro_f1:.4f}")


# =========================================================
# 6. Class-wise Results
# =========================================================
class_names = [
    "Normal",
    "Ischemia",
    "Bleeding"
]

print("\nClass-wise Results")
print("-" * 60)

for i, name in enumerate(class_names):

    print(
        f"{name:10s} | "
        f"Precision: {precision[i]:.4f} | "
        f"Recall: {recall[i]:.4f} | "
        f"F1: {f1[i]:.4f} | "
        f"Support: {support[i]}"
    )


# =========================================================
# 7. Confusion Matrix
# =========================================================
cm = confusion_matrix(
    all_labels,
    all_preds,
    labels=[0, 1, 2]
)

print("\nConfusion Matrix")
print("(Rows = True, Columns = Predicted)")
print("-" * 60)

cm_df = pd.DataFrame(
    cm,
    index=class_names,
    columns=class_names
)

print(cm_df)


# =========================================================
# 8. Save predictions for later analysis
# =========================================================
external_results = external_sample_df.copy()

external_results["pred_idx"] = all_preds

idx_to_class = {
    0: "Normal",
    1: "Ischemia",
    2: "Bleeding"
}

external_results["predicted_class"] = [
    idx_to_class[x] for x in all_preds
]

external_results["confidence"] = all_probs.max(axis=1)

print("\nPrediction dataframe created:", external_results.shape)

