import torch
import numpy as np
import pandas as pd
from PIL import Image
from torch.utils.data import Dataset, DataLoader
from sklearn.metrics import (
    accuracy_score, balanced_accuracy_score,
    precision_score, recall_score, f1_score,
    classification_report, confusion_matrix
)

# --------------------------------------------------
# Dataset
# --------------------------------------------------

class ExternalDataset(Dataset):
    def __init__(self, df, transform):
        self.df = df.reset_index(drop=True)
        self.transform = transform

    def __len__(self):
        return len(self.df)

    def __getitem__(self, idx):
        row = self.df.iloc[idx]
        image = Image.open(row["image_path"]).convert("RGB")
        image = self.transform(image)

        label = {
            "Normal": 0,
            "Ischemia": 1,
            "Bleeding": 2
        }[row["mapped_class"]]

        return image, label, idx


# --------------------------------------------------
# DataLoader
# --------------------------------------------------

dataset = ExternalDataset(external_sample_df, preprocess)

loader = DataLoader(
    dataset,
    batch_size=64,
    shuffle=False,
    num_workers=2,
    pin_memory=torch.cuda.is_available()
)

device = torch.device("cuda" if torch.cuda.is_available() else "cpu")

model = model.to(device)
model.eval()

y_true = []
y_pred = []
prediction_rows = []

print("Device:", device)
print("Starting external validation...")
print("Images:", len(dataset))

# --------------------------------------------------
# Batch inference
# --------------------------------------------------

with torch.inference_mode():

    for batch_idx, (images, labels, indices) in enumerate(loader):

        images = images.to(device, non_blocking=True)

        outputs = model(images)
        preds = outputs.argmax(dim=1).cpu().numpy()

        labels = labels.numpy()
        indices = indices.numpy()

        y_true.extend(labels)
        y_pred.extend(preds)

        for idx, true_label, pred_label in zip(
            indices, labels, preds
        ):
            row = external_sample_df.iloc[idx]

            prediction_rows.append({
                "image_id": row["Unnamed: 0"],
                "patient_id": row["patient_id"],
                "true_class": row["mapped_class"],
                "pred_class": ["Normal", "Ischemia", "Bleeding"][pred_label],
                "true_idx": true_label,
                "pred_idx": pred_label,
                "correct": true_label == pred_label,
                "image_path": row["image_path"]
            })

        processed = min(
            (batch_idx + 1) * 64,
            len(dataset)
        )

        if (batch_idx + 1) % 5 == 0 or processed == len(dataset):
            print(f"Processed: {processed}/{len(dataset)}")


# --------------------------------------------------
