# ============================================================
# 9. FIND OVERLAY PATH
#
# For:
# Bleeding/PNG/10865.png
# -> Bleeding/OVERLAY/10865.png
#
# Ischemia/PNG/13671.png
# -> Ischemia/OVERLAY/13671.png
#
# Normal has no lesion overlay, so Normal is skipped.
# ============================================================

def get_overlay_path(
    image_path,
    label
):

    label = str(
        label
    ).strip()

    # Normal images do not have lesion overlays
    if label == "Normal":

        return None

    filename = os.path.basename(
        image_path
    )

    # Replace /PNG/ with /OVERLAY/
    if "/PNG/" in image_path:

        overlay_path = image_path.replace(
            "/PNG/",
            "/OVERLAY/"
        )

    else:

        return None

    # Make sure filename remains identical
    overlay_path = os.path.join(
        os.path.dirname(
            overlay_path
        ),
        filename
    )

    if os.path.exists(
        overlay_path
    ):

        return overlay_path

    return None


