# ============================================================
# 13. GT MASK EXTRACTION
# ============================================================

def extract_gt_mask(
    overlay_rgb
):

    r = overlay_rgb[
        :, :, 0
    ].astype(
        np.int16
    )

    g = overlay_rgb[
        :, :, 1
    ].astype(
        np.int16
    )

    b = overlay_rgb[
        :, :, 2
    ].astype(
        np.int16
    )

    colored = (

        (
            (r > g + 30) &
            (r > b + 30)
        )

        |

        (
            (b > r + 30) &
            (b > g + 30)
        )
    )

    return colored.astype(
        np.uint8
    )


# ============================================================
# 14. DICE
# ============================================================

def calculate_dice(
    pred_mask,
    gt_mask
):

    pred_mask = (
        pred_mask > 0
    )

    gt_mask = (
        gt_mask > 0
    )

    intersection = np.logical_and(
        pred_mask,
        gt_mask
    ).sum()

    denominator = (
        pred_mask.sum() +
        gt_mask.sum()
    )

    if denominator == 0:

        return 1.0

    return (
        2.0 * intersection /
        denominator
    )


# ============================================================
# 15. IoU
# ============================================================

def calculate_iou(
    pred_mask,
    gt_mask
):

    pred_mask = (
        pred_mask > 0
    )

    gt_mask = (
        gt_mask > 0
    )

    intersection = np.logical_and(
        pred_mask,
        gt_mask
    ).sum()

    union = np.logical_or(
        pred_mask,
        gt_mask
    ).sum()

    if union == 0:

        return 1.0

    return (
        intersection /
        union
    )


# ============================================================
# 16. POINTING GAME
# ============================================================

def calculate_pointing_game(
    cam_map,
    gt_mask
):

    if gt_mask.sum() == 0:

        return np.nan

    max_y, max_x = np.unravel_index(
        np.argmax(cam_map),
        cam_map.shape
    )

    return int(
        gt_mask[
            max_y,
            max_x
        ] > 0
    )


# ============================================================
# 17. CENTROID DISTANCE
# ============================================================

def calculate_centroid_distance(
    pred_mask,
    gt_mask
):

    pred_pixels = np.argwhere(
        pred_mask > 0
    )

    gt_pixels = np.argwhere(
        gt_mask > 0
    )

    if (
        len(pred_pixels) == 0 or
        len(gt_pixels) == 0
    ):

        return np.nan

    pred_centroid = (
        pred_pixels.mean(
            axis=0
        )
    )

    gt_centroid = (
        gt_pixels.mean(
            axis=0
        )
    )

    return float(
        np.linalg.norm(
            pred_centroid -
            gt_centroid
        )
    )


# ============================================================
# 18. ORIGINAL PAPER LESION PIPELINE
#
# threshold = 0.55
# largest connected component
# ============================================================

def original_lesion_mask(
    grayscale_cam,
    threshold=0.55
):

    binary = (
        grayscale_cam > threshold
    ).astype(
        np.uint8
    )

    num_labels, labels, stats, centroids = (
        cv2.connectedComponentsWithStats(
            binary,
            connectivity=8
        )
    )

    clean = np.zeros_like(
        binary
    )

    if num_labels > 1:

        largest = (
            1 +
            np.argmax(
                stats[
                    1:,
                    cv2.CC_STAT_AREA
                ]
            )
        )

        clean[
            labels == largest
        ] = 1

    return clean


# ============================================================
# 19. EXACT NORMALIZATION
# ============================================================

mean = torch.tensor(
    [0.485, 0.456, 0.406],
    dtype=torch.float32
).view(
    3, 1, 1
)

std = torch.tensor(
    [0.229, 0.224, 0.225],
    dtype=torch.float32
).view(
    3, 1, 1
)


# ============================================================
# 20. PROCESS ALL ANNOTATED IMAGES
# ============================================================

results = []

print("\n========================================")
print("STARTING GRAD-CAM VALIDATION")
print("========================================")


for counter, row in annotated_df.iterrows():

    dataset_index = int(
        row["dataset_index"]
    )

    image_path = row[
        "image_path"
    ]

    filename = row[
        "filename"
    ]

    true_label = row[
        "label"
    ]

    overlay_path = row[
        "overlay_path"
    ]


    try:

        # ====================================================
        # LOAD IMAGE
        # ====================================================

        image = Image.open(
            image_path
        ).convert(
            "RGB"
        )

        image_np = np.array(
            image
        )


        # ====================================================
        # LOAD OVERLAY
        # ====================================================

        overlay = Image.open(
            overlay_path
        ).convert(
            "RGB"
        )

        overlay_np = np.array(
            overlay
        )


        # ====================================================
        # ORIGINAL GT
        # ====================================================

        gt_mask_original = (
            extract_gt_mask(
                overlay_np
            )
        )


        # ====================================================
        # CRITICAL ALIGNMENT
        #
        # IMAGE -> 224x224
        # GT    -> 224x224
        #
        # SAME coordinate transformation
        # ====================================================

        image_224 = cv2.resize(
            image_np,
            (224, 224),
            interpolation=cv2.INTER_LINEAR
        )

        gt_224 = cv2.resize(
            gt_mask_original,
            (224, 224),
            interpolation=cv2.INTER_NEAREST
        )

        gt_224 = (
            gt_224 > 0
        ).astype(
            np.uint8
        )


        # ====================================================
        # MODEL INPUT
        # ====================================================

        image_tensor = (
            torch.from_numpy(
                image_224
            )
            .permute(
                2, 0, 1
            )
            .float()
            / 255.0
        )

        image_tensor = (
            image_tensor - mean
        ) / std

        image_tensor = (
            image_tensor
            .unsqueeze(0)
            .to(device)
        )


        # ====================================================
        # MODEL PREDICTION
        # ====================================================

        with torch.no_grad():

            output = model(
                image_tensor
            )

            pred_id = output.argmax(
                dim=1
            ).item()


        pred_label = CLASS_MAP[
            pred_id
        ]

        true_id = LABEL_TO_ID[
            true_label
        ]

        correct = (
            pred_id == true_id
        )


        # ====================================================
        # GRAD-CAM
        # ====================================================

        targets = [
            ClassifierOutputTarget(
                pred_id
            )
        ]

        grayscale_cam = cam(
            input_tensor=image_tensor,
            targets=targets
        )[0]


        # ====================================================
        # FORCE 224x224
        # ====================================================

        if grayscale_cam.shape != (
            224,
            224
        ):

            grayscale_cam = cv2.resize(
                grayscale_cam,
                (224, 224),
                interpolation=cv2.INTER_LINEAR
            )


        # ====================================================
        # ORIGINAL PAPER PIPELINE
        # ====================================================

        cam_mask = original_lesion_mask(
            grayscale_cam,
            threshold=0.55
        )


        # ====================================================
        # METRICS
        # ====================================================

        dice = calculate_dice(
            cam_mask,
            gt_224
        )

        iou = calculate_iou(
            cam_mask,
            gt_224
        )

        pointing = calculate_pointing_game(
            grayscale_cam,
            gt_224
        )

        centroid_distance = (
            calculate_centroid_distance(
                cam_mask,
                gt_224
            )
        )


        overlap = int(
            np.logical_and(
                cam_mask,
                gt_224
            ).sum()
        )


        # ====================================================
        # SAVE RESULT
        # ====================================================

        results.append({

            "dataset_index":
                dataset_index,

            "filename":
                filename,

            "true_label":
                true_label,

            "true_id":
                true_id,

            "pred_id":
                pred_id,

            "pred_label":
                pred_label,

            "correct":
                correct,

            "image_path":
                image_path,

            "overlay_path":
                overlay_path,

            "gt_pixels_224":
                int(
                    gt_224.sum()
                ),

            "cam_pixels_224":
                int(
                    cam_mask.sum()
                ),

            "overlap_pixels":
                overlap,

            "dice":
                dice,

            "iou":
                iou,

            "pointing_game":
                pointing,

            "centroid_distance":
                centroid_distance
        })


        if (
            (counter + 1) % 25 == 0
        ):

            print(
                f"Processed "
                f"{counter+1}/"
                f"{len(annotated_df)}"
            )


    except Exception as e:

        print(
            f"\n❌ ERROR at "
            f"{counter}: "
            f"{filename}"
        )

        print(
            repr(e)
        )


