# ============================================================
# 28. VISUAL ALIGNMENT CHECK
# ============================================================

if len(results_df) > 0:

    sample = results_df.iloc[0]

    sample_image_path = (
        sample["image_path"]
    )

    sample_overlay_path = (
        sample["overlay_path"]
    )


    # --------------------------------------------------------
    # IMAGE
    # --------------------------------------------------------

    sample_image = np.array(
        Image.open(
            sample_image_path
        ).convert(
            "RGB"
        )
    )


    # --------------------------------------------------------
    # OVERLAY
    # --------------------------------------------------------

    sample_overlay = np.array(
        Image.open(
            sample_overlay_path
        ).convert(
            "RGB"
        )
    )


    # --------------------------------------------------------
    # GT ORIGINAL
    # --------------------------------------------------------

    sample_gt_original = (
        extract_gt_mask(
            sample_overlay
        )
    )


    # --------------------------------------------------------
    # GT 224
    # --------------------------------------------------------

    sample_gt_224 = cv2.resize(
        sample_gt_original,
        (224, 224),
        interpolation=cv2.INTER_NEAREST
    )

    sample_gt_224 = (
        sample_gt_224 > 0
    ).astype(
        np.uint8
    )


    # --------------------------------------------------------
    # IMAGE 224
    # --------------------------------------------------------

    sample_img_224 = cv2.resize(
        sample_image,
        (224, 224),
        interpolation=cv2.INTER_LINEAR
    )


    # --------------------------------------------------------
    # TENSOR
    # --------------------------------------------------------

    sample_tensor = (
        torch.from_numpy(
            sample_img_224
        )
        .permute(
            2, 0, 1
        )
        .float()
        / 255.0
    )

    sample_tensor = (
        sample_tensor - mean
    ) / std

    sample_tensor = (
        sample_tensor
        .unsqueeze(0)
        .to(device)
    )


    # --------------------------------------------------------
    # PREDICTION
    # --------------------------------------------------------

    with torch.no_grad():

        sample_pred = model(
            sample_tensor
        ).argmax(
            dim=1
        ).item()


    # --------------------------------------------------------
    # CAM
    # --------------------------------------------------------

    sample_cam = cam(
        input_tensor=sample_tensor,
        targets=[
            ClassifierOutputTarget(
                sample_pred
            )
        ]
    )[0]


    if sample_cam.shape != (
        224,
        224
    ):

        sample_cam = cv2.resize(
            sample_cam,
            (224, 224),
            interpolation=cv2.INTER_LINEAR
        )


    # --------------------------------------------------------
    # CAM MASK
    # --------------------------------------------------------

    sample_cam_mask = (
        original_lesion_mask(
            sample_cam,
            threshold=0.55
        )
    )


    # --------------------------------------------------------
    # VISUALIZE
    # --------------------------------------------------------

    fig, axes = plt.subplots(
        1,
        4,
        figsize=(16, 4)
    )


    axes[0].imshow(
        sample_img_224
    )

    axes[0].set_title(
        "CT Image"
    )


    axes[1].imshow(
        sample_gt_224,
        cmap="gray"
    )

    axes[1].set_title(
        "GT Lesion Mask"
    )


    axes[2].imshow(
        sample_cam,
        cmap="jet"
    )

    axes[2].set_title(
        "Grad-CAM"
    )


    axes[3].imshow(
        sample_img_224
    )

    axes[3].imshow(
        sample_gt_224,
        cmap="Greens",
        alpha=0.40
    )

    axes[3].imshow(
        sample_cam_mask,
        cmap="Reds",
        alpha=0.40
    )

    axes[3].set_title(
        "GT + Grad-CAM"
    )


    for ax in axes:

        ax.axis("off")


    plt.tight_layout()


    VIS_PATH = os.path.join(
        OUTPUT_DIR,
        "alignment_sanity_check.png"
    )


    plt.savefig(
        VIS_PATH,
        dpi=300,
        bbox_inches="tight"
    )

    plt.show()


    print(
        "\nVisual check saved:"
    )

    print(
        VIS_PATH
    )


