# ==========================================================
# CREATE FINAL DATA LOADERS
# ==========================================================

import pandas as pd
import os
from PIL import Image

import torch
from torch.utils.data import Dataset, DataLoader
from torchvision import transforms


# ==========================================================
# PATHS
# ==========================================================

TRAIN_CSV = "/content/drive/MyDrive/archive (1)/train_final.csv"
VAL_CSV   = "/content/drive/MyDrive/archive (1)/val_final.csv"
TEST_CSV  = "/content/drive/MyDrive/archive (1)/test_final.csv"


# ==========================================================
# LOAD CSVs
# ==========================================================

train_df = pd.read_csv(TRAIN_CSV)
val_df   = pd.read_csv(VAL_CSV)
test_df  = pd.read_csv(TEST_CSV)

print("Train      :", len(train_df))
print("Validation :", len(val_df))
print("Test       :", len(test_df))


# ==========================================================
# LABEL MAPPING
# ==========================================================

label2idx = {
    "Normal": 0,
    "Ischemia": 1,
    "Bleeding": 2
}

idx2label = {
    0: "Normal",
    1: "Ischemia",
    2: "Bleeding"
}


# ==========================================================
# TRANSFORMS
# ==========================================================

train_transform = transforms.Compose([
    transforms.Resize((224, 224)),
    transforms.RandomHorizontalFlip(),
    transforms.RandomRotation(15),
    transforms.ColorJitter(
        brightness=0.2,
        contrast=0.2
    ),
    transforms.ToTensor(),
    transforms.Normalize(
        mean=[0.485, 0.456, 0.406],
        std=[0.229, 0.224, 0.225]
    )
])

val_test_transform = transforms.Compose([
    transforms.Resize((224, 224)),
    transforms.ToTensor(),
    transforms.Normalize(
        mean=[0.485, 0.456, 0.406],
        std=[0.229, 0.224, 0.225]
    )
])


# ==========================================================
# DATASET
# ==========================================================

class StrokeDataset(Dataset):

    def __init__(self, dataframe, transform=None):

        self.df = dataframe.reset_index(drop=True)
        self.transform = transform

    def __len__(self):
        return len(self.df)

    def __getitem__(self, idx):

        row = self.df.iloc[idx]

        image_path = row["image_path"]
        label = row["label"]

        image = Image.open(image_path).convert("RGB")

        if self.transform:
            image = self.transform(image)

        label = label2idx[label]

        return image, label


# ==========================================================
# CREATE DATASETS
# ==========================================================

train_dataset = StrokeDataset(
    train_df,
    transform=train_transform
)

val_dataset = StrokeDataset(
    val_df,
    transform=val_test_transform
)

test_dataset = StrokeDataset(
    test_df,
    transform=val_test_transform
)


# ==========================================================
# CREATE DATALOADERS
# ==========================================================

BATCH_SIZE = 16
NUM_WORKERS = 2

train_loader = DataLoader(
    train_dataset,
    batch_size=BATCH_SIZE,
    shuffle=True,
    num_workers=NUM_WORKERS,
    pin_memory=True,
    persistent_workers=True,
    prefetch_factor=2
)

val_loader = DataLoader(
    val_dataset,
    batch_size=BATCH_SIZE,
    shuffle=False,
    num_workers=NUM_WORKERS,
    pin_memory=True,
    persistent_workers=True,
    prefetch_factor=2
)

test_loader = DataLoader(
    test_dataset,
    batch_size=BATCH_SIZE,
    shuffle=False,
    num_workers=NUM_WORKERS,
    pin_memory=True,
    persistent_workers=True,
    prefetch_factor=2
)


# ==========================================================
# VERIFY
# ==========================================================

print("\n" + "="*60)
print("DATALOADERS READY")
print("="*60)

print("Train batches      :", len(train_loader))
print("Validation batches :", len(val_loader))
print("Test batches       :", len(test_loader))

# Expected:
# Train      = 4728
# Validation = 1014
# Test       = 1014

images, labels = next(iter(train_loader))

print("\nFirst batch:")
print("Images :", images.shape)
print("Labels :", labels.shape)

print("\nLabel examples:")
print([idx2label[x.item()] for x in labels[:10]])

print("\n" + "="*60)
print("LOADER CHECK COMPLETE")
print("="*60)

# ==========================================================
# TRAINING LOOP (MAXVIT-T)
# ==========================================================

from tqdm import tqdm
import torch
import pandas as pd

# ==========================================================
# SETTINGS
# ==========================================================

EPOCHS = 30

best_acc = 0.0

train_losses = []
val_losses = []

train_accs = []
val_accs = []

# ==========================================================
# TRAINING
# ==========================================================

for epoch in range(EPOCHS):

    print("\n" + "="*70)
    print(f"Epoch [{epoch+1}/{EPOCHS}]")
    print("="*70)

    ##################################################
    # TRAIN
    ##################################################

    model.train()

    running_loss = 0.0
    correct = 0
    total = 0

    progress_bar = tqdm(train_loader)

    for images, labels in progress_bar:

        images = images.to(device)
        labels = labels.to(device)

        optimizer.zero_grad()

        outputs = model(images)

        loss = criterion(outputs, labels)

        loss.backward()

        optimizer.step()

        running_loss += loss.item()

        _, predicted = torch.max(outputs, 1)

        total += labels.size(0)

        correct += (predicted == labels).sum().item()

        progress_bar.set_postfix(loss=f"{loss.item():.4f}")

    train_loss = running_loss / len(train_loader)
    train_acc = 100 * correct / total

    train_losses.append(train_loss)
    train_accs.append(train_acc)

    ##################################################
    # VALIDATION
    ##################################################

    model.eval()

    running_loss = 0.0
    correct = 0
    total = 0

    with torch.no_grad():

        for images, labels in val_loader:

            images = images.to(device)
            labels = labels.to(device)

            outputs = model(images)

            loss = criterion(outputs, labels)

            running_loss += loss.item()

            _, predicted = torch.max(outputs, 1)

            total += labels.size(0)

            correct += (predicted == labels).sum().item()

    val_loss = running_loss / len(val_loader)

    val_acc = 100 * correct / total

    val_losses.append(val_loss)
    val_accs.append(val_acc)

    ##################################################
    # LR Scheduler
    ##################################################

    scheduler.step(val_acc)

    ##################################################
    # PRINT RESULTS
    ##################################################

    print(f"Train Loss         : {train_loss:.4f}")
    print(f"Train Accuracy     : {train_acc:.2f}%")
    print(f"Validation Loss    : {val_loss:.4f}")
    print(f"Validation Accuracy: {val_acc:.2f}%")

    ##################################################
    # SAVE BEST MODEL
    ##################################################

    if val_acc > best_acc:

        best_acc = val_acc

        torch.save(
            model.state_dict(),
            BEST_MODEL_PATH
        )

        print("✅ Best MaxViT-T Model Saved Successfully")
        print(f"Best Validation Accuracy : {best_acc:.2f}%")

##################################################
# SAVE LAST MODEL
##################################################

torch.save(
    model.state_dict(),
    LAST_MODEL_PATH
)

print("\n" + "="*70)
print("Training Completed Successfully")
print("="*70)

print(f"Best Validation Accuracy : {best_acc:.2f}%")

print("Best Model:")
print(BEST_MODEL_PATH)

print("Last Model:")
print(LAST_MODEL_PATH)

##################################################
# SAVE TRAINING HISTORY
##################################################

history = pd.DataFrame({

    "Epoch": list(range(1, len(train_losses)+1)),

    "Train Loss": train_losses,

    "Validation Loss": val_losses,

    "Train Accuracy": train_accs,

    "Validation Accuracy": val_accs

})

history_path = SAVE_DIR + "/training_history.csv"

history.to_csv(
    history_path,
    index=False
)

print("✅ Training History Saved Successfully")
print(history_path)

