roc_auc = {}

for i in range(n_classes):

    fpr[i], tpr[i], _ = roc_curve(
        y_true_bin[:, i],
        y_score[:, i]
    )

    roc_auc[i] = auc(fpr[i], tpr[i])

# ==========================================================
# PLOT
# ==========================================================

plt.figure(figsize=(8,6))

colors = ["blue", "red", "green"]

for i, color in zip(range(n_classes), colors):

    plt.plot(
        fpr[i],
        tpr[i],
        color=color,
        linewidth=2.5,
        label=f"{class_names[i]} (AUC = {roc_auc[i]:.4f})"
    )

# Random Classifier
plt.plot(
    [0,1],
    [0,1],
    linestyle="--",
    color="black",
    linewidth=1.5
)

plt.xlim(0,1)
plt.ylim(0,1.02)

plt.xlabel("False Positive Rate", fontsize=13)
plt.ylabel("True Positive Rate", fontsize=13)
plt.title("ROC Curve (MaxViT-T)", fontsize=15)

# ==========================================================
# PROFESSIONAL BORDER
# ==========================================================

ax = plt.gca()

for spine in ax.spines.values():
    spine.set_visible(True)
    spine.set_color("black")
    spine.set_linewidth(1.3)

ax.tick_params(
    axis='both',
    labelsize=11,
    width=1.3
)

# ==========================================================
# LEGEND
# ==========================================================

plt.legend(
    loc="lower right",
    fontsize=11,
    frameon=False
)

plt.tight_layout()

# ==========================================================
# SAVE
# ==========================================================

roc_path = os.path.join(
    SAVE_DIR,
    "roc_curve_maxvit.png"
)

plt.savefig(
    roc_path,
    dpi=300,
    bbox_inches="tight",
    pad_inches=0.1
)

plt.show()
plt.close()

# ==========================================================
# PRINT RESULTS
# ==========================================================

print("="*60)

for i in range(n_classes):
    print(f"{class_names[i]} AUC : {roc_auc[i]:.4f}")

print("="*60)

print("ROC Curve Saved Successfully")
print(roc_path)

