from torch.utils.data import Dataset, DataLoader

# ==========================================================
# BUILD IMAGE LIST
# ==========================================================

image_paths = []
labels = []

classes = [
    "Bleeding",
    "Ischemia",
    "Normal"
]

for cls in classes:

    folder = os.path.join(
        EXTERNAL_DATASET,
        cls,
        "PNG"
    )

    images = sorted(os.listdir(folder))

    for img in images:

        if img.lower().endswith((".png",".jpg",".jpeg")):

            image_paths.append(
                os.path.join(folder,img)
            )

            labels.append(
                label_map[cls]
            )

print("="*60)
print("External Images :", len(image_paths))
print("="*60)

# ==========================================================
# CUSTOM DATASET
# ==========================================================

class ExternalDataset(Dataset):

    def __init__(
        self,
        image_paths,
        labels,
        transform=None
    ):

        self.image_paths = image_paths
        self.labels = labels
        self.transform = transform

    def __len__(self):

        return len(self.image_paths)

    def __getitem__(self, idx):

        image = Image.open(
            self.image_paths[idx]
        ).convert("RGB")

        if self.transform:
            image = self.transform(image)

        label = self.labels[idx]

        return image, label

# ==========================================================
# DATASET
# ==========================================================

external_dataset = ExternalDataset(

    image_paths=image_paths,

    labels=labels,

    transform=test_transform

)

external_loader = DataLoader(

    external_dataset,

    batch_size=32,

    shuffle=False,

    num_workers=2,

    pin_memory=True

)

print("External Dataset Loaded Successfully")
print("Total Images :", len(external_dataset))

