# EXTERNAL VALIDATION - PART 2
# DATASET + DATALOADER (CORRECT LABEL MAPPING)
# ==========================================================

from torch.utils.data import Dataset, DataLoader
from PIL import Image
import os

# ==========================================================
# SAME TEST TRANSFORM AS TRAINING
# ==========================================================

test_transform = transforms.Compose([
    transforms.Resize((224,224)),
    transforms.ToTensor(),
    transforms.Normalize(
        mean=[0.485,0.456,0.406],
        std=[0.229,0.224,0.225]
    )
])

# ==========================================================
# LABEL MAP (MUST MATCH TRAINING)
# ==========================================================

label_map = {
    "Normal": 0,
    "Bleeding": 1,
    "Ischemia": 2
}

class_names = [
    "Normal",
    "Bleeding",
    "Ischemia"
]

# ==========================================================
# BUILD IMAGE LIST
# ==========================================================

image_paths = []
labels = []

# IMPORTANT:
# Folder order doesn't matter now because we use label_map.

folders = [
    "Normal",
    "Bleeding",
    "Ischemia"
]

for cls in folders:

    png_folder = os.path.join(
        EXTERNAL_DATASET,
        cls,
        "PNG"
    )

    images = sorted(os.listdir(png_folder))

    for img in images:

        if img.lower().endswith((".png", ".jpg", ".jpeg")):

            image_paths.append(
                os.path.join(png_folder, img)
            )

            labels.append(
                label_map[cls]
            )

print("="*60)
print("Total Images :", len(image_paths))
print("="*60)

# ==========================================================
# CUSTOM DATASET
# ==========================================================

class ExternalDataset(Dataset):

    def __init__(self, image_paths, labels, transform=None):

        self.image_paths = image_paths
        self.labels = labels
        self.transform = transform

    def __len__(self):

        return len(self.image_paths)

    def __getitem__(self, idx):

        image = Image.open(
            self.image_paths[idx]
        ).convert("RGB")

        if self.transform:
            image = self.transform(image)

        label = self.labels[idx]

        return image, label

# ==========================================================
# DATASET
# ==========================================================

external_dataset = ExternalDataset(
    image_paths=image_paths,
    labels=labels,
    transform=test_transform
)

# ==========================================================
# DATALOADER
# ==========================================================

external_loader = DataLoader(
    external_dataset,
    batch_size=32,
    shuffle=False,
    num_workers=2,
    pin_memory=True
)

print("External Dataset Loaded Successfully")
print("Total Images :", len(external_dataset))

