import os
import hashlib
from tqdm import tqdm

def md5(file_path):
    with open(file_path, "rb") as f:
        return hashlib.md5(f.read()).hexdigest()

def get_hashes(folder):

    hashes = {}

    for root, dirs, files in os.walk(folder):

        for file in files:

            if file.lower().endswith((".png",".jpg",".jpeg",".bmp",".tif")):

                path = os.path.join(root,file)

                hashes[path] = md5(path)

    return hashes

internal_hashes = get_hashes(internal_path)
external_hashes = get_hashes(external_path)

internal_set = set(internal_hashes.values())
external_set = set(external_hashes.values())

duplicates = internal_set.intersection(external_set)

print("Internal Images :",len(internal_hashes))
print("External Images :",len(external_hashes))
print("Exact Duplicate :",len(duplicates))

