import os
import cv2
import numpy as np
import pandas as pd
from tqdm import tqdm

image_dir = "/content/drive/MyDrive/archive (1)/İNME VERİ SETİ/YarısmaVeriSeti_2_Oturum/PNG"
mask_dir  = "/content/drive/MyDrive/archive (1)/İNME VERİ SETİ/YarısmaVeriSeti_2_Oturum/MASKS"

mask_names = set(os.listdir(mask_dir))
image_names = set(os.listdir(image_dir))

valid_files = sorted(mask_names.intersection(image_names))

results = []

for file in tqdm(valid_files):

    img = cv2.imread(os.path.join(image_dir, file), cv2.IMREAD_GRAYSCALE)
    mask = cv2.imread(os.path.join(mask_dir, file), cv2.IMREAD_GRAYSCALE)

    # Lesion pixels
    lesion_pixels = np.sum(mask == 95)

    # Brain mask using Otsu threshold
    _, brain = cv2.threshold(img, 0, 255,
                             cv2.THRESH_BINARY + cv2.THRESH_OTSU)

    brain_pixels = np.sum(brain > 0)

    lesion_percent = (lesion_pixels / brain_pixels) * 100 if brain_pixels > 0 else 0

    results.append([
        file,
        lesion_pixels,
        brain_pixels,
        lesion_percent
    ])

df = pd.DataFrame(results,
                  columns=[
                      "Image",
                      "LesionPixels",
                      "BrainPixels",
                      "LesionBurdenPercent"
                  ])

df.to_csv("lesion_burden.csv", index=False)

print(df.head())

print()
print(df.describe())

import cv2
import numpy as np
import matplotlib.pyplot as plt

image_path = "/content/drive/MyDrive/archive (1)/İNME VERİ SETİ/YarısmaVeriSeti_2_Oturum/PNG/10020.png"

# Read image
img = cv2.imread(image_path, cv2.IMREAD_GRAYSCALE)

# Gaussian Blur
blur = cv2.GaussianBlur(img, (5,5), 0)

# Otsu Threshold
_, thresh = cv2.threshold(
    blur,
    0,
    255,
    cv2.THRESH_BINARY + cv2.THRESH_OTSU
)

# Morphological Closing
kernel = np.ones((5,5), np.uint8)
closed = cv2.morphologyEx(
    thresh,
    cv2.MORPH_CLOSE,
    kernel,
    iterations=2
)

# Largest Connected Component
num_labels, labels, stats, centroids = cv2.connectedComponentsWithStats(closed)

largest = 1 + np.argmax(stats[1:, cv2.CC_STAT_AREA])

brain_mask = np.zeros_like(labels, dtype=np.uint8)
brain_mask[labels == largest] = 255

# Hole Filling
brain_mask_flood = brain_mask.copy()

h, w = brain_mask.shape
mask = np.zeros((h+2, w+2), np.uint8)

cv2.floodFill(brain_mask_flood, mask, (0,0), 255)

brain_mask_flood_inv = cv2.bitwise_not(brain_mask_flood)

brain_mask = brain_mask | brain_mask_flood_inv

# Brain Extraction
brain = cv2.bitwise_and(img, img, mask=brain_mask)

# Visualization
plt.figure(figsize=(20,4))

plt.subplot(1,5,1)
plt.imshow(img, cmap='gray')
plt.title("Original")
plt.axis("off")

plt.subplot(1,5,2)
plt.imshow(thresh, cmap='gray')
plt.title("Otsu")
plt.axis("off")

plt.subplot(1,5,3)
plt.imshow(closed, cmap='gray')
plt.title("Closing")
plt.axis("off")

plt.subplot(1,5,4)
plt.imshow(brain_mask, cmap='gray')
plt.title("Brain Mask")
plt.axis("off")

plt.subplot(1,5,5)
plt.imshow(brain, cmap='gray')
plt.title("Extracted Brain")
plt.axis("off")

plt.tight_layout()
plt.show()

