import os
import cv2
import numpy as np
import pandas as pd
from tqdm import tqdm

mask_dir = "/content/drive/MyDrive/archive (1)/İNME VERİ SETİ/YarısmaVeriSeti_2_Oturum/MASKS"
image_dir = "/content/drive/MyDrive/archive (1)/İNME VERİ SETİ/YarısmaVeriSeti_2_Oturum/PNG"

mask_names = set(os.listdir(mask_dir))
image_names = set(os.listdir(image_dir))

valid_files = sorted(mask_names.intersection(image_names))

results = []

for file in tqdm(valid_files):

    mask = cv2.imread(os.path.join(mask_dir, file), cv2.IMREAD_GRAYSCALE)

    # Binary mask
    binary = np.uint8(mask == 95)

    contours, _ = cv2.findContours(
        binary,
        cv2.RETR_EXTERNAL,
        cv2.CHAIN_APPROX_SIMPLE
    )

    if len(contours) == 0:

        results.append([
            file,
            0,0,0,0,0,0,0,0
        ])

        continue

    cnt = max(contours, key=cv2.contourArea)

    area = cv2.contourArea(cnt)

    perimeter = cv2.arcLength(cnt, True)

    circularity = 0

    if perimeter > 0:
        circularity = (4*np.pi*area)/(perimeter*perimeter)

    hull = cv2.convexHull(cnt)

    hull_area = cv2.contourArea(hull)

    solidity = area/hull_area if hull_area>0 else 0

    x,y,w,h = cv2.boundingRect(cnt)

    M = cv2.moments(cnt)

    if M["m00"]!=0:

        cx=int(M["m10"]/M["m00"])

        cy=int(M["m01"]/M["m00"])

    else:

        cx=0
        cy=0

    results.append([
        file,
        area,
        perimeter,
        circularity,
        solidity,
        w,
        h,
        cx,
        cy
    ])

df = pd.DataFrame(results, columns=[
    "Image",
    "Area",
    "Perimeter",
    "Circularity",
    "Solidity",
    "BBoxWidth",
    "BBoxHeight",
    "CentroidX",
    "CentroidY"
])

df.to_csv("stroke_morphology_features.csv", index=False)

print(df.head())

print("\n")

print(df.describe())

import matplotlib.pyplot as plt

feature = "Area"

plt.figure(figsize=(8,5))

plt.hist(df[feature], bins=20)

plt.title(feature)

plt.xlabel(feature)

plt.ylabel("Number of Images")

plt.show()

