import os
import cv2
import numpy as np
import pandas as pd
from tqdm import tqdm
from skimage.measure import label, regionprops

mask_dir = "/content/drive/MyDrive/archive (1)/İNME VERİ SETİ/YarısmaVeriSeti_2_Oturum/MASKS"
image_dir = "/content/drive/MyDrive/archive (1)/İNME VERİ SETİ/YarısmaVeriSeti_2_Oturum/PNG"

valid_files = sorted(
    set(os.listdir(mask_dir)).intersection(os.listdir(image_dir))
)

features = []

for file in tqdm(valid_files):

    mask = cv2.imread(os.path.join(mask_dir, file), cv2.IMREAD_GRAYSCALE)

    binary = (mask == 95).astype(np.uint8)

    lbl = label(binary)

    props = regionprops(lbl)

    if len(props) == 0:

        features.append([
            file,
            0,
            0,
            0,
            0
        ])

        continue

    # Largest lesion
    p = max(props, key=lambda x: x.area)

    features.append([
        file,
        p.major_axis_length,
        p.minor_axis_length,
        p.eccentricity,
        p.extent
    ])

feature_df = pd.DataFrame(features, columns=[
    "Image",
    "MajorAxis",
    "MinorAxis",
    "Eccentricity",
    "Extent"
])

print(feature_df.head())

print("\n")

print(feature_df.describe())

feature_df.to_csv("regionprops_features.csv", index=False)

