import cv2
import torch
import numpy as np
import pandas as pd
from tqdm import tqdm
from torchvision import transforms
from pytorch_grad_cam.utils.model_targets import ClassifierOutputTarget

# -----------------------------
# Label Map
# -----------------------------
idx_to_label = {
    0: "Normal",
    1: "Bleeding",
    2: "Ischemia"
}

results = []

model.eval()

for idx in tqdm(range(len(test_dataset))):

    image, true_label = test_dataset[idx]

    input_tensor = image.unsqueeze(0).to(device)

    # -----------------------------
    # Prediction
    # -----------------------------
    with torch.no_grad():

        output = model(input_tensor)

        prob = torch.softmax(output, dim=1)

        confidence, pred = torch.max(prob, 1)

    pred = pred.item()
    confidence = confidence.item()

    # -----------------------------
    # Grad-CAM
    # -----------------------------
    targets = [ClassifierOutputTarget(pred)]

    grayscale_cam = cam(
        input_tensor=input_tensor,
        targets=targets
    )[0]

    # -----------------------------
    # Threshold
    # -----------------------------
    binary = (grayscale_cam > 0.55).astype(np.uint8)

    # -----------------------------
    # Largest Connected Component
    # -----------------------------
    num_labels, labels, stats, centroids = cv2.connectedComponentsWithStats(
        binary,
        connectivity=8
    )

    clean = np.zeros_like(binary)

    if num_labels > 1:

        largest = 1 + np.argmax(stats[1:, cv2.CC_STAT_AREA])

        clean[labels == largest] = 1

    # -----------------------------
    # Area
    # -----------------------------
    area = int(clean.sum())

    # -----------------------------
    # Bounding Box
    # -----------------------------
    if area > 0:

        x, y, w, h = cv2.boundingRect(clean)

        M = cv2.moments(clean)

        cx = int(M["m10"]/M["m00"])
        cy = int(M["m01"]/M["m00"])

    else:

        x=y=w=h=0
        cx=cy=0

    # -----------------------------
    # Brain Area
    # -----------------------------
    rgb = image.permute(1,2,0).cpu().numpy()

    mean=np.array([0.485,0.456,0.406])
    std=np.array([0.229,0.224,0.225])

    rgb=std*rgb+mean
    rgb=np.clip(rgb,0,1)

    brain_pixels = np.sum(rgb[:,:,0] > 0.05)

    attention_percent = area/brain_pixels*100 if brain_pixels>0 else 0

    # -----------------------------
    # Side
    # -----------------------------
    if area==0:

        side="None"

    elif cx < clean.shape[1]//2:

        side="Left"

    else:

        side="Right"

    # -----------------------------
    # Save
    # -----------------------------
    results.append({

        "Image": test_df.iloc[idx]["image_path"].split("/")[-1],

        "TrueLabel": idx_to_label[true_label],

        "PredLabel": idx_to_label[pred],

        "Confidence": round(confidence,4),

        "AttentionArea": area,

        "AttentionPercent": round(attention_percent,2),

        "CenterX": cx,

        "CenterY": cy,

        "Side": side,

        "BBoxWidth": w,

        "BBoxHeight": h

    })

# -----------------------------
# DataFrame
# -----------------------------
attention_df = pd.DataFrame(results)

attention_df.to_csv(
    "attention_analysis.csv",
    index=False
)

print(attention_df.head())

print("\nCSV Saved Successfully.")

# ============================================================
# VALIDATING YOUR EXISTING LESION MASK
# EXACT SAME PIPELINE AS YOUR ORIGINAL CODE
#
# Grad-CAM
#    ↓
# Threshold
#    ↓
# Largest Connected Component
#    ↓
# clean = YOUR LESION MASK
#
# Then:
# YOUR clean mask  <---->  GT lesion mask from OVERLAY
# ============================================================

import os
import cv2
import torch
import numpy as np
import pandas as pd
from tqdm import tqdm
import matplotlib.pyplot as plt

from pytorch_grad_cam.utils.model_targets import ClassifierOutputTarget


# ============================================================
# SETTINGS
# ============================================================

THRESHOLDS = [0.30, 0.40, 0.50, 0.55, 0.60, 0.70, 0.80]

print("=" * 70)
print("VALIDATION OF YOUR EXISTING LESION MASK")
print("=" * 70)

print("Thresholds:", THRESHOLDS)
print("Annotated test images:", len(matched_df))
print()


# ============================================================
# YOUR OVERLAY -> GT LESION MASK
# ============================================================

def extract_gt_mask(overlay_rgb):

    r = overlay_rgb[:, :, 0].astype(np.int16)
    g = overlay_rgb[:, :, 1].astype(np.int16)
    b = overlay_rgb[:, :, 2].astype(np.int16)

    colored = (
        ((r > g + 30) & (r > b + 30)) |
        ((b > r + 30) & (b > g + 30))
    )

    return colored.astype(np.uint8)


# ============================================================
# DICE
# ============================================================

def dice_score(pred, gt):

    pred = pred.astype(bool)
    gt = gt.astype(bool)

    intersection = np.logical_and(
        pred,
        gt
    ).sum()

    total = pred.sum() + gt.sum()

    if total == 0:
        return 1.0

    return (
        2.0 * intersection /
        (total + 1e-8)
    )


# ============================================================
# IOU
# ============================================================

def iou_score(pred, gt):

    pred = pred.astype(bool)
    gt = gt.astype(bool)

    intersection = np.logical_and(
        pred,
        gt
    ).sum()

    union = np.logical_or(
        pred,
        gt
    ).sum()

    if union == 0:
        return 1.0

    return (
        intersection /
        (union + 1e-8)
    )


# ============================================================
# POINTING GAME
# ============================================================

def pointing_game(grayscale_cam, gt):

    y, x = np.unravel_index(
        np.argmax(grayscale_cam),
        grayscale_cam.shape
    )

    return int(
        gt[y, x] == 1
    )


# ============================================================
# CENTROID DISTANCE
# ============================================================

def centroid_distance(pred, gt):

    pred_points = np.argwhere(
        pred > 0
    )

    gt_points = np.argwhere(
        gt > 0
    )

    if len(pred_points) == 0:
        return np.nan

    if len(gt_points) == 0:
        return np.nan

    pred_centroid = (
        pred_points.mean(axis=0)
    )

    gt_centroid = (
        gt_points.mean(axis=0)
    )

    return float(
        np.linalg.norm(
            pred_centroid -
            gt_centroid
        )
    )


# ============================================================
# EXACT SAME CLEAN MASK PIPELINE
# FROM YOUR ORIGINAL CODE
# ============================================================

def generate_your_lesion_mask(
    grayscale_cam,
    threshold
):

    # -----------------------------
    # Threshold
    # -----------------------------

    binary = (
        grayscale_cam > threshold
    ).astype(np.uint8)


    # -----------------------------
    # Largest Connected Component
    # -----------------------------

    num_labels, labels, stats, centroids = (
        cv2.connectedComponentsWithStats(
            binary,
            connectivity=8
        )
    )


    clean = np.zeros_like(
        binary
    )


    if num_labels > 1:

        largest = (
            1 +
            np.argmax(
                stats[
                    1:,
                    cv2.CC_STAT_AREA
                ]
            )
        )

        clean[
            labels == largest
        ] = 1


    # THIS "clean" IS YOUR LESION MASK
    return clean


# ============================================================
# MAIN
# ============================================================

all_results = []


for _, row in tqdm(
    matched_df.iterrows(),
    total=len(matched_df),
    desc="Validating lesion masks"
):

    idx = int(
        row["index"]
    )

    label = str(
        row["label"]
    )

    overlay_path = str(
        row["overlay_path"]
    )


    try:

        # ====================================================
        # LOAD IMAGE
        # ====================================================

        image, true_label = (
            test_dataset[idx]
        )

        input_tensor = (
            image
            .unsqueeze(0)
            .to(device)
        )


        # ====================================================
        # PREDICTION
        # ====================================================

        with torch.no_grad():

            output = model(
                input_tensor
            )

            probability = torch.softmax(
                output,
                dim=1
            )

            confidence, pred = torch.max(
                probability,
                dim=1
            )

        pred = pred.item()

        confidence = confidence.item()


        # ====================================================
        # GRAD-CAM
        # ====================================================

        grayscale_cam = cam(
            input_tensor=input_tensor,
            targets=[
                ClassifierOutputTarget(
                    pred
                )
            ]
        )[0]


        # ====================================================
        # LOAD OVERLAY
        # ====================================================

        overlay_bgr = cv2.imread(
            overlay_path
        )

        if overlay_bgr is None:

            print(
                f"\nCould not read:"
                f" {overlay_path}"
            )

            continue


        overlay_rgb = cv2.cvtColor(
            overlay_bgr,
            cv2.COLOR_BGR2RGB
        )


        # ====================================================
        # GT LESION MASK
        # ====================================================

        gt_mask_original = (
            extract_gt_mask(
                overlay_rgb
            )
        )


        # ====================================================
        # ALIGN GT TO CAM
        # ====================================================

        cam_h, cam_w = (
            grayscale_cam.shape
        )

        gt_mask = cv2.resize(
            gt_mask_original,
            (cam_w, cam_h),
            interpolation=cv2.INTER_NEAREST
        )

        gt_mask = (
            gt_mask > 0
        ).astype(np.uint8)


        # ====================================================
        # POINTING GAME
        # Same for every threshold
        # ====================================================

        pointing = pointing_game(
            grayscale_cam,
            gt_mask
        )


        # ====================================================
        # TEST ALL THRESHOLDS
        # ====================================================

        for threshold in THRESHOLDS:

            # =================================================
            # THIS IS EXACTLY YOUR "clean"
            # =================================================

            clean = generate_your_lesion_mask(
                grayscale_cam,
                threshold
            )


            # =================================================
            # METRICS
            # =================================================

            dice = dice_score(
                clean,
                gt_mask
            )

            iou = iou_score(
                clean,
                gt_mask
            )

            centroid = centroid_distance(
                clean,
                gt_mask
            )


            # =================================================
            # SAVE
            # =================================================

            if "image_id" in matched_df.columns:

                image_id = str(
                    row["image_id"]
                )

            elif "image_path" in matched_df.columns:

                image_id = os.path.splitext(
                    os.path.basename(
                        str(row["image_path"])
                    )
                )[0]

            else:

                image_id = str(idx)


            all_results.append({

                "index":
                    idx,

                "image_id":
                    image_id,

                "label":
                    label,

                "predicted_class":
                    pred,

                "confidence":
                    confidence,

                "threshold":
                    threshold,

                "dice":
                    dice,

                "iou":
                    iou,

                "pointing_game":
                    pointing,

                "centroid_distance_px":
                    centroid,

                "gt_area":
                    int(
                        gt_mask.sum()
                    ),

                "your_lesion_mask_area":
                    int(
                        clean.sum()
                    )
            })


    except Exception as e:

        print(
            f"\nError at index {idx}: {e}"
        )


# ============================================================
# DATAFRAME
# ============================================================

validation_df = pd.DataFrame(
    all_results
)


print()
print("=" * 70)
print("VALIDATION COMPLETED")
print("=" * 70)

