# FINAL LOCALIZATION VALIDATION
# EXACT ORIGINAL LESION MASK PIPELINE
# ============================================================

import os
import cv2
import numpy as np
import pandas as pd
from tqdm import tqdm
from PIL import Image
import torch

THRESHOLDS = [0.30, 0.40, 0.50, 0.55, 0.60, 0.70, 0.80]

# ------------------------------------------------------------
# GT extraction from annotation overlay
# ------------------------------------------------------------

def extract_gt_mask(overlay_rgb):
    r = overlay_rgb[:, :, 0].astype(np.int16)
    g = overlay_rgb[:, :, 1].astype(np.int16)
    b = overlay_rgb[:, :, 2].astype(np.int16)

    colored = (
        ((r > g + 30) & (r > b + 30)) |
        ((b > r + 30) & (b > g + 30))
    )

    return colored.astype(np.uint8)


# ------------------------------------------------------------
# Metrics
# ------------------------------------------------------------

def dice_score(pred, gt):
    pred = pred.astype(bool)
    gt = gt.astype(bool)

    intersection = np.logical_and(pred, gt).sum()

    return (2.0 * intersection) / (
        pred.sum() + gt.sum() + 1e-8
    )


def iou_score(pred, gt):
    pred = pred.astype(bool)
    gt = gt.astype(bool)

    intersection = np.logical_and(pred, gt).sum()
    union = np.logical_or(pred, gt).sum()

    return intersection / (union + 1e-8)


def centroid_distance(pred, gt):

    pred_yx = np.argwhere(pred > 0)
    gt_yx = np.argwhere(gt > 0)

    if len(pred_yx) == 0 or len(gt_yx) == 0:
        return np.nan

    pred_centroid = pred_yx.mean(axis=0)
    gt_centroid = gt_yx.mean(axis=0)

    return np.linalg.norm(pred_centroid - gt_centroid)


def pointing_game(cam_map, gt):

    if gt.sum() == 0:
        return np.nan

    max_y, max_x = np.unravel_index(
        np.argmax(cam_map),
        cam_map.shape
    )

    return float(gt[max_y, max_x] > 0)


# ------------------------------------------------------------
# Validation
# ------------------------------------------------------------

results = []

print("=" * 70)
print("FINAL GRAD-CAM LOCALIZATION VALIDATION")
print("=" * 70)

print("Annotated images:", len(matched_df))
print("Thresholds:", THRESHOLDS)

for _, row in tqdm(
    matched_df.iterrows(),
    total=len(matched_df),
    desc="Validating"
):

    sample_idx = int(row["index"])
    label = row["label"]

    # --------------------------------------------------------
    # Get model input
    # --------------------------------------------------------

    input_tensor, sample_label = test_dataset[sample_idx]

    input_tensor = input_tensor.unsqueeze(0).to(device)

    # --------------------------------------------------------
    # Grad-CAM
    # --------------------------------------------------------

    targets = [
        ClassifierOutputTarget(int(sample_label))
    ]

    grayscale_cam = cam(
        input_tensor=input_tensor,
        targets=targets
    )[0]

    # --------------------------------------------------------
    # Load GT overlay
    # --------------------------------------------------------

    overlay = np.array(
        Image.open(row["overlay_path"]).convert("RGB")
    )

    gt_original = extract_gt_mask(overlay)

    # IMPORTANT:
    # Test transform is only Resize(224,224)
    # Therefore GT undergoes the same spatial resize.
    gt = cv2.resize(
        gt_original,
        (grayscale_cam.shape[1],
         grayscale_cam.shape[0]),
        interpolation=cv2.INTER_NEAREST
    )

    gt = (gt > 0).astype(np.uint8)

    # --------------------------------------------------------
    # Evaluate every threshold
    # --------------------------------------------------------

    for threshold in THRESHOLDS:

        # ====================================================
        # YOUR EXACT ORIGINAL LESION MASK CODE
        # ====================================================

        binary = (
            grayscale_cam > threshold
        ).astype(np.uint8)

        num_labels, labels, stats, centroids = (
            cv2.connectedComponentsWithStats(
                binary,
                connectivity=8
            )
        )

        clean = np.zeros_like(binary)

        if num_labels > 1:

            largest = (
                1 +
                np.argmax(
                    stats[1:, cv2.CC_STAT_AREA]
                )
            )

            clean[labels == largest] = 1

        # ----------------------------------------------------
        # Metrics
        # ----------------------------------------------------

        dice = dice_score(clean, gt)
        iou = iou_score(clean, gt)
        pointing = pointing_game(grayscale_cam, gt)
        centroid = centroid_distance(clean, gt)

        results.append({

            "index": sample_idx,
            "label": label,
            "threshold": threshold,

            "dice": dice,
            "iou": iou,

            "pointing_game": pointing,
            "centroid_distance": centroid,

            "gt_pixels": int(gt.sum()),
            "pred_pixels": int(clean.sum())
        })


# ------------------------------------------------------------
# DataFrame
# ------------------------------------------------------------

results_df = pd.DataFrame(results)

