# ============================================================

import torch
import torch.nn.functional as F
import numpy as np

model.eval()

captured_inputs = {}
hooks = []

# ------------------------------------------------------------
# Capture attention inputs
# ------------------------------------------------------------

def make_hook(name):
    def hook(module, inputs, output):
        captured_inputs[name] = inputs[0].detach()
    return hook


for name, module in attention_modules:
    hooks.append(
        module.register_forward_hook(
            make_hook(name)
        )
    )


