img_tensor, label = test_dataset[sample_idx]

x = img_tensor.unsqueeze(0).to(device)

captured_inputs.clear()

with torch.no_grad():
    logits = model(x)

prediction = logits.argmax(dim=1).item()

print("=" * 80)
print("SAMPLE")
print("=" * 80)

print("Index:", sample_idx)
print("True label:", label)
print("Prediction:", prediction)

print("\nCaptured attention layers:", len(captured_inputs))


# ============================================================
# RECONSTRUCT ATTENTION
# ============================================================

def reconstruct_attention(module, x):

    # --------------------------------------------------------
    # MaxViT attention input is:
    #
    # [B, P, N, C]
    #
    # Example:
    # [1, 1, 49, 512]
    # --------------------------------------------------------

    if x.ndim == 4:

        B, P, N, C = x.shape

        # Merge batch + partition
        x = x.reshape(
            B * P,
            N,
            C
        )

    elif x.ndim == 3:

        B, N, C = x.shape

    else:

        raise ValueError(
            f"Unexpected attention input shape: {x.shape}"
        )


    # --------------------------------------------------------
    # QKV
    # --------------------------------------------------------

    qkv = module.to_qkv(x)

    qkv = qkv.reshape(
        x.shape[0],
        N,
        3,
        module.n_heads,
        module.head_dim
    )

    # [3, B*P, heads, N, head_dim]

    qkv = qkv.permute(
        2, 0, 3, 1, 4
    )

    q = qkv[0]
    k = qkv[1]


    # --------------------------------------------------------
    # Scaled dot-product attention
    # --------------------------------------------------------

    q = q * (module.head_dim ** -0.5)

    attn = q @ k.transpose(-2, -1)

    # --------------------------------------------------------
    # Relative positional bias
    # --------------------------------------------------------

    relative_bias = module.get_relative_positional_bias()

    attn = attn + relative_bias

    attn = F.softmax(
        attn,
        dim=-1
    )

    return attn


# ============================================================
# TEST ALL 22 ATTENTION MODULES
# ============================================================

attention_results = {}

print("\n" + "=" * 80)
print("ATTENTION SHAPES")
print("=" * 80)

for name, module in attention_modules:

    inp = captured_inputs[name]

    attn = reconstruct_attention(
        module,
        inp
    )

    attention_results[name] = attn.cpu()

    print(
        f"{name}\n"
        f"  Input     : {tuple(inp.shape)}\n"
        f"  Attention : {tuple(attn.shape)}\n"
        f"  Min       : {attn.min().item():.6f}\n"
        f"  Max       : {attn.max().item():.6f}\n"
        f"  Mean      : {attn.mean().item():.6f}"
    )


# ============================================================
# SANITY CHECK
