import numpy as np
import cv2
import matplotlib.pyplot as plt
from PIL import Image

model.eval()

# ------------------------------------------------------------
# Capture attention matrices
# ------------------------------------------------------------

captured_inputs = {}
hooks = []

def make_hook(name):
    def hook(module, inputs, output):
        captured_inputs[name] = inputs[0].detach()
    return hook


for name, module in attention_modules:
    hooks.append(
        module.register_forward_hook(
            make_hook(name)
        )
    )


# ------------------------------------------------------------
# One annotated sample
# ------------------------------------------------------------

sample_idx = int(matched_df.iloc[0]["index"])

img_tensor, true_label = test_dataset[sample_idx]

x = img_tensor.unsqueeze(0).to(device)

with torch.no_grad():
    logits = model(x)

prediction = logits.argmax(dim=1).item()

print("=" * 80)
print("SAMPLE")
print("=" * 80)
print("Index      :", sample_idx)
print("True label :", true_label)
print("Prediction :", prediction)


# ------------------------------------------------------------
# Reconstruct attention
# ------------------------------------------------------------

def reconstruct_attention(module, x):

    # [B, P, 49, C]
    if x.ndim == 4:

        B, P, N, C = x.shape

        x = x.reshape(
            B * P,
            N,
            C
        )

    elif x.ndim == 3:

        B, N, C = x.shape

    else:

        raise ValueError(
            f"Unexpected shape: {x.shape}"
        )


    # QKV
    qkv = module.to_qkv(x)

    qkv = qkv.reshape(
        x.shape[0],
        N,
        3,
        module.n_heads,
        module.head_dim
    )

    qkv = qkv.permute(
        2, 0, 3, 1, 4
    )

    q = qkv[0]
    k = qkv[1]

    # scaled dot product
    q = q * (module.head_dim ** -0.5)

    attn = q @ k.transpose(-2, -1)

    # relative positional bias
    relative_bias = module.get_relative_positional_bias()

    attn = attn + relative_bias

    attn = F.softmax(
        attn,
        dim=-1
    )

    return attn.detach()


# ------------------------------------------------------------
# Extract all attention
# ------------------------------------------------------------

attention_results = {}

for name, module in attention_modules:

    attn = reconstruct_attention(
        module,
        captured_inputs[name]
    )

    attention_results[name] = attn.cpu()


print("\nCaptured attention layers:", len(attention_results))


# ============================================================
# LAST STAGE
# ============================================================

last_window_name = [
    k for k in attention_results
    if k.startswith("blocks.3")
    and "window_attention" in k
][-1]

last_grid_name = [
    k for k in attention_results
    if k.startswith("blocks.3")
    and "grid_attention" in k
][-1]


window_attn = attention_results[
    last_window_name
]

grid_attn = attention_results[
    last_grid_name
]


print("\n" + "=" * 80)
print("LAST STAGE")
print("=" * 80)

print(
    "Window:",
    last_window_name,
    window_attn.shape
)

print(
    "Grid  :",
    last_grid_name,
    grid_attn.shape
)


# ============================================================
# TOKEN IMPORTANCE
# ============================================================

def token_importance(attn):

    # attn:
    # [partitions, heads, 49, 49]

    # Average heads
    A = attn.mean(dim=1)

    # Average attention received by each token
    score = A.mean(dim=1)

    return score


window_score = token_importance(
    window_attn
)

grid_score = token_importance(
    grid_attn
)


print("\nWindow score:", window_score.shape)
print("Grid score  :", grid_score.shape)


# ============================================================
# 7 x 7 MAP
# ============================================================

window_map = window_score.reshape(
    -1,
    7,
    7
)

grid_map = grid_score.reshape(
    -1,
    7,
    7
)


# Average partitions
window_map = window_map.mean(dim=0)
grid_map = grid_map.mean(dim=0)


# Combine
combined = (
    window_map + grid_map
) / 2.0


# Normalize
combined = combined - combined.min()

if combined.max() > 0:
    combined = combined / combined.max()


# ============================================================
# UPSAMPLE
# ============================================================

combined_224 = F.interpolate(
    combined[None, None],
    size=(224, 224),
    mode="bilinear",
    align_corners=False
)[0, 0]


combined_np = combined_224.detach().cpu().numpy()


print("\nFinal attention map:")
print("Shape:", combined_np.shape)
print("Min  :", combined_np.min())
print("Max  :", combined_np.max())


