import os
import numpy as np
import pandas as pd

# ------------------------------------------------------------
# 1. CORRECT MODEL LABEL MAPPING
# ------------------------------------------------------------

CLASS_MAP = {
    0: "Normal",
    1: "Ischemia",
    2: "Bleeding"
}

LABEL_TO_ID = {
    "Normal": 0,
    "Ischemia": 1,
    "Bleeding": 2
}

print("=" * 80)
print("CORRECT MODEL LABEL MAPPING")
print("=" * 80)

for k, v in CLASS_MAP.items():
    print(f"Pred ID {k} -> {v}")


# ------------------------------------------------------------
# 2. LOAD EXISTING ATTENTION ROLLOUT RESULTS
# ------------------------------------------------------------

RESULT_DIR = "/content/maxvit_attention_rollout_results"

DETAILED_PATH = os.path.join(
    RESULT_DIR,
    "attention_rollout_detailed.csv"
)

print("\n" + "=" * 80)
print("LOADING ATTENTION ROLLOUT RESULTS")
print("=" * 80)

results_df = pd.read_csv(DETAILED_PATH)

print("Loaded:", len(results_df), "rows")
print("\nColumns:")
print(results_df.columns.tolist())


# ------------------------------------------------------------
# 3. FIX TRUE LABEL -> ID
# ------------------------------------------------------------

def label_to_id(label):

    if isinstance(label, str):
        label = label.strip()

        if label in LABEL_TO_ID:
            return LABEL_TO_ID[label]

        # case-insensitive fallback
        label_lower = label.lower()

        if label_lower == "normal":
            return 0

        elif label_lower == "ischemia":
            return 1

        elif label_lower == "bleeding":
            return 2

    return int(label)


results_df["true_id_fixed"] = (
    results_df["true_label"]
    .apply(label_to_id)
)


# ------------------------------------------------------------
# 4. FIX PREDICTED LABEL
# ------------------------------------------------------------

results_df["pred_id"] = (
    results_df["pred_id"]
    .astype(int)
)

results_df["pred_label_fixed"] = (
    results_df["pred_id"]
    .map(CLASS_MAP)
)


# ------------------------------------------------------------
# 5. CORRECT / INCORRECT
# ------------------------------------------------------------

results_df["correct_fixed"] = (
    results_df["pred_id"] ==
    results_df["true_id_fixed"]
)


# ------------------------------------------------------------
# 6. CHECK
# ------------------------------------------------------------

