# ============================================================
# 10. SUMMARY FUNCTION
# ============================================================

def make_summary(df):

    rows = []

    for metric in available_metrics:

        values = df[metric].dropna()

        if len(values) == 0:
            mean_val = np.nan
            std_val = np.nan
        else:
            mean_val = values.mean()
            std_val = values.std()

        rows.append({
            "metric": metric,
            "N": len(values),
            "mean": mean_val,
            "std": std_val,
            "mean_std": (
                f"{mean_val:.4f} ± {std_val:.4f}"
                if len(values) > 0
                else "NA"
            )
        })

    return pd.DataFrame(rows)


