# ============================================================
# GT MASK EXTRACTION
# ============================================================

def extract_gt_mask(
    overlay_path
):

    overlay = cv2.imread(
        overlay_path,
        cv2.IMREAD_COLOR
    )

    if overlay is None:

        raise FileNotFoundError(
            overlay_path
        )

    overlay_rgb = cv2.cvtColor(
        overlay,
        cv2.COLOR_BGR2RGB
    )

    r = overlay_rgb[:, :, 0].astype(
        np.int16
    )

    g = overlay_rgb[:, :, 1].astype(
        np.int16
    )

    b = overlay_rgb[:, :, 2].astype(
        np.int16
    )

    colored = (
        ((r > g + 30) & (r > b + 30))
        |
        ((b > r + 30) & (b > g + 30))
    )

    return colored.astype(
        np.uint8
    )


# ============================================================
# EXACT DATASET TRANSFORM
# ============================================================

transform = transforms.Compose([

    transforms.Resize(
        (224, 224),
        interpolation=
        transforms.InterpolationMode.BILINEAR
    ),

    transforms.ToTensor(),

    transforms.Normalize(
        mean=[
            0.485,
            0.456,
            0.406
        ],

        std=[
            0.229,
            0.224,
            0.225
        ]
    )
])


# ============================================================
# FIND ATTENTION MODULES
# ============================================================

attention_modules = []

for name, module in model.named_modules():

    if isinstance(
        module,
        RelativePositionalMultiHeadAttention
    ):

        attention_modules.append(
            (name, module)
        )


print("\n" + "=" * 80)
print("ATTENTION MODULES")
print("=" * 80)

for i, (name, module) in enumerate(
    attention_modules
):

    print(
        i,
        name
    )


# ============================================================
# FINAL 4 ATTENTION MODULES
# ============================================================

final_attention_modules = (
    attention_modules[-4:]
)

print("\n" + "=" * 80)
print("FINAL-STAGE ATTENTION MODULES")
print("=" * 80)

for name, module in (
    final_attention_modules
):

    print(name)


# ============================================================
# HOOK STORAGE
# ============================================================

captured_inputs = []

hooks = []


def make_hook(module):

    def hook(
        module,
        inputs,
        output
    ):

        captured_inputs.append(
            inputs[0].detach()
        )

    return hook


for _, module in (
    final_attention_modules
):

    hooks.append(
        module.register_forward_hook(
            make_hook(module)
        )
    )


# ============================================================
# RECONSTRUCT ATTENTION
# ============================================================

@torch.no_grad()
def reconstruct_attention(
    module,
    x
):

    # x:
    # [B, G, P, C]

    B, G, P, C = x.shape

    head_dim = 32

    num_heads = C // head_dim

    qkv = module.to_qkv(x)

    qkv = qkv.reshape(
        B,
        G,
        P,
        3,
        num_heads,
        head_dim
    )

    qkv = qkv.permute(
        3,
        0,
        1,
        4,
        2,
        5
    )

    q, k, v = qkv.unbind(
        dim=0
    )

    q = q * (
        head_dim ** -0.5
    )

    attention = torch.matmul(
        q,
        k.transpose(
            -2,
            -1
        )
    )

    # Relative positional bias
    try:

        bias = (
            module.get_relative_positional_bias()
        )

        attention = (
            attention + bias
        )

    except Exception:
        pass

    attention = torch.softmax(
        attention,
        dim=-1
    )

    return attention


# ============================================================
# ATTENTION ROLLOUT
# ============================================================

def attention_rollout(
    attention_list
):

    rollout = None

    for A in attention_list:

        # [B,G,H,P,P]
        if A.dim() == 5:

            A = A[0]
            A = A[0]
            A = A.mean(
                dim=0
            )

        elif A.dim() == 4:

            A = A[0]
            A = A.mean(
                dim=0
            )

        elif A.dim() == 3:

            A = A.mean(
                dim=0
            )

        # A = [P,P]

        P = A.shape[-1]

        identity = torch.eye(
            P,
            device=A.device,
            dtype=A.dtype
        )

        A = A + identity

        A = A / (
            A.sum(
                dim=-1,
                keepdim=True
            )
            + 1e-8
        )

        if rollout is None:

            rollout = A

        else:

            rollout = (
                rollout @ A
            )

    return rollout


# ============================================================
# ROLLOUT TO 224x224
# ============================================================

def rollout_to_map(
    rollout
):

    # [49,49]

    token_score = rollout.mean(
        dim=0
    )

    token_score = (
        token_score
        .detach()
        .cpu()
        .numpy()
    )

    # 49 = 7 x 7
    token_score = token_score.reshape(
        7,
        7
    )

    # Min-max normalize
    min_value = token_score.min()

    max_value = token_score.max()

    if max_value > min_value:

        token_score = (
            token_score - min_value
        ) / (
            max_value - min_value
        )

    else:

        token_score = np.zeros_like(
            token_score
        )

    attention_map = cv2.resize(
        token_score,
        (224, 224),
        interpolation=cv2.INTER_LINEAR
    )

    return attention_map.astype(
        np.float32
    )


# ============================================================
# METRICS
# ============================================================

def dice_score(
    pred,
    gt
):

    pred = pred.astype(bool)
    gt = gt.astype(bool)

    intersection = np.logical_and(
        pred,
        gt
    ).sum()

    denominator = (
        pred.sum()
        + gt.sum()
    )

    if denominator == 0:
        return 1.0

    return (
        2.0 * intersection /
        denominator
    )


def iou_score(
    pred,
    gt
):

    pred = pred.astype(bool)
    gt = gt.astype(bool)

    intersection = np.logical_and(
        pred,
        gt
    ).sum()

    union = np.logical_or(
        pred,
        gt
    ).sum()

    if union == 0:
        return 1.0

    return (
        intersection /
        union
    )


def pointing_game(
    attention_map,
    gt
):

    y, x = np.unravel_index(
        np.argmax(attention_map),
        attention_map.shape
    )

    return int(
        gt[y, x] > 0
    )


def centroid_distance(
    pred,
    gt
):

    py, px = np.where(
        pred > 0
    )

    gy, gx = np.where(
        gt > 0
    )

    if len(px) == 0:
        return np.nan

    if len(gx) == 0:
        return np.nan

    pred_center = np.array([
        px.mean(),
        py.mean()
    ])

    gt_center = np.array([
        gx.mean(),
        gy.mean()
    ])

    return float(
        np.linalg.norm(
            pred_center -
            gt_center
        )
    )


# ============================================================
# RUN
# ============================================================

print("\n" + "=" * 80)
print("RUNNING ATTENTION ROLLOUT")
print("=" * 80)

results = []

total = len(matched_df)

for counter, (_, row) in enumerate(
    matched_df.iterrows()
):

    image_path = (
        row["actual_image_path"]
    )

    overlay_path = (
        row["overlay_path"]
    )

    true_label = (
        str(row["label"])
        .strip()
    )

    # --------------------------------------------------------
    # Load image
    # --------------------------------------------------------

    image = cv2.imread(
        image_path,
        cv2.IMREAD_COLOR
    )

    if image is None:

        print(
            "SKIP:",
            image_path
        )

        continue

    image_rgb = cv2.cvtColor(
        image,
        cv2.COLOR_BGR2RGB
    )

    # NumPy -> PIL
    image_pil = Image.fromarray(
        image_rgb
    )

    # --------------------------------------------------------
    # GT
    # --------------------------------------------------------

    gt_original = extract_gt_mask(
        overlay_path
    )

    gt_224 = cv2.resize(
        gt_original,
        (224, 224),
        interpolation=cv2.INTER_NEAREST
    )

    gt_224 = (
        gt_224 > 0
    ).astype(np.uint8)

    # --------------------------------------------------------
    # Transform
    # --------------------------------------------------------

    tensor = transform(
        image_pil
    ).unsqueeze(
        0
    ).to(DEVICE)

    # --------------------------------------------------------
    # Forward
    # --------------------------------------------------------

    captured_inputs.clear()

    with torch.no_grad():

        logits = model(
            tensor
        )

        pred_id = int(
            logits.argmax(
                dim=1
            ).item()
        )

    pred_label = CLASS_MAP[
        pred_id
    ]

    true_id = LABEL_TO_ID[
        true_label
    ]

    correct = (
        pred_id == true_id
    )

    # --------------------------------------------------------
    # Verify hooks
    # --------------------------------------------------------

    if len(captured_inputs) != 4:

        print(
            f"ERROR {counter}: "
            f"captured "
            f"{len(captured_inputs)} "
            f"modules"
        )

        continue

    # --------------------------------------------------------
    # Reconstruct attention
    # --------------------------------------------------------

    attention_list = []

    for (
        (_, module),
        x
    ) in zip(
        final_attention_modules,
        captured_inputs
    ):

        A = reconstruct_attention(
            module,
            x
        )

        attention_list.append(
            A
        )

    # --------------------------------------------------------
    # Rollout
    # --------------------------------------------------------

    rollout = attention_rollout(
        attention_list
    )

    # --------------------------------------------------------
    # Spatial map
    # --------------------------------------------------------

    attention_map = rollout_to_map(
        rollout
    )

    # --------------------------------------------------------
    # Sanity check
    # --------------------------------------------------------

    if (
        np.isnan(
            attention_map
        ).any()
    ):

        print(
            f"ERROR {counter}: "
            "NaN attention"
        )

        continue

    # --------------------------------------------------------
    # Pointing
    # --------------------------------------------------------

    pointing = pointing_game(
        attention_map,
        gt_224
    )

    # --------------------------------------------------------
    # Record
    # --------------------------------------------------------

    record = {

        "index":
            int(row["index"]),

        "filename":
            row["filename"],

        "true_label":
            true_label,

        "true_id":
            true_id,

        "pred_id":
            pred_id,

        "pred_label":
            pred_label,

        "correct":
            correct,

        "overlay_path":
            overlay_path,

        "pointing_game":
            pointing
    }

    # --------------------------------------------------------
    # Thresholds
    # --------------------------------------------------------

    for threshold in THRESHOLDS:

        binary = (
            attention_map >= threshold
        ).astype(np.uint8)

        record[
            f"dice_{threshold:.2f}"
        ] = dice_score(
            binary,
            gt_224
        )

        record[
            f"iou_{threshold:.2f}"
        ] = iou_score(
            binary,
            gt_224
        )

        record[
            f"area_{threshold:.2f}"
        ] = int(
            binary.sum()
        )

        record[
            f"centroid_{threshold:.2f}"
        ] = centroid_distance(
            binary,
            gt_224
        )

    results.append(
        record
    )

    # --------------------------------------------------------
    # Progress
    # --------------------------------------------------------

    if (
        counter == 0
        or (counter + 1) % 25 == 0
        or counter + 1 == total
    ):

        print(
            f"{counter + 1}/{total} | "
            f"True={true_label} | "
            f"Pred={pred_label} | "
            f"Correct={correct} | "
            f"Dice@0.55="
            f"{record['dice_0.55']:.4f} | "
            f"IoU@0.55="
            f"{record['iou_0.55']:.4f} | "
            f"Point="
            f"{pointing}"
        )


# ============================================================
# REMOVE HOOKS
# ============================================================

for h in hooks:
    h.remove()


# ============================================================
# RESULTS
# ============================================================

results_df = pd.DataFrame(
    results
)

print("\n" + "=" * 80)
print("ATTENTION ROLLOUT FINISHED")
print("=" * 80)

print(
    "Successful:",
    len(results_df),
    "/",
    len(matched_df)
)


# ============================================================
# CLASSIFICATION
# ============================================================

print("\n" + "=" * 80)
print("CLASSIFICATION")
print("=" * 80)

correct_n = int(
    results_df["correct"].sum()
)

total_n = len(
    results_df
)

print(
    "Total:",
    total_n
)

print(
    "Correct:",
    correct_n
)

print(
    "Incorrect:",
    total_n - correct_n
)

print(
    "Accuracy:",
    correct_n / total_n
)


# ============================================================
# SUMMARY FUNCTION
# ============================================================

def make_summary(
    data
):

    rows = []

    for threshold in THRESHOLDS:

        rows.append({

            "threshold":
                threshold,

            "N":
                len(data),

            "Dice_mean":
                data[
                    f"dice_{threshold:.2f}"
                ].mean(),

            "Dice_std":
                data[
                    f"dice_{threshold:.2f}"
                ].std(),

            "IoU_mean":
                data[
                    f"iou_{threshold:.2f}"
                ].mean(),

            "IoU_std":
                data[
                    f"iou_{threshold:.2f}"
                ].std(),

            "Area_mean":
                data[
                    f"area_{threshold:.2f}"
                ].mean(),

            "Area_std":
                data[
                    f"area_{threshold:.2f}"
                ].std(),

            "Pointing_mean":
                data[
                    "pointing_game"
                ].mean(),

            "Pointing_std":
                data[
                    "pointing_game"
                ].std(),

            "Centroid_mean":
                data[
                    f"centroid_{threshold:.2f}"
                ].mean(),

            "Centroid_std":
                data[
                    f"centroid_{threshold:.2f}"
                ].std()
        })

    return pd.DataFrame(
        rows
    )


# ============================================================
# ALL
# ============================================================

summary_all = make_summary(
    results_df
)


# ============================================================
# CORRECT ONLY
# ============================================================

correct_df = results_df[
    results_df["correct"]
].copy()

summary_correct = make_summary(
    correct_df
)


# ============================================================
# CLASSWISE CORRECT
# ============================================================

classwise = []

for cls in [
    "Bleeding",
    "Ischemia"
]:

    subset = correct_df[
        correct_df["true_label"] == cls
    ]

    temp = make_summary(
        subset
    )

    temp.insert(
        0,
        "class",
        cls
    )

    classwise.append(
        temp
    )

classwise_df = pd.concat(
    classwise,
    ignore_index=True
)


