from pytorch_grad_cam.utils.model_targets import ClassifierOutputTarget

fig, axes = plt.subplots(3, 3, figsize=(13, 12))

classes = ["Normal", "Bleeding", "Ischemia"]

for row, cls in enumerate(classes):

    # ---------------------------------------
    # Image Path
    # ---------------------------------------
    img_path = selected_df[selected_df["label"] == cls]["image_path"].values[0]

    # ---------------------------------------
    # Read Image
    # ---------------------------------------
    pil_img = Image.open(img_path).convert("RGB")
    pil_resize = pil_img.resize((224,224))

    rgb_img = np.array(pil_resize).astype(np.float32)/255.0

    input_tensor = val_transform(pil_resize).unsqueeze(0).to(device)

    # ---------------------------------------
    # Prediction
    # ---------------------------------------
    with torch.no_grad():

        output = model(input_tensor)

        probs = torch.softmax(output, dim=1)

        confidence, pred = torch.max(probs,1)

    pred = pred.item()
    confidence = confidence.item()

    pred_name = idx_to_label[pred]

    # ---------------------------------------
    # GradCAM
    # ---------------------------------------
    grayscale_cam = cam(
        input_tensor=input_tensor,
        targets=[ClassifierOutputTarget(pred)]
    )[0]

