candidate_images = [
    "15051.png",
    "12693.png",
    "10957.png",
    "14764.png",
    "15095.png",
    "14396.png"
]

fig, axes = plt.subplots(2, 3, figsize=(12,8))

for ax, img_name in zip(axes.ravel(), candidate_images):

    img_path = test_df[
        test_df["image_path"].str.endswith(img_name)
    ]["image_path"].values[0]

    pil = Image.open(img_path).convert("RGB")
    pil = pil.resize((224,224))

    rgb = np.array(pil).astype(np.float32)/255.

    tensor = val_transform(pil).unsqueeze(0).to(device)

    with torch.no_grad():
        out = model(tensor)
        pred = out.argmax(1).item()

    cam_map = cam(
        input_tensor=tensor,
        targets=[ClassifierOutputTarget(pred)]
    )[0]

    overlay = show_cam_on_image(rgb, cam_map, use_rgb=True)

    ax.imshow(overlay)
    ax.set_title(img_name)
    ax.axis("off")

plt.tight_layout()
plt.show()

