# ============================================================
# SELF-CONTAINED GRAD-CAM VALIDATION
# YOUR ORIGINAL WORKING GRAD-CAM PIPELINE
# ============================================================

import os
import cv2
import numpy as np
import pandas as pd
import torch
import torch.nn as nn

from PIL import Image
from torchvision import transforms
from torchvision.models import maxvit_t

from pytorch_grad_cam import GradCAM
from pytorch_grad_cam.utils.model_targets import ClassifierOutputTarget


# ============================================================
# 1. DEVICE
# ============================================================

device = torch.device(
    "cuda" if torch.cuda.is_available() else "cpu"
)

print("=" * 70)
print("Device:", device)
print("=" * 70)


# ============================================================
# 2. YOUR ORIGINAL val_transform
# ============================================================

val_transform = transforms.Compose([
    transforms.Resize((224, 224)),
    transforms.ToTensor(),
    transforms.Normalize(
        mean=[0.485, 0.456, 0.406],
        std=[0.229, 0.224, 0.225]
    )
])

print("val_transform ready.")


# ============================================================
# 3. CHECK test_df
# ============================================================

if "test_df" not in globals():

    raise NameError(
        "test_df is not defined. "
        "Please run the cell where test_df was created."
    )


print("Test samples:", len(test_df))


# ============================================================
# 4. LOAD MODEL
# ============================================================

BEST_MODEL_PATH = (
    "/content/drive/MyDrive/"
    "Stroke_MaxViT_Model/"
    "best_maxvit_t.pth"
)

model = maxvit_t(weights=None)

in_features = model.classifier[5].in_features

model.classifier[5] = nn.Linear(
    in_features,
    3
)

model.load_state_dict(
    torch.load(
        BEST_MODEL_PATH,
        map_location=device
    )
)

model = model.to(device)
model.eval()

print("MaxViT loaded.")


# ============================================================
# 5. ACTUAL CLASS MAPPING
# ============================================================

idx_to_label = {
    0: "Normal",
    1: "Bleeding",
    2: "Ischemia"
}

print("Class mapping:", idx_to_label)


# ============================================================
# 6. SAME TARGET LAYER FROM YOUR OLD CODE
# ============================================================

target_layer = (
    model
    .blocks[3]
    .layers[1]
    .layers
    .MBconv
    .layers
    .conv_c
)

print("\nTarget layer:")
print(target_layer)


# ============================================================
# 7. GRAD-CAM
# ============================================================

cam = GradCAM(
    model=model,
    target_layers=[target_layer]
)

print("Grad-CAM ready.")


# ============================================================
# 8. OVERLAY → GT LESION MASK
# ============================================================

def extract_gt_mask(overlay_rgb):

    r = overlay_rgb[:, :, 0].astype(np.int16)
    g = overlay_rgb[:, :, 1].astype(np.int16)
    b = overlay_rgb[:, :, 2].astype(np.int16)

    colored = (
        ((r > g + 30) & (r > b + 30)) |
        ((b > r + 30) & (b > g + 30))
    )

    return colored.astype(np.uint8)


# ============================================================
# 9. FIND CORRESPONDING OVERLAY
# ============================================================

def get_overlay_path(image_path):

    if "/PNG/" not in image_path:
        return None

    overlay_path = image_path.replace(
        "/PNG/",
        "/OVERLAY/"
    )

    if os.path.exists(overlay_path):
        return overlay_path

    return None


# ============================================================
# 10. VALIDATION
# ============================================================

results = []

print("\n")
print("=" * 70)
print("STARTING GRAD-CAM VALIDATION")
print("=" * 70)


for idx in range(len(test_df)):

    image_path = test_df.iloc[idx]["image_path"]

    true_class = str(
        test_df.iloc[idx]["label"]
    )


    # --------------------------------------------------------
    # Find GT overlay
    # --------------------------------------------------------

    overlay_path = get_overlay_path(
        image_path
    )

    if overlay_path is None:
        continue


    # ========================================================
    # EXACT OLD CODE
    # ========================================================

    pil_img = Image.open(
        image_path
    ).convert("RGB")

    pil_img = pil_img.resize(
        (224, 224)
    )

    rgb_img = (
        np.array(pil_img)
        .astype(np.float32) / 255.0
    )


    # ========================================================
    # EXACT OLD val_transform
    # ========================================================

    input_tensor = val_transform(
        pil_img
    ).unsqueeze(0).to(device)


    # ========================================================
    # PREDICTION
    # ========================================================

    with torch.no_grad():

        output = model(
            input_tensor
        )

        probs = torch.softmax(
            output,
            dim=1
        )

        confidence, pred = torch.max(
            probs,
            1
        )

    pred = pred.item()
    confidence = confidence.item()

    pred_name = idx_to_label[pred]


    # ========================================================
    # EXACT OLD GRAD-CAM
    # ========================================================

    grayscale_cam = cam(
        input_tensor=input_tensor,
        targets=[
            ClassifierOutputTarget(pred)
        ]
    )[0]


    # ========================================================
    # EXACT OLD VISUALIZATION THRESHOLD
    # ========================================================
    #
    # Your old code:
    #
    # grayscale_cam[grayscale_cam < 0.35] = 0
    #
    # ========================================================

    grayscale_cam = grayscale_cam.copy()

    grayscale_cam[
        grayscale_cam < 0.35
    ] = 0


    # ========================================================
    # CAM MASK
    # ========================================================

    cam_mask = (
        grayscale_cam > 0
    ).astype(np.uint8)


    # ========================================================
    # GT OVERLAY
    # ========================================================

    overlay_rgb = np.array(
        Image.open(
            overlay_path
        ).convert("RGB")
    )


    # ========================================================
    # GT LESION MASK
    # ========================================================

    gt_mask_original = extract_gt_mask(
        overlay_rgb
    )


    # ========================================================
    # GT → 224×224
    # ========================================================

    gt_mask_pil = Image.fromarray(
        gt_mask_original * 255
    )

    gt_mask_pil = gt_mask_pil.resize(
        (224, 224),
        Image.Resampling.NEAREST
    )

    gt_mask = (
        np.array(gt_mask_pil) > 0
    ).astype(np.uint8)


    # ========================================================
    # DICE
    # ========================================================

    intersection = np.logical_and(
        cam_mask,
        gt_mask
    ).sum()

    cam_area = cam_mask.sum()

    gt_area = gt_mask.sum()

    dice = (
        2.0 * intersection /
        (
            cam_area +
            gt_area +
            1e-8
        )
    )


    # ========================================================
    # IoU
    # ========================================================

    union = np.logical_or(
        cam_mask,
        gt_mask
    ).sum()

    iou = (
        intersection /
        (union + 1e-8)
    )


    # ========================================================
    # POINTING GAME
    # ========================================================

    max_pos = np.unravel_index(
        np.argmax(grayscale_cam),
        grayscale_cam.shape
    )

    pointing = int(
        gt_mask[
            max_pos[0],
            max_pos[1]
        ] > 0
    )


    # ========================================================
    # CENTROID DISTANCE
    # ========================================================

    cam_coords = np.argwhere(
        cam_mask > 0
    )

    gt_coords = np.argwhere(
        gt_mask > 0
    )


    if (
        len(cam_coords) > 0
        and
        len(gt_coords) > 0
    ):

        cam_centroid = cam_coords.mean(
            axis=0
        )

        gt_centroid = gt_coords.mean(
            axis=0
        )

        centroid_distance = np.linalg.norm(
            cam_centroid -
            gt_centroid
        )

    else:

        centroid_distance = np.nan


    # ========================================================
    # CORRECT PREDICTION
    # ========================================================

    correct = (
        pred_name.lower()
        ==
        true_class.lower()
    )


    # ========================================================
    # STORE
    # ========================================================

    results.append({

        "index": idx,

        "image": os.path.basename(
            image_path
        ),

        "true_class": true_class,

        "pred_class": pred_name,

        "confidence": confidence,

        "correct": correct,

        "cam_area": int(
            cam_area
        ),

        "gt_area": int(
            gt_area
        ),

        "overlap": int(
            intersection
        ),

        "dice": float(
            dice
        ),

        "iou": float(
            iou
        ),

        "pointing_game": int(
            pointing
        ),

        "centroid_distance": float(
            centroid_distance
        )
    })


    # ========================================================
    # PROGRESS
    # ========================================================

    if len(results) % 25 == 0:

        print(
            f"Processed annotated images: "
            f"{len(results)}"
        )


# ============================================================
# DATAFRAME
# ============================================================

results_df = pd.DataFrame(
    results
)


# ============================================================
# FINAL RESULTS
# ============================================================

print("\n")
print("=" * 70)
print("VALIDATION COMPLETE")
print("=" * 70)

print(
    "Annotated images:",
    len(results_df)
)


# ============================================================
# OVERALL
# ============================================================

if len(results_df) > 0:

    print("\n")
    print("=" * 70)
    print("OVERALL RESULTS")
    print("=" * 70)

    print(
        f"Dice              : "
        f"{results_df['dice'].mean():.4f} "
        f"± {results_df['dice'].std():.4f}"
    )

    print(
        f"IoU               : "
        f"{results_df['iou'].mean():.4f} "
        f"± {results_df['iou'].std():.4f}"
    )

    print(
        f"Pointing Game     : "
        f"{results_df['pointing_game'].mean():.4f} "
        f"± {results_df['pointing_game'].std():.4f}"
    )

    print(
        f"Centroid Distance: "
        f"{results_df['centroid_distance'].mean():.4f} "
        f"± {results_df['centroid_distance'].std():.4f}"
    )


# ============================================================
# CLASS-WISE
# ============================================================

if len(results_df) > 0:

    print("\n")
    print("=" * 70)
    print("CLASS-WISE RESULTS")
    print("=" * 70)

    class_summary = (
        results_df
        .groupby("true_class")
        .agg(

            N=("image", "count"),

            Dice_mean=("dice", "mean"),
            Dice_std=("dice", "std"),

            IoU_mean=("iou", "mean"),
            IoU_std=("iou", "std"),

            Pointing_mean=(
                "pointing_game",
                "mean"
            ),

            Centroid_mean=(
                "centroid_distance",
                "mean"
            ),

            Centroid_std=(
                "centroid_distance",
                "std"
            )
        )
    )

    print(
        class_summary.round(4)
    )


# ============================================================
# CORRECT VS INCORRECT
# ============================================================

if len(results_df) > 0:

    print("\n")
    print("=" * 70)
    print("CORRECT VS INCORRECT")
    print("=" * 70)

    correct_summary = (
        results_df
        .groupby("correct")
        .agg(

            N=("image", "count"),

            Dice=("dice", "mean"),

            IoU=("iou", "mean"),

            Pointing=(
                "pointing_game",
                "mean"
            ),

            Centroid=(
                "centroid_distance",
                "mean"
            )
        )
    )

    print(
        correct_summary.round(4)
    )


# ============================================================
# SAVE
# ============================================================

output_path = (
    "/content/"
    "gradcam_validation_old_working_pipeline.csv"
)

results_df.to_csv(
    output_path,
    index=False
)

print("\n")
print("=" * 70)
print("CSV SAVED")
print("=" * 70)

print(output_path)

