# ============================================================
# 6. GRAD-CAM
# ============================================================

cam = GradCAM(
    model=model,
    target_layers=[target_layer]
)

print("\nGrad-CAM initialized.")


# ============================================================
# 7. CHECK TEST DATA
# ============================================================

if "test_df" not in globals():

    raise NameError(
        "test_df is not defined. "
        "Please run your test dataset cell first."
    )

