# ============================================================
# DIAGNOSTIC:
# EXACT OLD GRAD-CAM + GT LESION CONTOUR
# ============================================================

import cv2
import numpy as np
import matplotlib.pyplot as plt
import torch
from PIL import Image

from pytorch_grad_cam.utils.image import show_cam_on_image
from pytorch_grad_cam.utils.model_targets import ClassifierOutputTarget


# ============================================================
# ACTUAL MODEL MAPPING
# ============================================================

idx_to_label = {
    0: "Normal",
    1: "Ischemia",
    2: "Bleeding"
}


# ============================================================
# SAME REPRESENTATIVE IMAGES
# ============================================================

selected_images = {
    "Bleeding": "15509.png",
    "Ischemia": "11871.png"
}


# ============================================================
# GT EXTRACTION
# ============================================================

def extract_gt_mask(overlay_rgb):

    r = overlay_rgb[:, :, 0].astype(np.int16)
    g = overlay_rgb[:, :, 1].astype(np.int16)
    b = overlay_rgb[:, :, 2].astype(np.int16)

    colored = (
        ((r > g + 30) & (r > b + 30)) |
        ((b > r + 30) & (b > g + 30))
    )

    return colored.astype(np.uint8)


# ============================================================
# OVERLAY PATH
# ============================================================

def get_overlay_path(image_path):

    if "/PNG/" not in image_path:
        return None

    p = image_path.replace(
        "/PNG/",
        "/OVERLAY/"
    )

    if os.path.exists(p):
        return p

    return None


# ============================================================
# FIGURE
# ============================================================

fig, axes = plt.subplots(
    2,
    4,
    figsize=(16, 8)
)


for row, (true_cls, img_name) in enumerate(
    selected_images.items()
):

    # --------------------------------------------------------
    # FIND IMAGE
    # --------------------------------------------------------

    matches = test_df[
        test_df["image_path"].str.endswith(
            img_name
        )
    ]

    if len(matches) == 0:
        print("Not found:", img_name)
        continue

    img_path = matches.iloc[0]["image_path"]


    # --------------------------------------------------------
    # ORIGINAL IMAGE
    # SAME AS OLD CODE
    # --------------------------------------------------------

    pil_img = Image.open(
        img_path
    ).convert("RGB")

    pil_img = pil_img.resize(
        (224, 224)
    )

    rgb_img = (
        np.array(pil_img)
        .astype(np.float32) / 255.0
    )


    # --------------------------------------------------------
    # SAME OLD TRANSFORM
    # --------------------------------------------------------

    input_tensor = val_transform(
        pil_img
    ).unsqueeze(0).to(device)


    # --------------------------------------------------------
    # PREDICTION
    # --------------------------------------------------------

    with torch.no_grad():

        output = model(
            input_tensor
        )

        probs = torch.softmax(
            output,
            dim=1
        )

        confidence, pred = torch.max(
            probs,
            dim=1
        )

    pred = pred.item()

    pred_name = idx_to_label[pred]

    confidence = confidence.item()


    # --------------------------------------------------------
    # SAME OLD GRAD-CAM
    # --------------------------------------------------------

    grayscale_cam = cam(
        input_tensor=input_tensor,
        targets=[
            ClassifierOutputTarget(pred)
        ]
    )[0]


    # --------------------------------------------------------
    # SAME OLD 0.35 THRESHOLD
    # --------------------------------------------------------

    cam_original = grayscale_cam.copy()

    cam_thresholded = grayscale_cam.copy()

    cam_thresholded[
        cam_thresholded < 0.35
    ] = 0


    # --------------------------------------------------------
    # CAM MASK
    # --------------------------------------------------------

    cam_mask = (
        cam_thresholded > 0
    ).astype(np.uint8)


    # --------------------------------------------------------
    # GT OVERLAY
    # --------------------------------------------------------

    overlay_path = get_overlay_path(
        img_path
    )

    overlay_rgb = np.array(
        Image.open(
            overlay_path
        ).convert("RGB")
    )


    # --------------------------------------------------------
    # GT MASK
    # --------------------------------------------------------

    gt_original = extract_gt_mask(
        overlay_rgb
    )

    gt_pil = Image.fromarray(
        gt_original * 255
    )

    gt_pil = gt_pil.resize(
        (224, 224),
        Image.Resampling.NEAREST
    )

    gt_mask = (
        np.array(gt_pil) > 0
    ).astype(np.uint8)


    # --------------------------------------------------------
    # DICE
    # --------------------------------------------------------

    intersection = np.logical_and(
        cam_mask,
        gt_mask
    ).sum()

    union = np.logical_or(
        cam_mask,
        gt_mask
    ).sum()

    dice = (
        2 * intersection /
        (
            cam_mask.sum()
            +
            gt_mask.sum()
            +
            1e-8
        )
    )

    iou = (
        intersection /
        (union + 1e-8)
    )


    # --------------------------------------------------------
    # MAX CAM LOCATION
    # IMPORTANT:
    # use ORIGINAL CAM, NOT THRESHOLDED CAM
    # --------------------------------------------------------

    max_pos = np.unravel_index(
        np.argmax(cam_original),
        cam_original.shape
    )

    max_inside_gt = (
        gt_mask[
            max_pos[0],
            max_pos[1]
        ] > 0
    )


    # --------------------------------------------------------
    # GT CONTOUR
    # --------------------------------------------------------

    gt_contour_img = (
        rgb_img * 255
    ).astype(np.uint8)

    contours, _ = cv2.findContours(
        gt_mask,
        cv2.RETR_EXTERNAL,
        cv2.CHAIN_APPROX_SIMPLE
    )

    cv2.drawContours(
        gt_contour_img,
        contours,
        -1,
        (0, 255, 0),
        2
    )


    # --------------------------------------------------------
    # CAM OVERLAY
    # --------------------------------------------------------

    cam_overlay = show_cam_on_image(
        rgb_img,
        cam_thresholded,
        use_rgb=True,
        image_weight=0.75
    )


    # --------------------------------------------------------
    # CAM + GT CONTOUR
    # --------------------------------------------------------

    cam_gt = cam_overlay.copy()

    cv2.drawContours(
        cam_gt,
        contours,
        -1,
        (0, 255, 0),
        2
    )

    # mark CAM maximum
    cv2.circle(
        cam_gt,
        (
            max_pos[1],
            max_pos[0]
        ),
        4,
        (255, 0, 0),
        -1
    )


    # --------------------------------------------------------
    # PRINT
    # --------------------------------------------------------

    print("\n" + "=" * 60)

    print("Image:", img_name)

    print("True:", true_cls)

    print(
        "Pred:",
        pred_name,
        f"({confidence*100:.2f}%)"
    )

    print(
        "GT pixels:",
        int(gt_mask.sum())
    )

    print(
        "CAM pixels:",
        int(cam_mask.sum())
    )

    print(
        "Overlap:",
        int(intersection)
    )

    print(
        "Dice:",
        f"{dice:.4f}"
    )

    print(
        "IoU:",
        f"{iou:.4f}"
    )

    print(
        "CAM max:",
        max_pos
    )

    print(
        "CAM max inside GT:",
        max_inside_gt
    )


    # --------------------------------------------------------
    # ROW VISUALIZATION
    # --------------------------------------------------------

    axes[row, 0].imshow(
        rgb_img
    )

    axes[row, 0].set_title(
        f"{true_cls}\nOriginal"
    )

    axes[row, 0].axis("off")


    axes[row, 1].imshow(
        cam_overlay
    )

    axes[row, 1].set_title(
        f"Old Grad-CAM\n"
        f"Pred: {pred_name}"
    )

    axes[row, 1].axis("off")


    axes[row, 2].imshow(
        gt_contour_img
    )

    axes[row, 2].set_title(
        "GT Lesion Contour"
    )

    axes[row, 2].axis("off")


    axes[row, 3].imshow(
        cam_gt
    )

    axes[row, 3].set_title(
        f"CAM + GT\n"
        f"Dice={dice:.4f}, IoU={iou:.4f}"
    )

    axes[row, 3].axis("off")


plt.tight_layout()

plt.show()

