import numpy as np
import cv2

def attention_grid_analysis(rgb_img, attention_mask):
    """
    rgb_img: Original image (224x224x3)
    attention_mask: Binary attention mask (224x224)
    """

    # -----------------------------
    # Brain Mask
    # -----------------------------
    gray = cv2.cvtColor((rgb_img * 255).astype(np.uint8), cv2.COLOR_RGB2GRAY)

    _, brain = cv2.threshold(gray, 10, 255, cv2.THRESH_BINARY)

    contours, _ = cv2.findContours(
        brain,
        cv2.RETR_EXTERNAL,
        cv2.CHAIN_APPROX_SIMPLE
    )

    largest = max(contours, key=cv2.contourArea)

    x, y, w, h = cv2.boundingRect(largest)

    # -----------------------------
    # Divide into 3×3 Grid
    # -----------------------------
    cell_w = w // 3
    cell_h = h // 3

    region_pixels = []

    for r in range(3):
        for c in range(3):

            x1 = x + c * cell_w
            y1 = y + r * cell_h

            if c == 2:
                x2 = x + w
            else:
                x2 = x1 + cell_w

            if r == 2:
                y2 = y + h
            else:
                y2 = y1 + cell_h

            region = attention_mask[y1:y2, x1:x2]

            region_pixels.append(int(region.sum()))

    region_pixels = np.array(region_pixels)

    total = region_pixels.sum()

    if total > 0:
        percentages = region_pixels / total * 100
    else:
        percentages = np.zeros(9)

    dominant_region = np.argmax(percentages) + 1

    return percentages, dominant_region

# ==========================================================
# PART 1
# Grid Attention Analysis Function
# ==========================================================

import cv2
import numpy as np

def attention_grid_analysis(rgb_img, attention_mask):

    # -----------------------------
    # Brain Mask
    # -----------------------------
    gray = cv2.cvtColor(
        (rgb_img * 255).astype(np.uint8),
        cv2.COLOR_RGB2GRAY
    )

    _, brain = cv2.threshold(
        gray,
        10,
        255,
        cv2.THRESH_BINARY
    )

    contours, _ = cv2.findContours(
        brain,
        cv2.RETR_EXTERNAL,
        cv2.CHAIN_APPROX_SIMPLE
    )

    if len(contours) == 0:

        return np.zeros(9), 0

    largest = max(contours, key=cv2.contourArea)

    x, y, w, h = cv2.boundingRect(largest)

    # -----------------------------
    # Divide Brain into 3x3 Grid
    # -----------------------------
    cell_w = w // 3
    cell_h = h // 3

    percentages = []

    total_attention = attention_mask.sum()

    for r in range(3):

        for c in range(3):

            x1 = x + c * cell_w
            y1 = y + r * cell_h

            if c == 2:
                x2 = x + w
            else:
                x2 = x1 + cell_w

            if r == 2:
                y2 = y + h
            else:
                y2 = y1 + cell_h

            roi = attention_mask[y1:y2, x1:x2]

            value = roi.sum()

            if total_attention > 0:

                value = value / total_attention * 100

            else:

                value = 0

            percentages.append(value)

    percentages = np.array(percentages)

    dominant_region = np.argmax(percentages) + 1

    return percentages, dominant_region

