import cv2
import numpy as np

def anatomical_location(rgb_img, attention_mask):

    # Brain mask
    gray = cv2.cvtColor(
        (rgb_img*255).astype(np.uint8),
        cv2.COLOR_RGB2GRAY
    )

    _, brain = cv2.threshold(
        gray,
        10,
        255,
        cv2.THRESH_BINARY
    )

    contours, _ = cv2.findContours(
        brain,
        cv2.RETR_EXTERNAL,
        cv2.CHAIN_APPROX_SIMPLE
    )

    if len(contours)==0:
        return "Unknown","Unknown","Unknown"

    largest = max(contours,key=cv2.contourArea)

    bx,by,bw,bh = cv2.boundingRect(largest)

    # -----------------------------
    # Attention centroid
    # -----------------------------
    M = cv2.moments(attention_mask)

    if M["m00"]==0:
        return "None","None","None"

    cx = int(M["m10"]/M["m00"])
    cy = int(M["m01"]/M["m00"])

    # =============================
    # Left / Right
    # =============================

    brain_center_x = bx + bw/2

    if cx < brain_center_x:
        hemisphere = "Left"
    else:
        hemisphere = "Right"

    # =============================
    # Anterior / Middle / Posterior
    # =============================

    relative_y = cy - by

    if relative_y < bh/3:

        ap = "Anterior"

    elif relative_y < 2*bh/3:

        ap = "Middle"

    else:

        ap = "Posterior"

    # =============================
    # Final Region
    # =============================

    region = hemisphere + " " + ap

    return hemisphere, ap, region

# ==========================================================
# Run Anatomical Location Analysis
# ==========================================================

results = []

model.eval()

for idx in tqdm(range(len(test_dataset))):

    image, true_label = test_dataset[idx]

    input_tensor = image.unsqueeze(0).to(device)

    # Prediction
    with torch.no_grad():
        output = model(input_tensor)
        probs = torch.softmax(output, dim=1)
        confidence, pred = torch.max(probs, 1)

    pred = pred.item()
    confidence = confidence.item()

    # Grad-CAM
    grayscale_cam = cam(
        input_tensor=input_tensor,
        targets=[ClassifierOutputTarget(pred)]
    )[0]

    grayscale_cam = grayscale_cam.copy()
    grayscale_cam[grayscale_cam < 0.35] = 0

    binary = (grayscale_cam > 0).astype(np.uint8)

    num_labels, labels, stats, centroids = cv2.connectedComponentsWithStats(
        binary,
        connectivity=8
    )

    clean = np.zeros_like(binary)

    if num_labels > 1:
        largest = 1 + np.argmax(stats[1:, cv2.CC_STAT_AREA])
        clean[labels == largest] = 1

    area = int(clean.sum())

    if area > 0:
        x, y, w, h = cv2.boundingRect(clean)

        M = cv2.moments(clean)

        cx = int(M["m10"] / M["m00"])
        cy = int(M["m01"] / M["m00"])
    else:
        cx = cy = 0

    # RGB image
    rgb = image.permute(1,2,0).cpu().numpy()

    mean = np.array([0.485,0.456,0.406])
    std = np.array([0.229,0.224,0.225])

    rgb = std * rgb + mean
    rgb = np.clip(rgb,0,1)

    # Anatomical Region
    hemisphere, ap, region = anatomical_location(
        rgb,
        clean
    )

    results.append({

        "Image": test_df.iloc[idx]["image_path"].split("/")[-1],

        "TrueLabel": idx_to_label[true_label],

        "PredLabel": idx_to_label[pred],

        "Region": region,

        "Hemisphere": hemisphere,

        "AP_Location": ap

    })

attention_region_df = pd.DataFrame(results)

attention_region_df.to_csv(
    "attention_region_analysis.csv",
    index=False
)

print(attention_region_df.head())
print("\nTotal Images:", len(attention_region_df))

print(
    attention_region_df.groupby(
        ["TrueLabel", "Region"]
    ).size()
)

