ROOT = "/content/drive/MyDrive/archive (1)"

overlay_folders = {}

for current_root, dirs, files in os.walk(ROOT):

    for d in dirs:

        if d.strip().upper() == "OVERLAY":

            full_path = os.path.join(
                current_root,
                d
            )

            parent_name = os.path.basename(
                os.path.dirname(full_path)
            )

            # Only classification folders
            if parent_name in ["Bleeding", "Ischemia"]:

                overlay_folders[parent_name] = full_path


print("Found overlay folders:")

for label, path in overlay_folders.items():

    print(
        label,
        "->",
        path
    )


# ============================================================
# CREATE FILENAME INDEX
# ============================================================

overlay_index = {}

for label, folder in overlay_folders.items():

    for fname in os.listdir(folder):

        # Remove extension and normalize
        base = os.path.splitext(fname)[0]

        overlay_index[
            (label, base)
        ] = os.path.join(
            folder,
            fname
        )


