import os
import torch
import torch.nn as nn
from torchvision.models import maxvit_t

# Device
device = torch.device("cuda" if torch.cuda.is_available() else "cpu")

# Model path
SAVE_DIR = "/content/drive/MyDrive/Stroke_MaxViT_Model"
BEST_MODEL_PATH = os.path.join(
    SAVE_DIR,
    "best_maxvit_t.pth"
)

# Create MaxViT
model = maxvit_t(weights=None)

# Change classifier to 3 classes
in_features = model.classifier[5].in_features

model.classifier[5] = nn.Linear(
    in_features,
    3
)

# Load trained weights
model.load_state_dict(
    torch.load(
        BEST_MODEL_PATH,
        map_location=device
    )
)

model = model.to(device)
model.eval()

print("MaxViT loaded successfully!")
print("Device:", device)

