        # ====================================================

        overlay = cv2.imread(overlay_path)

        if overlay is None:
            print(f"Could not read overlay: {overlay_path}")
            continue

        overlay_rgb = cv2.cvtColor(
            overlay,
            cv2.COLOR_BGR2RGB
        )

        # ====================================================
        # EXTRACT GT LESION MASK
        # ====================================================

        gt_mask = extract_gt_mask(overlay_rgb)

        # ====================================================
        # RESIZE IF NEEDED
        # ====================================================

        if gt_mask.shape != gradcam_mask.shape:

            gt_mask = cv2.resize(
                gt_mask,
                (
                    gradcam_mask.shape[1],
                    gradcam_mask.shape[0]
                ),
                interpolation=cv2.INTER_NEAREST
            )

            gt_mask = (gt_mask > 0).astype(np.uint8)

        # ====================================================
        # CALCULATE METRICS
        # ====================================================

        dice = dice_score(
            gradcam_mask,
            gt_mask
        )

        iou = iou_score(
            gradcam_mask,
            gt_mask
        )

        pointing = pointing_game_score(
            grayscale_cam,
            gt_mask
        )

        centroid_dist = centroid_distance(
            gradcam_mask,
            gt_mask
        )

        # ====================================================
