import os
import cv2
import numpy as np
import pandas as pd
import torch
import matplotlib.pyplot as plt

from tqdm.auto import tqdm
from torchvision import transforms
from pytorch_grad_cam import GradCAM
from pytorch_grad_cam.utils.model_targets import ClassifierOutputTarget


# ============================================================
# 1. CHECK BASIC OBJECTS
# ============================================================

print("=" * 70)
print("CHECKING NOTEBOOK OBJECTS")
print("=" * 70)

required_objects = [
    "model",
    "test_dataset",
    "test_df",
    "matched_df",
    "device"
]

for obj in required_objects:
    if obj in globals():
        print(f"✓ {obj}")
    else:
        print(f"✗ {obj} NOT FOUND")

print()


# ============================================================
# 2. SHOW DATASET TRANSFORM
# ============================================================

print("=" * 70)
print("TEST DATASET TRANSFORM")
print("=" * 70)

print(test_dataset.transform)
print()


# ============================================================
# 3. GET ONE SAMPLE
# ============================================================

sample_img, sample_label = test_dataset[0]

print("=" * 70)
print("SAMPLE INPUT INFORMATION")
print("=" * 70)

print("Tensor shape:", sample_img.shape)
print("Label:", sample_label)
print("Tensor dtype:", sample_img.dtype)
print()


# ============================================================
# 4. FIND GRAD-CAM TARGET LAYER
# ============================================================

print("=" * 70)
print("FINDING GRAD-CAM TARGET LAYER")
print("=" * 70)

# MaxViT has many Conv2d layers.
# We use the same layer that was previously selected.

target_layer = None
target_layer_name = None

for name, module in model.named_modules():

    if name == "blocks.3.layers.1.layers.MBconv.layers.conv_c":
        target_layer = module
        target_layer_name = name
        break


if target_layer is None:

    print("Previously used layer not found.")
    print("Available Conv2d layers near the end of model:")

    conv_layers = []

    for name, module in model.named_modules():

        if isinstance(module, torch.nn.Conv2d):
            conv_layers.append((name, module))

    for name, module in conv_layers[-20:]:
        print(name, module)

    raise RuntimeError(
        "Target layer not found. Please select a valid target layer."
    )


print("Target layer:")
print(target_layer_name)
print(target_layer)
print()


# ============================================================
# 5. INITIALIZE GRAD-CAM
# ============================================================

cam = GradCAM(
    model=model,
    target_layers=[target_layer]
)

print("Grad-CAM initialized successfully.")
print()


# ============================================================
# 6. OVERLAY -> GT MASK
# ============================================================

def extract_gt_mask(overlay_rgb):

    r = overlay_rgb[:, :, 0].astype(np.int16)
    g = overlay_rgb[:, :, 1].astype(np.int16)
    b = overlay_rgb[:, :, 2].astype(np.int16)

    colored = (
        ((r > g + 30) & (r > b + 30)) |
        ((b > r + 30) & (b > g + 30))
    )

    return colored.astype(np.uint8)


# ============================================================
# 7. MASK METRICS
# ============================================================

def dice_score(pred, gt):

    pred = pred.astype(bool)
    gt = gt.astype(bool)

    intersection = np.logical_and(pred, gt).sum()

    if pred.sum() == 0 and gt.sum() == 0:
        return 1.0

    return (
        2.0 * intersection /
        (pred.sum() + gt.sum() + 1e-8)
    )


def iou_score(pred, gt):

    pred = pred.astype(bool)
    gt = gt.astype(bool)

    intersection = np.logical_and(pred, gt).sum()
    union = np.logical_or(pred, gt).sum()

    if union == 0:
        return 1.0

    return intersection / (union + 1e-8)


def pointing_game_score(grayscale_cam, gt):

    y, x = np.unravel_index(
        np.argmax(grayscale_cam),
        grayscale_cam.shape
    )

    return int(gt[y, x] == 1)


def centroid_distance(pred, gt):

    pred_points = np.argwhere(pred > 0)
    gt_points = np.argwhere(gt > 0)

    if len(pred_points) == 0:
        return np.nan

    if len(gt_points) == 0:
        return np.nan

    pred_centroid = pred_points.mean(axis=0)
    gt_centroid = gt_points.mean(axis=0)

    return float(
        np.linalg.norm(
            pred_centroid - gt_centroid
        )
    )


# ============================================================
# 8. GRAD-CAM MASK
# ============================================================

def get_gradcam_mask(
    input_tensor,
    predicted_class,
    threshold=0.55
):

    targets = [
        ClassifierOutputTarget(predicted_class)
    ]

    grayscale_cam = cam(
        input_tensor=input_tensor,
        targets=targets
    )[0]

    # --------------------------------------------
    # Threshold
    # --------------------------------------------

    binary = (
        grayscale_cam > threshold
    ).astype(np.uint8)

    # --------------------------------------------
    # Connected components
    # --------------------------------------------

    num_labels, labels, stats, centroids = (
        cv2.connectedComponentsWithStats(
            binary,
            connectivity=8
        )
    )

    clean = np.zeros_like(binary)

    if num_labels > 1:

        largest = (
            1 +
            np.argmax(
                stats[1:, cv2.CC_STAT_AREA]
            )
        )

        clean[labels == largest] = 1

    return grayscale_cam, clean


# ============================================================
# 9. TRANSFORM CHECK
# ============================================================

print("=" * 70)
print("CHECKING SPATIAL TRANSFORM")
print("=" * 70)


def inspect_transform(transform):

    print("Transform:", transform)
    print()

    if isinstance(transform, transforms.Compose):

        for i, t in enumerate(transform.transforms):

            print(
                f"{i}: {type(t).__name__}"
            )

            if isinstance(
                t,
                transforms.Resize
            ):
                print(
                    "   Resize:",
                    t.size
                )

            elif isinstance(
                t,
                transforms.CenterCrop
            ):
                print(
                    "   CenterCrop:",
                    t.size
                )

            elif isinstance(
                t,
                transforms.RandomResizedCrop
            ):
                print(
                    "   WARNING: RandomResizedCrop detected"
                )

            elif isinstance(
                t,
                transforms.RandomCrop
            ):
                print(
                    "   WARNING: RandomCrop detected"
                )

    else:

        print(
            "Transform is not torchvision.Compose."
        )


inspect_transform(
    test_dataset.transform
)

print()


# ============================================================
# 10. CHECK FOR RANDOM SPATIAL TRANSFORM
# ============================================================

def has_random_spatial_transform(transform):

    if isinstance(transform, transforms.Compose):

        for t in transform.transforms:

            if isinstance(
                t,
                (
                    transforms.RandomResizedCrop,
                    transforms.RandomCrop,
                    transforms.RandomAffine,
                    transforms.RandomRotation,
                    transforms.RandomPerspective
                )
            ):

                return True

    return False


if has_random_spatial_transform(
    test_dataset.transform
):

    print("!" * 70)
    print("WARNING")
    print("Random spatial augmentation detected.")
    print(
        "GT mask cannot be safely aligned using simple resizing."
    )
    print(
        "Use a deterministic test transform before localization evaluation."
    )
    print("!" * 70)
    print()


