# ============================================================
# GRAD-CAM COMPONENT SELECTION CHECK
# BEFORE vs AFTER LARGEST CONNECTED COMPONENT
# ============================================================

import os
import cv2
import numpy as np
import matplotlib.pyplot as plt
import torch

from pytorch_grad_cam.utils.model_targets import ClassifierOutputTarget


# ============================================================
# SETTINGS
# ============================================================

THRESHOLD = 0.30
NUM_SAMPLES = 6


# ============================================================
# METRICS
# ============================================================

def dice_score(pred, gt):

    pred = pred.astype(bool)
    gt = gt.astype(bool)

    intersection = np.logical_and(
        pred,
        gt
    ).sum()

    denom = pred.sum() + gt.sum()

    if denom == 0:
        return 1.0

    return (
        2.0 * intersection /
        (denom + 1e-8)
    )


def iou_score(pred, gt):

    pred = pred.astype(bool)
    gt = gt.astype(bool)

    intersection = np.logical_and(
        pred,
        gt
    ).sum()

    union = np.logical_or(
        pred,
        gt
    ).sum()

    if union == 0:
        return 1.0

    return (
        intersection /
        (union + 1e-8)
    )


# ============================================================
# GT MASK EXTRACTION
# ============================================================

def extract_gt_mask(overlay_rgb):

    r = overlay_rgb[:, :, 0].astype(np.int16)
    g = overlay_rgb[:, :, 1].astype(np.int16)
    b = overlay_rgb[:, :, 2].astype(np.int16)

    colored = (
        ((r > g + 30) & (r > b + 30)) |
        ((b > r + 30) & (b > g + 30))
    )

    return colored.astype(np.uint8)


# ============================================================
# GET COMPONENTS
# ============================================================

def get_components(binary):

    num_labels, labels, stats, centroids = (
        cv2.connectedComponentsWithStats(
            binary,
            connectivity=8
        )
    )

    components = []

    for component_id in range(1, num_labels):

        area = stats[
            component_id,
            cv2.CC_STAT_AREA
        ]

        x = stats[
            component_id,
            cv2.CC_STAT_LEFT
        ]

        y = stats[
            component_id,
            cv2.CC_STAT_TOP
        ]

        w = stats[
            component_id,
            cv2.CC_STAT_WIDTH
        ]

        h = stats[
            component_id,
            cv2.CC_STAT_HEIGHT
        ]

        component_mask = (
            labels == component_id
        ).astype(np.uint8)

        components.append({

            "id": component_id,

            "area": int(area),

            "x": int(x),

            "y": int(y),

            "w": int(w),

            "h": int(h),

            "mask": component_mask
        })

    components.sort(
        key=lambda x: x["area"],
        reverse=True
    )

    return components


# ============================================================
# SELECT SAMPLE IMAGES
# ============================================================

sample_rows = matched_df.head(
    NUM_SAMPLES
).copy()


# ============================================================
# RESULTS
# ============================================================

component_results = []


# ============================================================
# VISUALIZATION
# ============================================================

fig, axes = plt.subplots(
    NUM_SAMPLES,
    6,
    figsize=(24, 4 * NUM_SAMPLES)
)

if NUM_SAMPLES == 1:
    axes = np.expand_dims(
        axes,
        axis=0
    )


for r, (_, row) in enumerate(
    sample_rows.iterrows()
):

    idx = int(
        row["index"]
    )

    label = str(
        row["label"]
    )

    overlay_path = str(
        row["overlay_path"]
    )

    # ========================================================
    # LOAD IMAGE
    # ========================================================

    image_tensor, true_label = (
        test_dataset[idx]
    )

    input_tensor = (
        image_tensor
        .unsqueeze(0)
        .to(device)
    )


    # ========================================================
    # MODEL PREDICTION
    # ========================================================

    with torch.no_grad():

        output = model(
            input_tensor
        )

    predicted_class = (
        output.argmax(
            dim=1
        ).item()
    )


    # ========================================================
    # GRAD-CAM
    # ========================================================

    grayscale_cam = cam(
        input_tensor=input_tensor,
        targets=[
            ClassifierOutputTarget(
                predicted_class
            )
        ]
    )[0]


    # ========================================================
    # THRESHOLD ONLY
    # ========================================================

    binary = (
        grayscale_cam > THRESHOLD
    ).astype(np.uint8)


    # ========================================================
    # CONNECTED COMPONENTS
    # ========================================================

    components = get_components(
        binary
    )


    # ========================================================
    # LARGEST COMPONENT
    # ========================================================

    largest_mask = np.zeros_like(
        binary
    )

    if len(components) > 0:

        largest_mask = components[
            0
        ]["mask"]


    # ========================================================
    # LOAD OVERLAY
    # ========================================================

    overlay_bgr = cv2.imread(
        overlay_path
    )

    overlay_rgb = cv2.cvtColor(
        overlay_bgr,
        cv2.COLOR_BGR2RGB
    )


    # ========================================================
    # GT MASK
    # ========================================================

    gt_original = extract_gt_mask(
        overlay_rgb
    )

    cam_h, cam_w = (
        grayscale_cam.shape
    )

    gt_mask = cv2.resize(
        gt_original,
        (cam_w, cam_h),
        interpolation=cv2.INTER_NEAREST
    )

    gt_mask = (
        gt_mask > 0
    ).astype(np.uint8)


    # ========================================================
    # METRICS BEFORE COMPONENT FILTERING
    # ========================================================

    dice_before = dice_score(
        binary,
        gt_mask
    )

    iou_before = iou_score(
        binary,
        gt_mask
    )


    # ========================================================
    # METRICS AFTER LARGEST COMPONENT
    # ========================================================

    dice_after = dice_score(
        largest_mask,
        gt_mask
    )

    iou_after = iou_score(
        largest_mask,
        gt_mask
    )


    # ========================================================
    # COMPONENT INFORMATION
    # ========================================================

    n_components = len(
        components
    )

    largest_area = (
        components[0]["area"]
        if n_components > 0
        else 0
    )

    second_area = (
        components[1]["area"]
        if n_components > 1
        else 0
    )


    # ========================================================
    # SAVE NUMERICAL RESULT
    # ========================================================

    component_results.append({

        "index": idx,

        "label": label,

        "threshold": THRESHOLD,

        "num_components":
            n_components,

        "largest_component_area":
            largest_area,

        "second_component_area":
            second_area,

        "dice_before":
            dice_before,

        "iou_before":
            iou_before,

        "dice_after":
            dice_after,

        "iou_after":
            iou_after
    })


    # ========================================================
    # DISPLAY IMAGE
    # ========================================================

    image = (
        image_tensor
        .detach()
        .cpu()
        .numpy()
    )

    if image.shape[0] == 3:

        image = np.transpose(
            image,
            (1, 2, 0)
        )

    image = (
        image - image.min()
    )

    image = (
        image /
        (image.max() + 1e-8)
    )

    image = cv2.resize(
        image,
        (cam_w, cam_h)
    )


    # ========================================================
    # 1. ORIGINAL
    # ========================================================

    axes[r, 0].imshow(
        image,
        cmap="gray"
    )

    axes[r, 0].set_title(
        f"{label}\nOriginal"
    )

    axes[r, 0].axis("off")


    # ========================================================
    # 2. GT
    # ========================================================

    axes[r, 1].imshow(
        gt_mask,
        cmap="gray"
    )

    axes[r, 1].set_title(
        "GT Lesion"
    )

    axes[r, 1].axis("off")


    # ========================================================
    # 3. RAW GRAD-CAM
    # ========================================================

    axes[r, 2].imshow(
        grayscale_cam,
        cmap="jet"
    )

    axes[r, 2].set_title(
        "Raw Grad-CAM"
    )

    axes[r, 2].axis("off")


    # ========================================================
    # 4. THRESHOLDED MASK
    # ========================================================

    axes[r, 3].imshow(
        binary,
        cmap="gray"
    )

    axes[r, 3].set_title(
        f"Threshold = {THRESHOLD}\n"
        f"Components = {n_components}"
    )

    axes[r, 3].axis("off")


    # ========================================================
    # 5. LARGEST COMPONENT
    # ========================================================

    axes[r, 4].imshow(
        largest_mask,
        cmap="gray"
    )

    axes[r, 4].set_title(
        f"Largest Component\n"
        f"Dice: {dice_after:.3f}"
    )

    axes[r, 4].axis("off")


    # ========================================================
    # 6. GT vs GRAD-CAM
    # ========================================================

    axes[r, 5].imshow(
        image,
        cmap="gray"
    )

    gt_display = np.ma.masked_where(
        gt_mask == 0,
        gt_mask
    )

    cam_display = np.ma.masked_where(
        largest_mask == 0,
        largest_mask
    )

    axes[r, 5].imshow(
        gt_display,
        cmap="Greens",
        alpha=0.5
    )

    axes[r, 5].imshow(
        cam_display,
        cmap="Reds",
        alpha=0.5
    )

    axes[r, 5].set_title(
        f"GT vs Largest CAM\n"
        f"Before Dice={dice_before:.3f}\n"
        f"After Dice={dice_after:.3f}"
    )

    axes[r, 5].axis("off")


plt.tight_layout()
plt.show()


# ============================================================
# NUMERICAL RESULTS
# ============================================================

component_df = pd.DataFrame(
    component_results
)

print("=" * 70)
print("COMPONENT ANALYSIS")
print("=" * 70)

display(
    component_df.round(4)
)


# ============================================================
# SUMMARY
# ============================================================

print("=" * 70)
print("SUMMARY")
print("=" * 70)

print(
    f"Mean Dice BEFORE largest component: "
    f"{component_df['dice_before'].mean():.4f}"
)

print(
    f"Mean Dice AFTER largest component:  "
    f"{component_df['dice_after'].mean():.4f}"
)

print()

print(
    f"Mean IoU BEFORE largest component: "
    f"{component_df['iou_before'].mean():.4f}"
)

print(
    f"Mean IoU AFTER largest component:  "
    f"{component_df['iou_after'].mean():.4f}"
)

print()

print(
    f"Mean number of components: "
    f"{component_df['num_components'].mean():.2f}"
)

