print("Overlay:", row["overlay_path"])


# ------------------------------------------------------------
# LOAD TEST IMAGE
# ------------------------------------------------------------

image_tensor, true_label = test_dataset[idx]

input_tensor = (
    image_tensor
    .unsqueeze(0)
    .to(device)
)


# ------------------------------------------------------------
# MODEL PREDICTION
# ------------------------------------------------------------

with torch.no_grad():
    output = model(input_tensor)

predicted_class = output.argmax(
    dim=1
).item()

print("True label:", true_label)
print("Predicted class:", predicted_class)


# ------------------------------------------------------------
# GRAD-CAM
# ------------------------------------------------------------

grayscale_cam = cam(
    input_tensor=input_tensor,
    targets=[
        ClassifierOutputTarget(
            predicted_class
        )
    ]
)[0]


print()
print("Grad-CAM shape:", grayscale_cam.shape)


# ------------------------------------------------------------
# LOAD OVERLAY
# ------------------------------------------------------------

overlay_bgr = cv2.imread(
    str(row["overlay_path"])
)

overlay_rgb = cv2.cvtColor(
    overlay_bgr,
    cv2.COLOR_BGR2RGB
)

print("Original overlay shape:", overlay_rgb.shape)


# ------------------------------------------------------------
# GT MASK
# ------------------------------------------------------------

gt_original = extract_gt_mask(
    overlay_rgb
)

print(
    "Original GT mask shape:",
    gt_original.shape
)

print(
    "Original GT lesion pixels:",
    gt_original.sum()
)


# ------------------------------------------------------------
# RESIZE GT TO CAM
# ------------------------------------------------------------

cam_h, cam_w = grayscale_cam.shape

gt_mask = cv2.resize(
    gt_original,
    (cam_w, cam_h),
    interpolation=cv2.INTER_NEAREST
)

gt_mask = (
    gt_mask > 0
).astype(np.uint8)

print(
    "Resized GT shape:",
    gt_mask.shape
)

print(
    "Resized GT lesion pixels:",
    gt_mask.sum()
)


# ------------------------------------------------------------
# THRESHOLD
# ------------------------------------------------------------

threshold = 0.30

binary = (
    grayscale_cam > threshold
).astype(np.uint8)

print(
    "Grad-CAM pixels after threshold:",
    binary.sum()
)


# ------------------------------------------------------------
# MAX CAM POINT
# ------------------------------------------------------------

cam_y, cam_x = np.unravel_index(
    np.argmax(grayscale_cam),
    grayscale_cam.shape
)

print()
print("Grad-CAM maximum point:")
print(
    "X =", cam_x,
    "Y =", cam_y
)

print(
    "Maximum CAM value:",
    grayscale_cam[cam_y, cam_x]
)

print(
    "Is maximum point inside GT?",
    bool(gt_mask[cam_y, cam_x])
)


# ------------------------------------------------------------
# GT CENTROID
# ------------------------------------------------------------

gt_points = np.argwhere(
    gt_mask > 0
)

if len(gt_points) > 0:

    gt_centroid_y, gt_centroid_x = (
        gt_points.mean(axis=0)
    )

    print()
    print("GT centroid:")
    print(
        "X =",
        gt_centroid_x
    )

    print(
        "Y =",
        gt_centroid_y
    )


# ------------------------------------------------------------
# CAM CENTROID
# ------------------------------------------------------------

cam_points = np.argwhere(
    binary > 0
)

if len(cam_points) > 0:

    cam_centroid_y, cam_centroid_x = (
        cam_points.mean(axis=0)
    )

    print()
    print("Grad-CAM centroid:")
    print(
        "X =",
        cam_centroid_x
    )

    print(
        "Y =",
        cam_centroid_y
    )


# ============================================================
# VISUALIZATION
# ============================================================

fig, axes = plt.subplots(
    1,
    5,
    figsize=(25, 5)
)


# ------------------------------------------------------------
# 1. ORIGINAL CT
# ------------------------------------------------------------

